CARDIO.register({"item":"234","meta":{"num":234,"short":"IC","title":"Insuffisance cardiaque de l'adulte","section":"IV","chapter":18,"pages":"455-490","sdd":[{"num":18,"label":"Découverte d'anomalies à l'auscultation cardiaque"},{"num":20,"label":"Découverte d'anomalies à l'auscultation pulmonaire"},{"num":21,"label":"Asthénie"},{"num":42,"label":"Hypertension artérielle"},{"num":50,"label":"Malaise / perte de connaissance"},{"num":54,"label":"Œdème localisé ou diffus"},{"num":159,"label":"Bradycardie"},{"num":160,"label":"Détresse respiratoire aiguë"},{"num":161,"label":"Douleur thoracique"},{"num":162,"label":"Dyspnée"},{"num":165,"label":"Palpitations"},{"num":166,"label":"Tachycardie"},{"num":178,"label":"Demande / prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":201,"label":"Dyskaliémie"},{"num":204,"label":"Élévation des enzymes cardiaques"},{"num":232,"label":"Demande d'explication d'un patient sur le déroulement, les risques et les bénéfices attendus d'un examen d'imagerie"},{"num":239,"label":"Explication préopératoire et recueil de consentement d'un geste invasif diagnostique ou thérapeutique"},{"num":248,"label":"Prescription et suivi d'un traitement par anticoagulant et/ou antiagrégant"},{"num":253,"label":"Prescrire des diurétiques"},{"num":271,"label":"Prescription et surveillance d'une voie d'abord vasculaire"},{"num":285,"label":"Consultation de suivi et éducation thérapeutique d'un patient avec antécédent cardiovasculaire"},{"num":287,"label":"Consultation de suivi et éducation thérapeutique d'un patient insuffisant cardiaque"},{"num":320,"label":"Prévention des maladies cardiovasculaires"},{"num":328,"label":"Annonce d'une maladie chronique"},{"num":352,"label":"Expliquer un traitement au patient (adulte / enfant / adolescent)"},{"num":354,"label":"Évaluation de l'observance thérapeutique"},{"num":355,"label":"Organisation de la sortie d'hospitalisation"}]},"objectives":[{"id":"234-obj-01","rank":"B","rubric":"Épidémiologie","title":"Épidémiologie de l'insuffisance cardiaque","desc":"Connaître l'épidémiologie de l'insuffisance cardiaque dans le contexte du vieillissement de la population et de l'amélioration du traitement des pathologies cardiovasculaires.","src":"p. 456"},{"id":"234-obj-02","rank":"A","rubric":"Définition","title":"Définition de l'insuffisance cardiaque (IC à FE diminuée ou à FE conservée)","desc":"Connaître la définition de l'insuffisance cardiaque.","src":"p. 456"},{"id":"234-obj-03","rank":"A","rubric":"Définition","title":"Savoir ce qu'est un œdème aigu pulmonaire (OAP) cardiogénique","desc":"Insuffisance cardiaque gauche responsable d'un œdème pulmonaire transsudatif.","src":"p. 456"},{"id":"234-obj-04","rank":"A","rubric":"Définition","title":"Connaître la définition du choc cardiogénique","desc":"Défaillance aiguë et sévère de la fonction cardiaque entraînant une altération profonde de la perfusion périphérique et une anoxie tissulaire.","src":"p. 456"},{"id":"234-obj-05","rank":"B","rubric":"Physiopathologie","title":"Physiopathologie de l'IC gauche et droite","desc":"IC gauche : débit, fraction d'éjection, remodelage, désynchronisation, arythmies. IC droite : savoir qu'elle est le plus souvent liée à une IC gauche ; connaître les conséquences de l'hypertension pulmonaire et de l'hypertension veineuse systémique.","src":"p. 456"},{"id":"234-obj-06","rank":"B","rubric":"Physiopathologie","title":"Différence entre OAP cardiogénique et OAP lésionnel","desc":"Connaître la différence entre œdème lésionnel et hydrostatique et l'implication immédiate d'un tel diagnostic.","src":"p. 456"},{"id":"234-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Diagnostics différentiels de l'œdème pulmonaire cardiogénique","desc":"Savoir rechercher les arguments pour les principaux diagnostics différentiels : pneumonie, exacerbation de BPCO, asthme.","src":"p. 456"},{"id":"234-obj-08","rank":"B","rubric":"Diagnostic positif","title":"IC à FE diminuée ou à FE conservée","desc":"Connaître les valeurs seuils de FEVG.","src":"p. 456"},{"id":"234-obj-09","rank":"A","rubric":"Diagnostic positif","title":"Modalités du diagnostic d'une IC","desc":"Connaître les principaux signes fonctionnels, la classe NYHA, les signes physiques et les différents tableaux cliniques.","src":"p. 456"},{"id":"234-obj-10","rank":"B","rubric":"Examens complémentaires","title":"Principaux examens du bilan d'une IC","desc":"Savoir prescrire ECG, bilan biologique, et connaître les indications de la coronarographie ou du coroscanner.","src":"p. 456"},{"id":"234-obj-11","rank":"A","rubric":"Examens complémentaires","title":"Examens complémentaires à réaliser en urgence dans l'OAP cardiogénique","desc":"Savoir demander : ECG, gaz du sang artériels, radiographie thoracique, bilan biologique, dosage des peptides natriurétiques, troponine, échocardiographie.","src":"p. 456"},{"id":"234-obj-12","rank":"B","rubric":"Examens complémentaires","title":"Intérêt et limites du BNP / NT-proBNP","desc":"Connaître l'intérêt et les limites du BNP ou du NT-proBNP pour le diagnostic et le suivi.","src":"p. 456"},{"id":"234-obj-13","rank":"B","rubric":"Examens complémentaires","title":"Valeur de l'échocardiographie transthoracique","desc":"Connaître la valeur de l'ETT dans le diagnostic positif et étiologique.","src":"p. 456"},{"id":"234-obj-14","rank":"A","rubric":"Examens complémentaires","title":"Sémiologie radiographique de l'OAP d'origine hémodynamique","desc":"Syndrome alvéolo-interstitiel gravitodépendant : opacités floconneuses des bases, lignes de Kerley, redistribution vasculaire, épanchements pleuraux ; opacités périhilaires si survenue brutale.","src":"p. 456"},{"id":"234-obj-15","rank":"A","rubric":"Contenu multimédia","title":"Radiographie thoracique d'un OAP d'origine hémodynamique","desc":"","src":"p. 457"},{"id":"234-obj-16","rank":"A","rubric":"Étiologies","title":"Principales étiologies de l'IC","desc":"Connaître les principales causes de l'IC gauche : cardiopathie ischémique, HTA, valvulopathies, cardiomyopathies, causes rythmiques.","src":"p. 457"},{"id":"234-obj-17","rank":"A","rubric":"Identifier une urgence","title":"Modalités du diagnostic d'un OAP cardiogénique","desc":"Savoir reconnaître un OAP devant une détresse respiratoire aiguë (dyspnée, orthopnée, râles crépitants, tachycardie, galop gauche, etc.) et en reconnaître les signes de gravité.","src":"p. 457"},{"id":"234-obj-18","rank":"A","rubric":"Prise en charge","title":"Traitement d'urgence de l'OAP cardiogénique","desc":"Savoir prescrire le traitement symptomatique : diurétiques de l'anse, dérivés nitrés, oxygénothérapie.","src":"p. 457"},{"id":"234-obj-19","rank":"A","rubric":"Prise en charge","title":"Mesures hygiénodiététiques, éducation thérapeutique et réadaptation","desc":"Principes du régime pauvre en sel, importance de l'observance du traitement, connaissance des signes d'alerte.","src":"p. 457"},{"id":"234-obj-20","rank":"A","rubric":"Prise en charge","title":"Classes médicamenteuses du traitement de l'IC à FE diminuée","desc":"Connaître les principales classes des cardioprotecteurs, l'utilisation des diurétiques de l'anse et thiazidiques, la réadaptation cardiaque.","src":"p. 457"},{"id":"234-obj-21","rank":"B","rubric":"Suivi et/ou pronostic","title":"Principales complications de l'IC et leur prise en charge","desc":"Décès, décompensations, troubles du rythme, embolie, hypotension, insuffisance rénale.","src":"p. 457"},{"id":"234-obj-22","rank":"A","rubric":"Identifier une urgence","title":"Diagnostiquer un choc cardiogénique","desc":"Pression artérielle, perfusion périphérique, oligurie, conscience.","src":"p. 457"},{"id":"234-obj-23","rank":"B","rubric":"Prise en charge","title":"Principes du traitement du choc cardiogénique","desc":"Connaître les principes du traitement inotrope et diurétique.","src":"p. 457"}],"course":{"sections":[{"id":"234-sec-01","title":"Définition et épidémiologie","rank":"A","objectives":["234-obj-01","234-obj-02"],"content":"**L'insuffisance cardiaque (IC)** est le point d'arrivée possible de n'importe quelle cardiopathie négligée ou insuffisamment traitée.\n\n- **Définition physiopathologique** : incapacité du cœur à assurer un débit suffisant pour les besoins de l'organisme, et/ou impossibilité de fonctionner avec des pressions de remplissage normales.\n- **Définition clinique** : syndrome associant des **symptômes** (dyspnée, fatigue, prise de poids, œdèmes) et des **signes physiques**, en rapport avec un trouble cardiaque (myocardique, valvulaire, péricardique, rythmique ou de conduction) responsable d'un débit insuffisant et/ou de pressions intracardiaques élevées et/ou d'une rétention hydrosodée.\n\n> Le diagnostic clinique est difficile : les symptômes manquent de spécificité, les signes physiques manquent de sensibilité (la rétention hydrosodée peut régresser vite sous traitement). Une phase de dysfonction cardiaque asymptomatique précède souvent l'apparition des symptômes ; la dépister permet d'améliorer le pronostic.\n\n**[B] Épidémiologie** : prévalence dans la population générale estimée à 1-2 %, en constante hausse du fait du vieillissement et de l'amélioration de la prise en charge cardiovasculaire, alors que l'incidence ajustée sur l'âge tend, elle, à diminuer. L'âge moyen au diagnostic se situe entre 75 et 80 ans en Europe.","keyPoints":["L'IC associe toujours symptômes + signes cliniques + anomalie cardiaque sous-jacente.","Les signes physiques peuvent disparaître rapidement sous traitement : leur absence n'élimine pas l'IC.","Une dysfonction cardiaque asymptomatique peut précéder l'IC de plusieurs années : son dépistage améliore le pronostic.","Prévalence : 1-2 % de la population générale ; âge moyen au diagnostic 75-80 ans."],"pitfalls":["Ne pas écarter le diagnostic d'IC devant un examen clinique pauvre : la sensibilité des signes physiques est faible."],"src":"p. 458"},{"id":"234-sec-02","title":"Physiopathologie","rank":"B","objectives":["234-obj-05","234-obj-06"],"content":"**Rappels** : débit cardiaque (DC) = volume d'éjection systolique (VES) × fréquence cardiaque (FC). Le VES dépend de la précharge, de la postcharge et de l'inotropie ; la fraction d'éjection (FE) = VES/volume télédiastolique (VTD).\n\n**Deux conséquences** d'une pompe défaillante : chute (ou incapacité d'augmentation) du débit, et élévation des pressions de remplissage qui se transmettent en amont (oreillette, veines et capillaires pulmonaires côté gauche ; oreillette droite et circulation veineuse systémique côté droit).\n\n**Mécanismes compensateurs :**\n- *Cardiaques* : remodelage (dilatation excentrique après perte de contractilité, hypertrophie concentrique en réponse à une surcharge de pression selon la loi de Laplace), loi de Starling, tachycardie réflexe.\n- *Extracardiaques* : vasoconstriction sympathique et rénine-angiotensine (inhomogène, épargnant cerveau et coronaires), rétention hydrosodée (majore la précharge), activation neurohormonale globale.\n- Chacun de ces mécanismes a un **revers délétère** (travail cardiaque accru, rigidité pariétale, congestion, effets proarythmiques et toxiques directs des catécholamines).\n\n**Désynchronisation** : un trouble de conduction (typiquement bloc de branche gauche) fait perdre la contraction synchrone des parois et aggrave l'IC.\n\n**FE diminuée vs préservée** : IC à FE diminuée (< 40 %) = défaut de contraction avec dilatation du VG ; IC à FE préservée (> 50 %) = trouble du remplissage sur VG non dilaté, souvent épaissi et fibrosé ([B] forme légèrement diminuée : 41-49 %, proche du profil « FE diminuée »).\n\n**Arythmies** : la FA est favorisée par la dilatation atriale et aggrave l'IC (perte de la systole atriale, risque d'AVC) ; les arythmies ventriculaires, favorisées par la fibrose et les anomalies calciques, sont la première cause de mort subite dans l'IC.","keyPoints":["DC = VES × FC ; FE = VES / VTD.","Toute compensation cardiaque ou périphérique a un coût délétère à long terme.","La désynchronisation par bloc de branche gauche aggrave l'IC et justifie la resynchronisation.","IC à FE diminuée < 40 %, légèrement diminuée 41-49 %, préservée > 50 %.","La fibrillation atriale et les troubles du rythme ventriculaire sont fréquents et aggravent le pronostic."],"pitfalls":["Ne pas confondre le mécanisme compensateur (utile à court terme) et son effet délétère à long terme."],"src":"p. 458-461"},{"id":"234-sec-03","title":"Signes cliniques","rank":"A","objectives":["234-obj-09"],"content":"**Signes fonctionnels respiratoires**\n- **Dyspnée d'effort** : fréquente, peu spécifique, sévérité graduée par la **classification NYHA** :\n\n| Stade | Description |\n|---|---|\n| I | Aucune gêne dans la vie courante |\n| II | Gêne pour des efforts importants habituels (marche rapide, côte, > 2 étages) |\n| III | Gêne pour des efforts peu intenses (terrain plat, < 2 étages) |\n| IV | Gêne permanente, de repos ou pour les efforts minimes |\n\n- **Orthopnée** (plus spécifique) et **dyspnée paroxystique nocturne** (très spécifique, réveille le patient).\n- Formes trompeuses : asthme cardiaque (bradypnée expiratoire sifflante), toux d'effort ou de décubitus, hémoptysies (traduisent l'hypertension veineuse pulmonaire).\n\n**Autres symptômes** : fatigue, prise de poids avec œdèmes, faiblesse musculaire (myopathie associée possible dans les CMD), palpitations ; aux stades sévères : Cheyne-Stokes, confusion (bas débit cérébral), troubles digestifs.\n\n**Signes d'IC droite** : hépatalgie d'effort puis de repos.\n\n**Signes physiques**\n- *Cardiaques* : choc de pointe dévié, tachycardie (souvent absente sous bêtabloquant), galop B3, éclat de B2 pulmonaire, souffle d'IM/IT fonctionnelle ou de valvulopathie organique.\n- *Pulmonaires* : râles crépitants bilatéraux, épanchement pleural (transsudatif si protides < 30 g/L).\n- *Artériels* : pouls rapide, PAS basse (< 100 mmHg) = signe de gravité ; PAS élevée possible en cas d'IC hypertensive.\n- *[A] Signes droits* : turgescence jugulaire (très spécifique), reflux hépatojugulaire, hépatomégalie ferme douloureuse, œdèmes déclives mous blancs indolores prenant le godet, ascite (souvent tardive).\n- Stade très avancé : pouls alternant, oligurie, cachexie.","keyPoints":["La NYHA classe la dyspnée d'effort en 4 stades et reflète la tolérance fonctionnelle.","Orthopnée et dyspnée paroxystique nocturne sont plus spécifiques que la simple dyspnée d'effort.","L'examen clinique peut être pauvre sous traitement : l'absence de signes ne récuse pas l'IC.","Turgescence jugulaire et reflux hépatojugulaire sont les signes les plus spécifiques d'IC droite.","PAS < 100 mmHg est un signe de gravité, sauf en cas d'IC d'origine hypertensive."],"pitfalls":["L'asthme cardiaque peut être pris à tort pour un asthme bronchique.","Une PAS élevée n'élimine pas une IC aiguë en poussée hypertensive."],"src":"p. 461-464"},{"id":"234-sec-04","title":"Examens complémentaires","rank":"A","objectives":["234-obj-10","234-obj-11","234-obj-12","234-obj-13","234-obj-14","234-obj-15"],"content":"**ECG** [B] : peu contributif au diagnostic positif, mais oriente vers une étiologie (séquelle d'infarctus, arythmie) ; un **BBG avec QRS > 120 ms** a des implications thérapeutiques majeures (resynchronisation).\n\n**Radiographie thoracique** : évalue le retentissement pleuropulmonaire. Cardiomégalie si rapport cardiothoracique **> 0,5** (peut manquer, notamment en cas d'IC à FE préservée). Signes de stase, par gravité croissante : redistribution vasculaire vers les sommets → œdème interstitiel (lignes B de Kerley) → œdème alvéolaire bilatéral « en ailes de papillon » ; épanchements pleuraux possibles.\n\n**[A] BNP / NT-proBNP** : dosage de 1re intention, bonne valeur prédictive négative.\n\n| Situation | Seuil d'exclusion |\n|---|---|\n| Dyspnée aiguë | BNP < 100 pg/mL ou NT-proBNP < 300 pg/mL |\n| Présentation non aiguë | BNP < 35 pg/mL ou NT-proBNP < 125 pg/mL |\n\nEn cas de dyspnée aiguë, des taux très élevés orientent vers l'origine cardiaque, avec des seuils qui augmentent avec l'âge (NT-proBNP > 450 avant 50 ans, > 900 de 50 à 75 ans, > 1 800 pg/mL au-delà). Âge, insuffisance rénale et FA élèvent ces marqueurs ; l'obésité les abaisse.\n\n**[B] Échocardiographie transthoracique (ETT)** : examen clé, couplée au doppler. Elle catégorise l'IC selon la FEVG (< 40, 41-49, > 50 %), mesure les volumes du VG, explore le VD, les atriums, les valves, estime les pressions de remplissage et peut orienter vers une étiologie (trouble segmentaire, valvulopathie, hypertrophie).\n\n**[B] Biologie standard** : natrémie, kaliémie, créatininémie, BNP/NT-proBNP, glycémie à jeun et HbA1c, bilan lipidique, bilan hépatique, TSHus, NFS, ferritinémie et coefficient de saturation de la transferrine.\n\n**Autres examens** : coroscanner en 1re intention si probabilité coronarienne faible/intermédiaire ; coronarographie si angor, probabilité intermédiaire/haute ou ischémie documentée avec projet de revascularisation ; IRM cardiaque (étiologie, viabilité, pronostic) ; scintigraphie (FE, ischémie, amylose) ; holter-ECG ; épreuve d'effort avec VO2 (valeur pronostique) ; cathétérisme droit (pressions, débit par thermodilution).","keyPoints":["BNP/NT-proBNP ont surtout une excellente valeur prédictive négative ; seuils différents selon présentation aiguë ou non.","L'ETT est l'examen clé : elle catégorise la FEVG et oriente vers une étiologie.","RCT > 0,5 = cardiomégalie, mais son absence n'élimine pas une IC à FE préservée.","Un BBG avec QRS > 120 ms sur l'ECG a des implications thérapeutiques (resynchronisation).","Le coroscanner est préféré chez le sujet à probabilité coronarienne faible ou intermédiaire."],"pitfalls":["Ne pas retarder le traitement de l'OAP en attendant les résultats des examens complémentaires.","Des peptides natriurétiques bas au cours d'une dyspnée aiguë doivent faire reconsidérer l'origine cardiaque."],"src":"p. 463-469"},{"id":"234-sec-05","title":"Étiologies de l'insuffisance cardiaque","rank":"A","objectives":["234-obj-16"],"content":"**Cardiopathies ischémiques** : première cause d'IC aujourd'hui. Perte de myocytes fonctionnels et fibrose post-infarctus, ou altération de la FE liée à une ischémie chronique parfois réversible après revascularisation (viabilité).\n\n**HTA** : facteur direct (hypertrophie et fibrose → dysfonction diastolique, surtout à FE préservée chez le sujet âgé) ou indirect (favorise l'athérome coronaire) ; peut aussi conduire à une FE abaissée par élévation chronique de la postcharge.\n\n**Cardiomyopathies** (diagnostic d'élimination après cause ischémique, valvulaire, congénitale, HTA) :\n- *Dilatées (CMD)* : 1re cause d'IC/transplantation chez le sujet jeune. Origines : familiale/génétique (~25 %, le plus souvent autosomique dominante), toxique (alcool, cocaïne), infectieuse (myocardites virales/bactériennes, Chagas), auto-immune, endocrinienne, nutritionnelle, péripartum, médicamenteuse/chimiothérapie (anthracyclines, trastuzumab), takotsubo ; idiopathique dans un nombre non négligeable de cas.\n- *Hypertrophiques (CMH)* : hypertrophie asymétrique prédominant sur le septum, cavité normale ou petite, FE conservée ; obstruction sous-aortique dans environ 25 % des cas ; le plus souvent génétique (gènes du sarcomère) ; risque de mort subite (1re cause chez le jeune athlète), d'IC ou de FA.\n- *Restrictives* : rares, dominées par l'amylose cardiaque (parois épaissies rigides, remplissage difficile, pronostic sévère).\n\n**Valvulopathies gauches** : IM, IA, RM, RA — toutes peuvent aboutir à l'IC ; le RM peut donner un OAP sans atteinte du VG.\n\n**Troubles du rythme/conduction** : tachycardie rapide prolongée (FA) → tachycardiomyopathie ; extrasystolie fréquente ; bradycardie extrême ; le traitement du trouble du rythme peut guérir l'IC.\n\n**Péricarde** : épanchement abondant, tamponnade, péricardite chronique constrictive.\n\n**IC droite isolée** : pathologies pulmonaires (cœur pulmonaire chronique ou aigu par EP), HTAP, dysplasie arythmogène du VD, atteintes tricuspidiennes isolées, infarctus du VD, péricardite constrictive.\n\n**IC à débit augmenté** : anémie chronique, fistules artérioveineuses, hyperthyroïdie, béribéri (carence en thiamine), maladie de Paget.","keyPoints":["La cardiopathie ischémique est la 1re cause globale d'IC ; la CMD est la 1re cause chez le sujet jeune.","L'HTA agit par hypertrophie/fibrose (FE préservée) ou par athérome coronaire favorisé.","Le diagnostic de cardiomyopathie suppose d'avoir éliminé cause ischémique, valvulaire, congénitale et HTA.","Toute valvulopathie gauche non traitée à temps peut se compliquer d'IC.","Il existe des étiologies d'IC droite isolée, sans passer par une IC gauche."],"pitfalls":["Ne pas oublier de rechercher une cause ischémique par coronarographie ou coroscanner devant toute FEVG abaissée."],"src":"p. 469-472"},{"id":"234-sec-06","title":"L'œdème aigu pulmonaire cardiogénique","rank":"A","objectives":["234-obj-03","234-obj-07","234-obj-17"],"content":"**Définition** : forme la plus typique de l'IC aiguë, grande urgence cardiovasculaire. Inondation alvéolaire par transsudât lié à l'élévation brutale de la pression capillaire pulmonaire.\n\n**Tableau clinique** : polypnée avec orthopnée forcée, sueurs, cyanose, grésillement laryngé, toux avec expectoration mousseuse rosée. Tirage possible. Auscultation : râles crépitants qui remontent d'autant plus haut que le tableau est sévère (image de la « marée montante »). Une poussée hypertensive peut accompagner l'épisode.\n\n**Bilan sans retarder le traitement** : BNP/NT-proBNP (des valeurs basses doivent faire reconsidérer l'origine cardiogénique), troponine (une élévation modérée n'implique pas forcément un syndrome coronarien aigu), radiographie de thorax (opacités périhilaires floues bilatérales), gaz du sang (hypoxie-hypocapnie), échocardiographie (cardiopathie sous-jacente, FEVG, pressions).\n\n**Diagnostics différentiels** [A] à évoquer systématiquement devant une dyspnée aiguë :\n- pneumopathie infectieuse (fièvre, foyer localisé, opacité systématisée, peptides natriurétiques normaux) ;\n- embolie pulmonaire (contexte à risque, auscultation souvent normale) ;\n- exacerbation de BPCO (antécédents, ronchi/sibilants, expectoration) ;\n- crise d'asthme (antécédents, dyspnée expiratoire sifflante).\n\n**Formes moins typiques** [B] : aggravation progressive de la dyspnée avec signes congestifs, tableau d'IC droite isolée, ou décompensation compliquant un syndrome coronarien aigu (double prise en charge nécessaire).\n\n**Facteurs déclenchants** [A] à rechercher systématiquement, en premier lieu une rupture thérapeutique ou d'observance du régime sans sel : écarts de régime, surinfection bronchique, trouble du rythme (FA), anémie, embolie pulmonaire, dysthyroïdie (amiodarone), causes iatrogènes (antiarythmiques, bêtabloquants, AINS, inhibiteurs calciques bradycardisants, baisse excessive de la précharge), poussée hypertensive, syndrome coronarien aigu.","keyPoints":["L'OAP est une urgence cardiovasculaire majeure ne devant pas attendre les examens complémentaires pour être traité.","La « marée montante des râles crépitants » traduit la sévérité de l'inondation alvéolaire.","4 diagnostics différentiels à éliminer systématiquement : pneumopathie, EP, BPCO, asthme.","Le premier facteur déclenchant à rechercher est une rupture de traitement ou de régime sans sel."],"pitfalls":["Une troponine légèrement augmentée pendant l'OAP n'affirme pas un syndrome coronarien aigu associé.","Un BNP bas au cours d'une dyspnée aiguë doit faire douter du diagnostic d'OAP cardiogénique."],"src":"p. 456, 472-473"},{"id":"234-sec-07","title":"Choc cardiogénique","rank":"A","objectives":["234-obj-04","234-obj-22"],"content":"**Définition** : tableau ultime de défaillance cardiaque aiguë et sévère avec effondrement du débit, entraînant une hypoperfusion tissulaire profonde et une anoxie ; pronostic très défavorable.\n\n**Diagnostic** [A], à évoquer devant l'association de :\n- pression artérielle systolique **< 90 mmHg**, ou chute > 30 mmHg par rapport à la valeur de base, maintenue au moins 30 minutes ;\n- signes d'hypoperfusion périphérique : extrémités froides, cyanosées, marbrées ;\n- oligurie **< 20 mL/h** ;\n- sueurs ;\n- altération de la conscience (agitation, confusion) ;\n- diminution du débit cardiaque mesuré à l'échocardiographie.\n\n> Le choc cardiogénique associe donc une **PAS effondrée**, des **signes de mauvaise perfusion d'organe** (peau, rein, cerveau) et une **preuve échographique** de bas débit.\n\nC'est le tableau ultime d'une insuffisance cardiaque aiguë : il peut compliquer un OAP réfractaire au traitement médical, un infarctus étendu ou une complication mécanique d'un syndrome coronarien aigu. Le pronostic dépend étroitement de la rapidité de la prise en charge et de la possibilité de traiter une cause curable sous-jacente.","keyPoints":["PAS < 90 mmHg (ou chute > 30 mmHg pendant ≥ 30 min) est le critère tensionnel du choc cardiogénique.","Oligurie < 20 mL/h et marbrures traduisent l'hypoperfusion périphérique.","L'altération de la conscience est un signe de gravité à rechercher systématiquement.","Le pronostic du choc cardiogénique reste sombre malgré la prise en charge."],"pitfalls":["Ne pas se limiter au chiffre de PAS : rechercher aussi les signes périphériques d'hypoperfusion."],"src":"p. 456, 473"},{"id":"234-sec-08","title":"IC chronique et IC à fraction d'éjection préservée","rank":"A","objectives":["234-obj-08"],"content":"**IC chronique** : état du patient en dehors d'une décompensation aiguë. Le patient est ambulatoire, suit un traitement oral, avec une gêne fonctionnelle variable selon la sévérité de la maladie.\n\n**IC à fraction d'éjection préservée (FEVG > 50 %)** : représente au moins la moitié des cas d'IC, surtout chez la femme et le sujet âgé, volontiers associée à l'HTA et à l'obésité. Le VG n'est en général pas dilaté mais souvent épaissi et fibrosé, ce qui gêne son remplissage.\n\n**Diagnostic**, qui repose sur la réunion de plusieurs éléments :\n- symptômes et/ou signes d'IC ;\n- fonction systolique normale à l'échographie (FEVG > 50 %), en l'absence de valvulopathie significative, de trouble du rythme/conduction ou d'atteinte péricardique ;\n- élévation du BNP ou du NT-proBNP ;\n- argument pour des pressions de remplissage élevées, une hypertrophie ventriculaire gauche (masse VG indexée > 115 g/m² chez l'homme, > 95 g/m² chez la femme) ou une dilatation de l'atrium gauche (volume indexé > 34 mL/m²).\n\n**[B] FE légèrement diminuée (41-49 %)** : profil intermédiaire, plus proche de l'IC à FE diminuée sur le plan thérapeutique.","keyPoints":["L'IC à FE préservée (FEVG > 50 %) représente au moins 50 % des IC, surtout chez la femme âgée.","Son diagnostic combine symptômes, FEVG normale, BNP élevé et argument de trouble du remplissage (HVG, dilatation de l'OG).","La FE légèrement diminuée (41-49 %) se comporte cliniquement comme l'IC à FE diminuée."],"pitfalls":["Ne pas éliminer une IC à FE préservée uniquement parce que la silhouette cardiaque est normale à la radiographie."],"src":"p. 473-474"},{"id":"234-sec-09","title":"Évolution, complications et pronostic","rank":"B","objectives":["234-obj-21"],"content":"**Histoire naturelle** [B] : le délai entre l'agression cardiaque initiale et les premiers signes d'IC est très variable, de quelques minutes (infarctus étendu, rupture de cordage, endocardite) à plusieurs années (HTA). Une phase asymptomatique de remodelage précède souvent la maladie déclarée ; l'évolution alterne ensuite phases stables et poussées aiguës déclenchées par des facteurs favorisants. Sous traitement de la cause, un remodelage inverse avec amélioration, voire normalisation de la fonction cardiaque, est possible.\n\n**Complications principales** :\n- **décès** : mortalité élevée, environ **50 % à 5 ans**, pouvant atteindre 40-50 % par an en classe NYHA IV, le plus souvent par mort subite rythmique ou par IC réfractaire ;\n- épisodes de décompensation nécessitant une hospitalisation pour diurétiques IV ou inotropes ; l'IC est l'une des toutes premières causes d'hospitalisation après 65 ans ;\n- troubles du rythme ventriculaires ou supraventriculaires (FA) ;\n- complications thromboemboliques (AVC sur thrombus intracavitaire, embolie pulmonaire) ;\n- hypotension artérielle, parfois majorée par les traitements ;\n- troubles hydroélectrolytiques (dyskaliémie, hyponatrémie), insuffisance rénale ;\n- anémie, carence martiale, syndrome d'apnées du sommeil.\n\n**Facteurs pronostiques défavorables** : NYHA III-IV, hospitalisations répétées, étiologie ischémique, hypotension, tachycardie, arythmies ventriculaires ; FE basse, débit bas, pressions pulmonaires élevées ; QRS > 120 ms (BBG) ; hyponatrémie, BNP/NT-proBNP élevé ; pic de VO2 abaissé à l'effort.\n\n**Comorbidités** à toujours rechercher et traiter (elles aggravent le pronostic et compliquent la tolérance des traitements) : HTA, diabète, obésité, pathologies respiratoires, coronaropathie, insuffisance rénale, dyskaliémies, goutte, troubles du sommeil, carence martiale, anémie, troubles cognitifs, AVC, troubles de l'humeur, dénutrition, sarcopénie, fragilité.","keyPoints":["La mortalité de l'IC avoisine 50 % à 5 ans, et jusqu'à 40-50 % par an au stade NYHA IV.","La mort subite rythmique et l'IC réfractaire sont les deux principaux mécanismes de décès.","Un remodelage inverse est possible si la cause de l'IC est traitée efficacement.","Les comorbidités doivent systématiquement être recherchées et prises en charge."],"pitfalls":["Ne pas négliger le dépistage et le traitement des comorbidités, qui conditionnent le pronostic autant que l'IC elle-même."],"src":"p. 474-476"},{"id":"234-sec-10","title":"Traitement de fond de l'IC à FE diminuée : mesures générales et médicaments","rank":"A","objectives":["234-obj-19","234-obj-20"],"content":"**Prévention/traitement étiologique** : contrôle de l'HTA, correction des valvulopathies, statines si risque élevé, gliflozines privilégiées chez le diabétique à haut risque cardiovasculaire, reperfusion précoce de l'infarctus, éviction des toxiques, surveillance des chimiothérapies cardiotoxiques, contrôle des arythmies.\n\n**Mesures hygiénodiététiques** [A] : régime pauvre en sel (5-6 g/j), pesée régulière (consulter si +2-3 kg en 2-3 jours), poursuite d'une activité physique régulière (le repos strict est délétère), sevrage tabagique impératif, réduction de l'alcool (arrêt total en cas de CMD alcoolique), vaccinations (grippe, Covid-19, pneumocoque), adaptation professionnelle (éviction des efforts physiques lourds et des métiers à risque), contraception adaptée en cas d'IC sévère.\n\n**Les 4 classes qui réduisent mortalité et hospitalisations dans l'IC à FE < 40 %** (recommandation I, A ; même logique mais preuve moindre entre 41 et 49 %) :\n\n| Classe | Points clés |\n|---|---|\n| IEC (ou ARA2/sacubitril-valsartan) | Débuter à faible dose, viser les doses des essais (ex. ramipril 10 mg) ; surveiller PA, créatininémie, kaliémie à 1 semaine puis à chaque palier ; CI : sténose bilatérale des artères rénales, angio-œdème, grossesse, hyperkaliémie |\n| Bêtabloquants (carvédilol, métoprolol, bisoprolol, nébivolol) | Introduction à distance d'une poussée, chez un patient stabilisé, à 1/8e de la dose cible puis paliers hebdomadaires (ex. carvédilol 3,125 mg ×2/j → 25 mg ×2/j ; bisoprolol 1,25 mg/j → 10 mg/j) ; CI : asthme/BPCO sévère, bradycardie ou hypotension symptomatique, BAV 2-3 |\n| Antialdostérones (spironolactone, éplérénone) | NYHA II-IV ; risque d'hyperkaliémie et d'insuffisance rénale, surtout associés à un IEC ; effets indésirables de la spironolactone : gynécomastie, impuissance |\n| Gliflozines (dapagliflozine, empagliflozine) | Efficaces quel que soit le statut diabétique ; peu d'effet hypotenseur ; risques : infections génitales, acidocétose chez le diabétique |\n\n**Diurétiques de l'anse** (furosémide) : traitement symptomatique de la rétention hydrosodée, dose adaptée aux apports sodés (20 mg/j à 1 g/j selon la sévérité) ; **thiazidiques** réservés aux formes résistantes, en association.\n\n**2e intention** : **ivabradine** [B] (rythme sinusal, FC > 70-75/min malgré bêtabloquant) réduit les hospitalisations ; **digoxine** (effet neutre sur la survie, réservée aux formes résistantes ou à la FA) ; **dérivés nitrés** en traitement d'appoint.\n\n**Associés parfois** : amiodarone [A] (seul antiarythmique utilisable dans l'IC à FE diminuée, sans bénéfice de mortalité démontré), antiagrégants/anticoagulants selon l'étiologie ou la FA (scores CHA2DS2-VA et HAS-BLED).\n\n**Contre-indiqués** : vérapamil et diltiazem (effet inotrope négatif), antiarythmiques de classe I (flécaïnide), AINS (risque de rétention hydrosodée) ; les dihydropyridines (amlodipine, félodipine) sont neutres et utilisables si une indication associée existe.","keyPoints":["4 classes réduisent la mortalité dans l'IC à FE diminuée : bloqueurs du SRA, bêtabloquants, antialdostérones, gliflozines.","Les bêtabloquants se débutent à très faible dose, chez un patient stabilisé, jamais en pleine poussée aiguë.","Les diurétiques de l'anse traitent la congestion mais n'ont pas d'effet démontré sur la mortalité.","Vérapamil, diltiazem, flécaïnide et AINS sont contre-indiqués dans l'IC à FE diminuée.","Le régime pauvre en sel (5-6 g/j) et la surveillance du poids restent des piliers du traitement."],"pitfalls":["Introduire un bêtabloquant en pleine décompensation aiguë est une faute.","Associer IEC et antialdostérone d'emblée expose à l'hyperkaliémie.","Le repos strict est délétère : il favorise le déconditionnement physique."],"src":"p. 476-481"},{"id":"234-sec-11","title":"Traitement électrique, IM percutanée et IC terminale","rank":"B","objectives":[],"content":"**Resynchronisation par stimulateur biventriculaire (CRT)** [B] : sondes en atrium droit, ventricule droit et paroi latérale du VG (via le sinus coronaire) pour restaurer une contraction synchrone. Indiquée si IC symptomatique (NYHA II-IV), **FEVG ≤ 35 %** et **QRS ≥ 130 ms** ; efficacité maximale si BBG, QRS ≥ 150 ms et cardiopathie non ischémique.\n\n**Défibrillateur automatique implantable (DAI)** [A] :\n- prévention secondaire : après arrêt cardiaque récupéré sur FV ou TV symptomatique ;\n- prévention primaire : patients symptomatiques (NYHA II-III), FEVG < 35 %, à distance d'un infarctus ou d'une revascularisation (≥ 6 semaines) ou après ≥ 3 mois de traitement médical optimal si cardiopathie non ischémique.\n- [B] Réservé aux patients dont l'espérance de survie dépasse 1 an (le stade NYHA IV n'en relève pas, sauf projet de greffe ou d'assistance) ; un dispositif combiné DAI-CRT est possible si les deux indications coexistent. Complications : infection de sonde, chocs inappropriés.\n\n**Traitement percutané de la fuite mitrale** : en cas d'IM secondaire significative persistant malgré un traitement optimal, une correction par clip percutané peut être discutée en réunion pluridisciplinaire si l'IC n'est pas trop avancée ; une correction percutanée de fuites tricuspides fonctionnelles importantes est aussi possible mais encore en évaluation.\n\n**IC terminale** :\n- **Transplantation cardiaque** : indiquée si symptômes invalidants, mauvais pronostic et absence d'alternative, sous réserve d'un traitement médical/non médical déjà maximal et de l'adhésion du patient au traitement immunosuppresseur. Limitée par le nombre de greffons. Contre-indications : âge physiologique avancé (rarement au-delà de 65-70 ans), pathologie réduisant l'espérance de vie, infection active, insuffisance rénale sévère, HTAP fixée (résistances > 5 unités Wood), artériopathie diffuse. Suivi à vie sous immunosuppresseurs (risque de rejet, infections, cancers, maladie coronarienne du greffon).\n- **Assistance circulatoire** : ECMO (courte durée) ou assistance mono/biventriculaire de plus longue durée, en pont vers la greffe ou, chez certains patients non éligibles à la greffe, comme traitement définitif.\n\n**Parcours de soins** [A] : après une 1re hospitalisation pour IC, le risque de réhospitalisation est élevé ; il faut contrôler les signes congestifs et optimiser le traitement en ambulatoire (lien cardiologue/médecin traitant), avec éducation thérapeutique du patient et de son entourage (connaître les signes d'alerte), réadaptation cardiaque si possible, et recours possible à des infirmiers en pratique avancée. Au stade avancé sans possibilité de greffe/assistance, une approche de soins de support ou palliatifs est nécessaire.","keyPoints":["CRT : NYHA II-IV, FEVG ≤ 35 %, QRS ≥ 130 ms (efficacité optimale si BBG et QRS ≥ 150 ms).","DAI en prévention secondaire (après FV/TV récupérée) ou primaire (FEVG < 35 % à distance de l'événement initial).","Le DAI n'est pas indiqué en NYHA IV sauf projet de greffe ou d'assistance, car le pronostic vital à court terme prime.","La transplantation cardiaque est limitée par la pénurie de greffons et par des contre-indications précises.","Un parcours de soins structuré avec éducation thérapeutique réduit le risque de réhospitalisation."],"pitfalls":["Ne pas proposer de DAI à un patient en NYHA IV sans projet de greffe ou d'assistance.","Ne pas oublier l'éducation thérapeutique après toute hospitalisation pour décompensation."],"src":"p. 481-483"},{"id":"234-sec-12","title":"Traitement de l'IC à fraction d'éjection préservée","rank":"B","objectives":["234-obj-08"],"content":"Moins codifié que celui de l'IC à FE diminuée (moins d'essais disponibles). Les **gliflozines** (dapagliflozine, empagliflozine) ont démontré une réduction de la mortalité cardiovasculaire et des hospitalisations, avec un haut niveau de preuve (I, A).\n\n**Le traitement de fond peut être organisé autour de 7 axes (moyen mnémotechnique du référentiel) :**\n\n| Axe | Contenu |\n|---|---|\n| A — arythmies | bêtabloquant ou inhibiteur calcique bradycardisant pour ralentir la FC et allonger la diastole (meilleur remplissage) |\n| B — pression artérielle | bloqueurs du SRA (IEC/ARA2) et antialdostérones (amélioration de la relaxation, régression de l'HVG chez l'hypertendu) |\n| C — comorbidités | cardiaques (FA, ischémie, valvulopathie) et non cardiaques (diabète, dysthyroïdie…) |\n| D — diurétique | thiazidique ou de l'anse en cas de signes congestifs, avec surveillance rénale |\n| E — exercice | activité physique adaptée régulière |\n| F — suivi | organisation d'un suivi régulier |\n| G — gliflozines | dapagliflozine/empagliflozine, hautement recommandées (I, A) |\n\n[B] Dans l'**amylose cardiaque à transthyrétine**, un traitement spécifique existe désormais : le **tafamidis**.\n\n**Télésurveillance** : des programmes de télésurveillance de l'IC, aujourd'hui remboursés, transmettent quasi quotidiennement des paramètres simples (PA, FC, poids) à une plateforme qui déclenche des alertes traitées par des infirmiers, afin de dépister précocement une décompensation et d'éviter une hospitalisation.","keyPoints":["Les gliflozines sont le traitement le mieux validé de l'IC à FE préservée (recommandation I, A).","Le traitement de fond de l'IC à FE préservée repose sur le contrôle de la FC, de la PA, des comorbidités, des diurétiques, de l'exercice, du suivi et des gliflozines.","Le tafamidis est un traitement spécifique de l'amylose cardiaque à transthyrétine.","La télésurveillance de l'IC est remboursée et vise à dépister précocement une décompensation."],"pitfalls":["Ne pas croire que l'IC à FE préservée n'a aucun traitement validé : les gliflozines le sont formellement."],"src":"p. 483-484"},{"id":"234-sec-13","title":"Traitement de l'insuffisance cardiaque aiguë","rank":"A","objectives":["234-obj-17","234-obj-18","234-obj-22","234-obj-23"],"content":"**OAP, à domicile** : position demi-assise, furosémide IV (**1 mg/kg**, à répéter si besoin), dérivés nitrés sublinguaux si PAS > 100 mmHg, appel du Samu selon la gravité, hospitalisation.\n\n**OAP, à l'hôpital/Samu** : position assise, voie veineuse (G5 %), monitorage (FC, PA, SpO2, scope), bilan (ECG, radio, biologie, ± écho pulmonaire), oxygénothérapie pour SpO2 > 90 % (prudence si risque d'hypercapnie), furosémide IV 1 mg/kg adapté à la diurèse, dérivés nitrés IV (trinitrine 1 mg/h adaptée) si **PAS > 110 mmHg**, morphine IV réservée à l'anxiété importante ou à la douleur thoracique, traitement du facteur déclenchant (digoxine IV + anticoagulation efficace si FA rapide ; nicardipine IV 1-5 mg/h si poussée hypertensive), anticoagulation préventive systématique par HBPM. **CPAP** si échec du traitement médicamenteux (FR > 25/min, SpO2 < 90 %) ; **intubation-ventilation invasive** en dernier recours. Le bêtabloquant n'est jamais débuté en pleine poussée ; s'il était déjà prescrit, il est le plus souvent arrêté ou réduit. Les IEC/ARA2/sacubitril-valsartan ne sont réintroduits que secondairement, une fois l'épisode stabilisé.\n\n**Poussée d'IC globale sans OAP franc** : hospitalisation fréquente mais non systématique, cure de diurétiques IV (ou simple majoration orale), réajustement du traitement de fond, recherche du facteur déclenchant.\n\n**Choc cardiogénique** : inotropes (dobutamine IV, ou inhibiteurs des phosphodiestérases type milrinone/énoximone si le patient est sous bêtabloquant), sondage urinaire systématique, monitorage invasif de la PA (cathéter radial) ; le lévosimendan (sensibilisateur calcique, inotrope et vasodilatateur) peut aider au sevrage des inotropes. En l'absence de réponse : discussion d'une assistance circulatoire (ECMO ou assistance prolongée), voire d'une greffe en urgence.\n\n**Rechercher systématiquement une cause curable, résumée par l'acronyme CHAMPIT** : **C**oronaire (syndrome coronarien aigu), **H**ypertensive (urgence hypertensive), **A**rythmie, **M**écanique (complication d'un SCA : rupture, CIV, IM aiguë), **P**ulmonaire (embolie pulmonaire), **I**nfection, **T**amponnade.","keyPoints":["Le traitement de l'OAP ne doit jamais attendre les examens complémentaires.","Furosémide 1 mg/kg IV et dérivés nitrés (si PAS suffisante) sont les piliers du traitement initial de l'OAP.","La CPAP est indiquée en cas d'échec du traitement médicamenteux ; l'intubation est le dernier recours.","Le choc cardiogénique relève des inotropes, éventuellement d'une assistance circulatoire.","CHAMPIT résume les causes curables à rechercher systématiquement devant une IC aiguë."],"pitfalls":["Introduire un bêtabloquant pendant une poussée aiguë d'IC est une faute grave.","Ne pas oublier l'anticoagulation préventive systématique par HBPM au cours d'un OAP hospitalisé.","Réserver la morphine IV aux situations d'anxiété importante ou de douleur, jamais en systématique."],"src":"p. 485-486"}],"essentials":[{"id":"234-ess-01","rank":"A","text":"L'IC associe des symptômes, des signes cliniques et une anomalie cardiaque structurelle ou fonctionnelle sous-jacente.","src":"p. 458"},{"id":"234-ess-02","rank":"B","text":"La prévalence de l'IC dans la population générale est de 1 à 2 %, en augmentation avec le vieillissement.","src":"p. 458"},{"id":"234-ess-03","rank":"A","text":"L'IC à FE diminuée est définie par une FEVG < 40 %, l'IC à FE préservée par une FEVG > 50 %.","src":"p. 460-461"},{"id":"234-ess-04","rank":"B","text":"Entre 41 et 49 % de FEVG, on parle d'IC à FE légèrement diminuée, proche du profil de l'IC à FE diminuée.","src":"p. 461"},{"id":"234-ess-05","rank":"A","text":"La dyspnée d'effort est le symptôme le plus fréquent mais le moins spécifique ; elle est quantifiée par la classification NYHA.","src":"p. 461-462"},{"id":"234-ess-06","rank":"A","text":"L'orthopnée et la dyspnée paroxystique nocturne sont plus spécifiques de l'IC que la dyspnée d'effort simple.","src":"p. 462"},{"id":"234-ess-07","rank":"A","text":"La turgescence jugulaire et le reflux hépatojugulaire sont les signes physiques les plus spécifiques d'IC droite.","src":"p. 463"},{"id":"234-ess-08","rank":"A","text":"Le dosage du BNP ou du NT-proBNP est l'examen de 1re intention, avec une excellente valeur prédictive négative.","src":"p. 465"},{"id":"234-ess-09","rank":"B","text":"L'échocardiographie transthoracique couplée au doppler est l'examen clé pour le diagnostic positif et étiologique de l'IC.","src":"p. 466"},{"id":"234-ess-10","rank":"A","text":"Un bloc de branche gauche avec QRS > 120 ms à l'ECG a des implications thérapeutiques majeures.","src":"p. 463"},{"id":"234-ess-11","rank":"A","text":"La cardiopathie ischémique est aujourd'hui la première cause d'insuffisance cardiaque.","src":"p. 469"},{"id":"234-ess-12","rank":"A","text":"La cardiomyopathie dilatée est la première cause d'insuffisance cardiaque et de transplantation chez le sujet jeune.","src":"p. 469"},{"id":"234-ess-13","rank":"B","text":"L'amylose cardiaque est la principale cardiomyopathie restrictive et a un pronostic sévère.","src":"p. 470"},{"id":"234-ess-14","rank":"A","text":"Devant toute IC à FEVG abaissée, il faut éliminer une cause ischémique par coronarographie ou coroscanner.","src":"p. 467-468"},{"id":"234-ess-15","rank":"A","text":"L'OAP cardiogénique est une urgence cardiovasculaire majeure imposant un traitement immédiat.","src":"p. 472"},{"id":"234-ess-16","rank":"A","text":"Le premier facteur déclenchant à rechercher devant une poussée d'IC est une rupture de traitement ou de régime sans sel.","src":"p. 473"},{"id":"234-ess-17","rank":"A","text":"Le choc cardiogénique associe hypotension marquée, signes d'hypoperfusion périphérique, oligurie et altération de la conscience.","src":"p. 473"},{"id":"234-ess-18","rank":"A","text":"L'IC à fraction d'éjection préservée représente au moins la moitié des cas d'IC, surtout chez la femme âgée.","src":"p. 473-474"},{"id":"234-ess-19","rank":"B","text":"La mortalité de l'insuffisance cardiaque est d'environ 50 % à 5 ans, par mort subite ou par IC réfractaire.","src":"p. 475"},{"id":"234-ess-20","rank":"A","text":"Quatre classes médicamenteuses réduisent la mortalité dans l'IC à FE diminuée : bloqueurs du SRA, bêtabloquants, antialdostérones, gliflozines.","src":"p. 477-480"},{"id":"234-ess-21","rank":"A","text":"Les bêtabloquants s'introduisent à très faible dose chez un patient stabilisé, jamais pendant une poussée aiguë.","src":"p. 478-479"},{"id":"234-ess-22","rank":"A","text":"Les diurétiques de l'anse contrôlent la rétention hydrosodée mais n'ont pas démontré de bénéfice sur la mortalité.","src":"p. 480"},{"id":"234-ess-23","rank":"A","text":"Le vérapamil, le diltiazem, les antiarythmiques de classe I et les AINS sont contre-indiqués dans l'IC à FE diminuée.","src":"p. 481"},{"id":"234-ess-24","rank":"B","text":"La resynchronisation cardiaque est indiquée en cas de FEVG ≤ 35 % et de QRS ≥ 130 ms, avec un bénéfice maximal si BBG et QRS ≥ 150 ms.","src":"p. 481-482"},{"id":"234-ess-25","rank":"A","text":"Le défibrillateur automatique implantable est proposé en prévention secondaire après un arrêt cardiaque récupéré ou en prévention primaire si la FEVG reste < 35 % malgré un traitement optimal.","src":"p. 481-482"},{"id":"234-ess-26","rank":"A","text":"Les gliflozines sont hautement recommandées dans le traitement de l'IC à FE préservée.","src":"p. 483-484"},{"id":"234-ess-27","rank":"A","text":"Le traitement de l'OAP repose sur la position assise, l'oxygénothérapie, le furosémide IV et les dérivés nitrés si la PAS le permet.","src":"p. 485"},{"id":"234-ess-28","rank":"A","text":"CHAMPIT résume les causes curables à rechercher systématiquement devant une insuffisance cardiaque aiguë.","src":"p. 486"},{"id":"234-ess-29","rank":"B","text":"La transplantation cardiaque est réservée à l'IC sévère sans alternative thérapeutique, limitée par la pénurie de greffons.","src":"p. 482"},{"id":"234-ess-30","rank":"A","text":"L'éducation thérapeutique du patient, notamment sur les signes d'alerte, réduit le risque de réhospitalisation.","src":"p. 484"}],"numbers":[{"id":"234-num-01","rank":"B","label":"Prévalence de l'IC en population générale","value":"1 à 2 %","src":"p. 458"},{"id":"234-num-02","rank":"B","label":"Âge moyen au diagnostic d'IC en Europe","value":"75 à 80 ans","src":"p. 458"},{"id":"234-num-03","rank":"A","label":"Seuil de FEVG pour l'IC à FE diminuée","value":"< 40 %","src":"p. 460"},{"id":"234-num-04","rank":"B","label":"Plage de FEVG pour l'IC à FE légèrement diminuée","value":"41 à 49 %","src":"p. 461"},{"id":"234-num-05","rank":"A","label":"Seuil de FEVG pour l'IC à FE préservée","value":"> 50 %","src":"p. 461"},{"id":"234-num-06","rank":"A","label":"Seuil BNP excluant l'IC lors d'une dyspnée aiguë","value":"< 100 pg/mL","src":"p. 465"},{"id":"234-num-07","rank":"A","label":"Seuil NT-proBNP excluant l'IC lors d'une dyspnée aiguë","value":"< 300 pg/mL","src":"p. 465"},{"id":"234-num-08","rank":"A","label":"Seuil BNP excluant l'IC en présentation non aiguë","value":"< 35 pg/mL","src":"p. 465"},{"id":"234-num-09","rank":"A","label":"Seuil NT-proBNP excluant l'IC en présentation non aiguë","value":"< 125 pg/mL","src":"p. 465"},{"id":"234-num-10","rank":"B","label":"Seuil NT-proBNP en faveur d'une IC (dyspnée aiguë, > 75 ans)","value":"> 1 800 pg/mL","src":"p. 465"},{"id":"234-num-11","rank":"B","label":"Rapport cardiothoracique pathologique","value":"> 0,5","src":"p. 463"},{"id":"234-num-12","rank":"B","label":"Protides d'un épanchement pleural transsudatif","value":"< 30 g/L","src":"p. 463"},{"id":"234-num-13","rank":"A","label":"Durée de QRS définissant un bloc de branche gauche significatif","value":"> 120 ms","src":"p. 463"},{"id":"234-num-14","rank":"A","label":"PAS définissant le choc cardiogénique","value":"< 90 mmHg (ou chute > 30 mmHg ≥ 30 min)","src":"p. 473"},{"id":"234-num-15","rank":"A","label":"Diurèse définissant l'oligurie du choc cardiogénique","value":"< 20 mL/h","src":"p. 473"},{"id":"234-num-16","rank":"B","label":"Masse VG indexée définissant l'HVG (homme / femme)","value":"> 115 g/m² / > 95 g/m²","src":"p. 474"},{"id":"234-num-17","rank":"B","label":"Volume atrial gauche indexé pathologique","value":"> 34 mL/m²","src":"p. 474"},{"id":"234-num-18","rank":"B","label":"Mortalité de l'IC à 5 ans","value":"environ 50 %","src":"p. 475"},{"id":"234-num-19","rank":"B","label":"Mortalité annuelle en NYHA IV","value":"40 à 50 % par an","src":"p. 475"},{"id":"234-num-20","rank":"A","label":"Régime hyposodé cible","value":"5 à 6 g de sel/jour","src":"p. 476"},{"id":"234-num-21","rank":"A","label":"Prise de poids devant alerter","value":"2 à 3 kg en 2-3 jours","src":"p. 476"},{"id":"234-num-22","rank":"A","label":"Dose de furosémide oral (IC chronique, selon sévérité)","value":"20 mg/j à 500 mg-1 g/j","src":"p. 480"},{"id":"234-num-23","rank":"B","label":"Dose initiale / cible de carvédilol","value":"3,125 mg ×2/j → 25 mg ×2/j","src":"p. 479"},{"id":"234-num-24","rank":"B","label":"Dose initiale / cible de bisoprolol","value":"1,25 mg/j → 10 mg/j","src":"p. 479"},{"id":"234-num-25","rank":"B","label":"Seuil de FC justifiant l'ivabradine malgré bêtabloquant","value":"> 70-75/min","src":"p. 480"},{"id":"234-num-26","rank":"A","label":"FEVG seuil pour la resynchronisation (CRT)","value":"≤ 35 %","src":"p. 481"},{"id":"234-num-27","rank":"A","label":"Durée de QRS seuil pour la resynchronisation","value":"≥ 130 ms","src":"p. 481"},{"id":"234-num-28","rank":"A","label":"FEVG seuil pour le DAI en prévention primaire","value":"< 35 %","src":"p. 482"},{"id":"234-num-29","rank":"B","label":"Délai minimal DAI après infarctus/revascularisation","value":"≥ 6 semaines","src":"p. 482"},{"id":"234-num-30","rank":"B","label":"Résistances pulmonaires contre-indiquant la greffe cardiaque","value":"> 5 unités Wood","src":"p. 468, 482"},{"id":"234-num-31","rank":"A","label":"Dose de furosémide IV à la phase initiale de l'OAP","value":"1 mg/kg","src":"p. 485"},{"id":"234-num-32","rank":"B","label":"PAS minimale pour les dérivés nitrés IV dans l'OAP","value":"> 110 mmHg","src":"p. 485"},{"id":"234-num-33","rank":"B","label":"Objectif de saturation en oxygène sous oxygénothérapie","value":"SaO2 > 90 %","src":"p. 485"}],"mnemonics":[{"id":"234-mn-01","rank":"A","title":"Causes curables à rechercher devant une IC aiguë","mnemonic":"CHAMPIT","expansion":"- **C** : syndrome Coronarien aigu\n- **H** : urgence Hypertensive\n- **A** : Arythmie\n- **M** : cause Mécanique compliquant un SCA (rupture, CIV, IM aiguë)\n- **P** : embolie Pulmonaire\n- **I** : Infection\n- **T** : Tamponnade","src":"p. 486"},{"id":"234-mn-02","rank":"B","title":"Les 7 axes du traitement de fond de l'IC à FE préservée","mnemonic":"A-B-C-D-E-F-G","expansion":"- **A** : Arythmies/tachycardie à ralentir (bêtabloquant, inhibiteur calcique bradycardisant)\n- **B** : Blood pressure — contrôle tensionnel (IEC/ARA2, antialdostérone)\n- **C** : Comorbidités cardiaques et non cardiaques\n- **D** : Diurétique (thiazidique ou de l'anse) si signes congestifs\n- **E** : Exercice physique adapté\n- **F** : suivi (Follow-up) régulier\n- **G** : Gliflozines","src":"p. 483-484"},{"id":"234-mn-03","rank":"A","title":"Signes périphériques de l'insuffisance cardiaque droite","mnemonic":"TRHOA","expansion":"- **T** : Turgescence jugulaire\n- **R** : Reflux hépatojugulaire\n- **H** : Hépatomégalie ferme et douloureuse\n- **O** : Œdèmes déclives prenant le godet\n- **A** : Ascite (souvent tardive)","src":"p. 463"},{"id":"234-mn-04","rank":"A","title":"Signes cliniques du choc cardiogénique","mnemonic":"PSTOC","expansion":"- **P** : Pression artérielle effondrée (PAS < 90 mmHg ou chute > 30 mmHg)\n- **S** : Sueurs\n- **T** : Troubles de la perfusion périphérique (extrémités froides, marbrées)\n- **O** : Oligurie (< 20 mL/h)\n- **C** : Conscience altérée (agitation, confusion)","src":"p. 473"},{"id":"234-mn-05","rank":"B","title":"Contre-indications aux IEC dans l'IC","mnemonic":"SAGH","expansion":"- **S** : Sténose bilatérale des artères rénales\n- **A** : Antécédent d'Angio-œdème\n- **G** : Grossesse\n- **H** : Hyperkaliémie","src":"p. 477"},{"id":"234-mn-06","rank":"B","title":"Diagnostics différentiels d'une dyspnée aiguë évoquant un OAP","mnemonic":"PEBA","expansion":"- **P** : Pneumopathie infectieuse\n- **E** : Embolie pulmonaire\n- **B** : exacerbation de BPCO\n- **A** : crise d'Asthme","src":"p. 472"},{"id":"234-mn-07","rank":"B","title":"Principales complications de l'insuffisance cardiaque","mnemonic":"DÉTHER","expansion":"- **D** : Décès (mort subite ou IC réfractaire)\n- **É** : Épisodes de décompensation (réhospitalisations)\n- **T** : Troubles du rythme\n- **H** : Hypotension artérielle\n- **E** : Emboliques (AVC, embolie pulmonaire)\n- **R** : Rénale et hydroélectrolytique (insuffisance rénale, dyskaliémie)","src":"p. 475"}]},"questions":[{"id":"234-qcm-001","type":"QRM","rank":"A","objective":"234-obj-02","tags":["définition"],"difficulty":1,"stem":"Parmi les propositions suivantes concernant la définition clinique de l'insuffisance cardiaque (IC), lesquelles sont exactes ?","options":[{"t":"L'IC associe des symptômes (dyspnée, fatigue) et des signes cliniques (œdèmes) à une anomalie cardiaque sous-jacente.","ok":true,"why":"C'est la définition clinique retenue par le chapitre : symptômes + signes + trouble cardiaque responsable."},{"t":"La présence d'une cardiomégalie radiologique est indispensable au diagnostic.","ok":false,"why":"L'absence de cardiomégalie n'élimine pas l'IC, en particulier à fraction d'éjection préservée."},{"t":"Le trouble cardiaque responsable peut être myocardique, valvulaire, péricardique, rythmique ou de conduction.","ok":true,"why":"Le chapitre énumère ces cinq origines possibles du dysfonctionnement cardiaque."},{"t":"Les signes physiques ont une sensibilité élevée et suffisent à eux seuls au diagnostic.","ok":false,"why":"Les signes physiques manquent de sensibilité et peuvent régresser rapidement sous traitement."},{"t":"Une phase de dysfonction cardiaque asymptomatique peut précéder l'apparition des symptômes.","ok":true,"why":"Son dépistage permet d'instaurer un traitement plus précoce et d'améliorer le pronostic."}],"explanation":"La définition clinique de l'IC repose sur l'association symptômes + signes + anomalie cardiaque. Les signes physiques sont peu sensibles et peuvent disparaître sous traitement, d'où l'intérêt de dépister la dysfonction asymptomatique.","src":"p. 458"},{"id":"234-qru-001","type":"QRU","rank":"B","objective":"234-obj-01","tags":["épidémiologie"],"difficulty":1,"stem":"Concernant l'épidémiologie de l'insuffisance cardiaque, quelle proposition est exacte ?","options":[{"t":"La prévalence en population générale est estimée entre 1 et 2 %.","ok":true,"why":"C'est la valeur donnée par le chapitre pour la population générale."},{"t":"L'incidence standardisée sur l'âge est en constante augmentation.","ok":false,"why":"Le chapitre indique au contraire que l'incidence standardisée sur l'âge tend à diminuer."},{"t":"L'âge moyen au diagnostic en Europe se situe entre 40 et 50 ans.","ok":false,"why":"L'âge moyen au diagnostic se situe en réalité entre 75 et 80 ans."},{"t":"La prévalence diminue avec le vieillissement de la population.","ok":false,"why":"C'est l'inverse : le vieillissement contribue à l'augmentation de la prévalence."},{"t":"Le dépistage précoce d'une dysfonction asymptomatique n'a aucun impact sur le pronostic.","ok":false,"why":"Le chapitre indique au contraire que ce dépistage améliore le pronostic."}],"explanation":"La prévalence de l'IC (1-2 %) augmente avec le vieillissement de la population et l'amélioration de la prise en charge cardiovasculaire, alors que l'incidence ajustée sur l'âge diminue.","src":"p. 458"},{"id":"234-qcm-002","type":"QRM","rank":"B","objective":"234-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant les mécanismes compensateurs de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"La dilatation ventriculaire (remodelage excentrique) permet de maintenir le volume d'éjection malgré une FEVG abaissée.","ok":true,"why":"Le chapitre illustre ce mécanisme : un VTD qui double peut compenser une FEVG divisée par deux."},{"t":"L'hypertrophie concentrique répond, selon la loi de Laplace, à une surcharge de pression.","ok":true,"why":"L'épaississement pariétal normalise la contrainte selon la loi de Laplace face à une postcharge élevée."},{"t":"La vasoconstriction périphérique épargne électivement la circulation cutanée et musculaire.","ok":false,"why":"C'est l'inverse : la vasoconstriction épargne le cerveau et les coronaires, aux dépens de la peau, des muscles et du rein."},{"t":"La rétention hydrosodée majore la précharge par le mécanisme de Starling.","ok":true,"why":"L'augmentation du volume circulant étire davantage les fibres myocardiques, augmentant transitoirement l'inotropie."},{"t":"L'activation neurohormonale est dépourvue de tout effet délétère à long terme.","ok":false,"why":"Elle a au contraire des effets proarythmiques et toxiques directs sur les myocytes à long terme."}],"explanation":"Chaque mécanisme compensateur (remodelage, vasoconstriction, rétention hydrosodée, activation neurohormonale) a un revers délétère à long terme, ce qui explique la progression de la maladie.","src":"p. 459-460"},{"id":"234-qcm-003","type":"QRM","rank":"B","objective":"234-obj-05","tags":["physiopathologie"],"difficulty":1,"stem":"Concernant le débit cardiaque et ses déterminants, lesquelles de ces propositions sont exactes ?","options":[{"t":"Le débit cardiaque est égal au produit du volume d'éjection systolique par la fréquence cardiaque.","ok":true,"why":"DC = VES × FC, formule rappelée en introduction du chapitre."},{"t":"Le volume d'éjection systolique dépend de la précharge, de la postcharge et de l'inotropie.","ok":true,"why":"Ce sont les trois déterminants classiques du VES cités par le chapitre."},{"t":"La fraction d'éjection correspond au rapport du volume télédiastolique sur le volume d'éjection systolique.","ok":false,"why":"C'est l'inverse : FE = VES/VTD, et non VTD/VES."},{"t":"La postcharge regroupe l'ensemble des forces s'opposant à l'éjection ventriculaire.","ok":true,"why":"C'est la définition donnée par le chapitre."},{"t":"La tachycardie réflexe ne contribue jamais au maintien du débit cardiaque.","ok":false,"why":"Au contraire, la tachycardie sympathique contribue à maintenir le débit cardiaque, au prix d'un travail cardiaque accru."}],"explanation":"DC = VES × FC ; le VES dépend de précharge, postcharge et inotropie ; la FE = VES/VTD. La tachycardie réflexe participe au maintien transitoire du débit.","src":"p. 458-460"},{"id":"234-qcm-004","type":"QRM","rank":"B","objective":"234-obj-05","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant la désynchronisation cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Elle résulte le plus souvent d'un trouble de conduction, typiquement un bloc de branche gauche.","ok":true,"why":"Le chapitre cite le bloc de branche gauche comme l'exemple le plus démonstratif."},{"t":"Elle correspond à une perte de la contraction synchrone des différents segments myocardiques.","ok":true,"why":"C'est la définition même de la désynchronisation donnée par le chapitre."},{"t":"Elle accélère la contraction de la paroi latérale du ventricule gauche.","ok":false,"why":"C'est l'inverse : dans le bloc de branche gauche, la contraction de la paroi latérale est retardée."},{"t":"Elle peut contribuer à aggraver une insuffisance cardiaque préexistante.","ok":true,"why":"Le chapitre indique que ce phénomène peut aggraver l'IC, justifiant la resynchronisation dans certains cas."},{"t":"Elle n'a jamais de retentissement clinique documenté.","ok":false,"why":"Elle est au contraire associée à une aggravation possible de l'IC."}],"explanation":"Un bloc de branche gauche retarde la contraction de la paroi latérale, créant une désynchronisation qui peut aggraver l'IC.","src":"p. 460"},{"id":"234-qru-002","type":"QRU","rank":"A","objective":"234-obj-08","tags":["diagnostic"],"difficulty":1,"stem":"Quel seuil de FEVG définit l'insuffisance cardiaque à fraction d'éjection diminuée ?","options":[{"t":"< 30 %","ok":false,"why":"Ce seuil est plus bas que celui retenu par le chapitre."},{"t":"< 35 %","ok":false,"why":"Ce seuil correspond au critère d'indication du défibrillateur, pas à la définition de l'IC à FE diminuée."},{"t":"< 40 %","ok":true,"why":"C'est le seuil exact donné par le chapitre pour l'IC à fraction d'éjection diminuée."},{"t":"< 45 %","ok":false,"why":"Ce seuil ne correspond à aucune des catégories définies dans le chapitre."},{"t":"< 50 %","ok":false,"why":"Ce seuil correspond en réalité au plafond de l'IC à FE préservée, pas au seuil de l'IC à FE diminuée."}],"explanation":"L'IC à FE diminuée est définie par une FEVG < 40 %, l'IC à FE légèrement diminuée entre 41 et 49 %, et l'IC à FE préservée par une FEVG > 50 %.","src":"p. 460"},{"id":"234-qcm-005","type":"QRM","rank":"B","objective":"234-obj-08","tags":["diagnostic"],"difficulty":2,"stem":"Concernant les catégories d'insuffisance cardiaque selon la FEVG, lesquelles de ces propositions sont exactes ?","options":[{"t":"L'IC à FE préservée est définie par une FEVG supérieure à 50 %.","ok":true,"why":"C'est le seuil exact donné par le chapitre."},{"t":"L'IC à FE légèrement diminuée correspond à une FEVG entre 41 et 49 %.","ok":true,"why":"C'est la définition intermédiaire introduite par le chapitre."},{"t":"L'IC à FE préservée s'accompagne le plus souvent d'une dilatation importante du ventricule gauche.","ok":false,"why":"Au contraire, le VG n'est en général pas dilaté mais épaissi et fibrosé."},{"t":"L'IC à FE légèrement diminuée se rapproche cliniquement du profil de l'IC à FE diminuée.","ok":true,"why":"Le chapitre indique que cette forme intermédiaire se comporte comme l'IC à FE diminuée sur le plan thérapeutique."},{"t":"La distinction entre ces différentes formes n'a aucune implication thérapeutique.","ok":false,"why":"Elle a au contraire des implications thérapeutiques majeures, les essais ayant inclus les patients selon la FEVG."}],"explanation":"Les trois catégories de FEVG orientent directement le traitement : les 4 classes majeures sont validées avec un haut niveau de preuve en dessous de 40 %.","src":"p. 460-461"},{"id":"234-qcm-006","type":"QRM","rank":"B","objective":"234-obj-05","tags":["physiopathologie","complications"],"difficulty":2,"stem":"Concernant les arythmies au cours de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"La fibrillation atriale est favorisée par la dilatation de l'oreillette secondaire à l'augmentation des pressions intracavitaires.","ok":true,"why":"C'est le mécanisme décrit par le chapitre pour expliquer la fréquence de la FA dans l'IC."},{"t":"La perte de la systole atriale liée à la FA peut aggraver l'insuffisance cardiaque.","ok":true,"why":"Le chapitre relie explicitement la perte de systole atriale à une aggravation de l'IC."},{"t":"La fibrillation atriale diminue le risque d'accident vasculaire cérébral.","ok":false,"why":"C'est l'inverse : la FA augmente le risque d'AVC dans ce contexte."},{"t":"Les troubles du rythme ventriculaires graves sont à l'origine de la plupart des morts subites dans l'IC.","ok":true,"why":"Le chapitre relie explicitement TV/FV et mort subite, justifiant l'intérêt du défibrillateur implantable."},{"t":"Les extrasystoles ventriculaires fréquentes n'ont aucun lien avec la fibrose myocardique.","ok":false,"why":"Le chapitre indique au contraire que la fibrose intramyocardique favorise les réentrées ventriculaires."}],"explanation":"La FA (favorisée par la dilatation atriale) aggrave l'IC et augmente le risque thromboembolique ; les arythmies ventriculaires, liées à la fibrose, sont la première cause de mort subite dans l'IC.","src":"p. 461"},{"id":"234-qcm-007","type":"QRM","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":1,"stem":"Une patiente décrit un essoufflement qui la réveille la nuit et l'oblige à s'asseoir pour reprendre son souffle. Concernant les symptômes respiratoires de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Ce symptôme correspond à une dyspnée paroxystique nocturne, très spécifique d'IC.","ok":true,"why":"Le chapitre décrit exactement ce tableau comme très spécifique de l'insuffisance cardiaque."},{"t":"L'orthopnée est liée à la redistribution des volumes sanguins vers le thorax en décubitus.","ok":true,"why":"C'est le mécanisme donné par le chapitre pour expliquer l'orthopnée."},{"t":"La dyspnée d'effort est le symptôme le plus spécifique de l'IC.","ok":false,"why":"Elle est au contraire fréquente mais peu spécifique ; ce sont l'orthopnée et la DPN qui sont plus spécifiques."},{"t":"L'asthme cardiaque peut être confondu à tort avec un asthme bronchique.","ok":true,"why":"Cette bradypnée expiratoire sifflante est décrite comme trompeuse, pouvant orienter à tort vers une cause pulmonaire."},{"t":"La toux d'effort ou de décubitus n'a aucune valeur d'orientation vers l'IC.","ok":false,"why":"Le chapitre indique au contraire qu'une toux survenant électivement à l'effort ou au décubitus doit faire évoquer l'IC."}],"explanation":"L'orthopnée et la dyspnée paroxystique nocturne sont plus spécifiques que la simple dyspnée d'effort ; certaines formes (asthme cardiaque, toux) peuvent être trompeuses.","src":"p. 461-462"},{"id":"234-qcm-008","type":"QRM","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":2,"stem":"Quelle classification est utilisée pour évaluer la sévérité fonctionnelle de la dyspnée chez un insuffisant cardiaque, et lesquelles de ces propositions à son sujet sont exactes ?","options":[{"t":"La classification NYHA comprend 4 stades de sévérité croissante.","ok":true,"why":"C'est la classification décrite par le chapitre, allant du stade I au stade IV."},{"t":"Le stade I correspond à une dyspnée pour les efforts minimes de la vie quotidienne.","ok":false,"why":"Le stade I correspond à l'absence de gêne ; c'est le stade IV qui correspond aux efforts minimes."},{"t":"Le stade III correspond à une gêne pour des efforts peu intenses comme la marche en terrain plat.","ok":true,"why":"C'est la description exacte du stade III donnée par le chapitre."},{"t":"Le stade IV correspond à une gêne permanente, y compris au repos.","ok":true,"why":"C'est la description exacte du stade IV."},{"t":"Cette classification n'a aucune valeur pronostique.","ok":false,"why":"Au contraire, la classe NYHA III-IV est un facteur pronostique défavorable cité par le chapitre."}],"explanation":"La NYHA classe la dyspnée en 4 stades ; sa sévérité (III-IV) est un facteur pronostique péjoratif reconnu.","src":"p. 461"},{"id":"234-qcm-009","type":"QRM","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":2,"stem":"Concernant les signes physiques d'insuffisance cardiaque droite, lesquelles de ces propositions sont exactes ?","options":[{"t":"La turgescence jugulaire est un signe très spécifique, recherché en position demi-assise.","ok":true,"why":"Le chapitre qualifie ce signe de très spécifique, recherché dans cette position."},{"t":"Le reflux hépatojugulaire se recherche après compression manuelle du foie.","ok":true,"why":"C'est la technique de recherche décrite par le chapitre."},{"t":"Les œdèmes des membres inférieurs de l'IC sont typiquement durs et douloureux.","ok":false,"why":"Ils sont au contraire mous, blancs, indolores et prennent le godet."},{"t":"L'ascite est le plus souvent un signe précoce d'insuffisance cardiaque droite.","ok":false,"why":"L'ascite est au contraire souvent tardive, sauf atteinte tricuspidienne organique ou péricardite constrictive."},{"t":"L'hépatomégalie d'insuffisance cardiaque droite est ferme et douloureuse à la palpation.","ok":true,"why":"C'est la description exacte donnée par le chapitre."}],"explanation":"Turgescence jugulaire et reflux hépatojugulaire sont les signes droits les plus spécifiques ; les œdèmes sont mous et indolores, l'ascite est souvent tardive.","src":"p. 462-463"},{"id":"234-qru-003","type":"QRU","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":2,"stem":"Chez un patient insuffisant cardiaque, en dessous de quel seuil la pression artérielle systolique est-elle considérée comme un signe de gravité ?","options":[{"t":"< 80 mmHg","ok":false,"why":"Ce seuil est plus bas que celui retenu par le chapitre."},{"t":"< 90 mmHg","ok":false,"why":"Ce seuil correspond au critère du choc cardiogénique, pas à celui de gravité clinique simple décrit dans ce paragraphe."},{"t":"< 100 mmHg","ok":true,"why":"C'est le seuil exact donné par le chapitre, traduisant une baisse du volume d'éjection ou un effet hypotenseur des traitements."},{"t":"< 110 mmHg","ok":false,"why":"Ce seuil est plus élevé que celui donné par le chapitre."},{"t":"< 120 mmHg","ok":false,"why":"Ce seuil est trop élevé et ne correspond à aucun critère du chapitre."}],"explanation":"Une PAS < 100 mmHg est un signe de gravité chez l'insuffisant cardiaque, sauf en cas d'IC d'origine hypertensive où la PAS peut rester élevée.","src":"p. 463"},{"id":"234-qcm-010","type":"QRM","rank":"A","objective":"234-obj-09","tags":["clinique","pièges"],"difficulty":3,"stem":"Concernant les particularités de l'examen clinique de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Une pression artérielle élevée peut coexister avec un OAP d'origine hypertensive.","ok":true,"why":"Le chapitre décrit explicitement l'OAP hypertensif comme une situation où la PA reste élevée."},{"t":"La tachycardie est souvent absente chez un patient traité par bêtabloquant.","ok":true,"why":"Le chapitre signale que ce signe manque fréquemment sous ce traitement."},{"t":"Un examen clinique pauvre permet d'éliminer formellement le diagnostic d'IC.","ok":false,"why":"L'examen peut au contraire être pauvre, notamment sous traitement, sans que cela élimine le diagnostic."},{"t":"Le bruit de galop B3 protodiastolique est facile à percevoir pour un examinateur non spécialiste.","ok":false,"why":"Le chapitre précise au contraire qu'il est difficile à rechercher pour le non-spécialiste."},{"t":"Un souffle d'insuffisance mitrale fonctionnelle peut s'entendre au cours d'une IC.","ok":true,"why":"Le chapitre cite ce souffle fonctionnel parmi les signes auscultatoires possibles de l'IC."}],"explanation":"L'examen clinique de l'IC peut être trompeur (pauvre sous traitement, PA parfois élevée) et certains signes auscultatoires demandent de l'expérience.","src":"p. 462-463"},{"id":"234-qcm-011","type":"QRM","rank":"B","objective":"234-obj-10","tags":["ECG","paraclinique"],"difficulty":2,"stem":"Concernant l'électrocardiogramme au cours de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Il est peu contributif pour le diagnostic positif mais peut orienter vers une étiologie.","ok":true,"why":"Le chapitre indique que l'ECG oriente parfois vers une cause (séquelle d'infarctus, arythmie) sans affirmer le diagnostic."},{"t":"Il permet à lui seul d'affirmer le diagnostic d'insuffisance cardiaque.","ok":false,"why":"Au contraire, il est décrit comme peu contributif pour le diagnostic positif."},{"t":"Un bloc de branche gauche avec QRS large a des implications thérapeutiques.","ok":true,"why":"Le chapitre mentionne explicitement ses implications pour la resynchronisation."},{"t":"Il est inutile de réaliser un ECG devant une suspicion d'insuffisance cardiaque.","ok":false,"why":"L'ECG fait au contraire partie du bilan recommandé devant toute suspicion d'IC."},{"t":"Sa normalité élimine formellement toute cardiopathie ischémique sous-jacente.","ok":false,"why":"Un ECG normal n'élimine pas une cardiopathie ischémique, qui nécessite d'autres examens."}],"explanation":"L'ECG oriente vers une étiologie (séquelle d'infarctus, trouble du rythme, bloc de branche) mais ne suffit pas au diagnostic positif d'IC.","src":"p. 463"},{"id":"234-qcm-012","type":"QRM","rank":"A","objective":"234-obj-14","tags":["imagerie"],"difficulty":2,"stem":"Concernant la radiographie thoracique au cours de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Un rapport cardiothoracique supérieur à 0,5 traduit une cardiomégalie.","ok":true,"why":"C'est le seuil exact donné par le chapitre pour définir une cardiomégalie radiologique."},{"t":"L'absence de cardiomégalie élimine le diagnostic d'IC à fraction d'éjection préservée.","ok":false,"why":"Au contraire, l'absence de dilatation ventriculaire est fréquente dans l'IC à FE préservée."},{"t":"Les lignes de Kerley traduisent un œdème interstitiel.","ok":true,"why":"Elles correspondent au stade intermédiaire de gravité croissante décrit par le chapitre."},{"t":"L'œdème alvéolaire réalise classiquement un aspect en ailes de papillon.","ok":true,"why":"C'est la description imagée exacte de l'œdème alvéolaire donnée par le chapitre."},{"t":"La redistribution vasculaire vers les sommets est le stade le plus sévère de la stase pulmonaire.","ok":false,"why":"C'est au contraire le premier stade, le moins sévère, précédant l'œdème interstitiel puis alvéolaire."}],"explanation":"Les signes de stase s'aggravent de façon croissante : redistribution vasculaire → œdème interstitiel (lignes de Kerley) → œdème alvéolaire en ailes de papillon.","src":"p. 463-465"},{"id":"234-qcm-013","type":"QRM","rank":"A","objective":"234-obj-12","tags":["biologie","diagnostic"],"difficulty":2,"stem":"Un patient de 60 ans consulte pour une dyspnée aiguë et bénéficie d'un dosage de NT-proBNP. Concernant l'interprétation des peptides natriurétiques, lesquelles de ces propositions sont exactes ?","options":[{"t":"Une valeur de NT-proBNP < 300 pg/mL rend le diagnostic d'IC très improbable en contexte aigu.","ok":true,"why":"C'est le seuil d'exclusion donné par le chapitre pour la dyspnée aiguë."},{"t":"Le seuil d'exclusion en situation non aiguë est plus bas qu'en situation aiguë.","ok":true,"why":"Le chapitre propose des seuils plus bas (BNP < 35, NT-proBNP < 125 pg/mL) pour les présentations non aiguës."},{"t":"L'obésité tend à augmenter les concentrations de peptides natriurétiques.","ok":false,"why":"C'est l'inverse : l'obésité tend à abaisser ces concentrations."},{"t":"L'insuffisance rénale et la fibrillation atriale tendent à élever ces marqueurs.","ok":true,"why":"Le chapitre cite ces deux facteurs parmi ceux qui augmentent les concentrations de BNP/NT-proBNP."},{"t":"Ces peptides sont libérés par les myocytes cardiaques lorsqu'ils sont étirés.","ok":true,"why":"C'est le mécanisme de sécrétion décrit par le chapitre, lié à l'augmentation de pression intracavitaire."}],"explanation":"Le BNP/NT-proBNP a une excellente valeur prédictive négative sous certains seuils, mais son interprétation doit tenir compte de facteurs modificateurs (âge, fonction rénale, FA, obésité).","src":"p. 465"},{"id":"234-qru-004","type":"QRU","rank":"A","objective":"234-obj-12","tags":["biologie"],"difficulty":1,"stem":"Quel seuil de BNP permet d'exclure une insuffisance cardiaque en présentation clinique non aiguë (dyspnée chronique) ?","options":[{"t":"< 35 pg/mL","ok":true,"why":"C'est le seuil d'exclusion donné par le chapitre pour les présentations non aiguës."},{"t":"< 100 pg/mL","ok":false,"why":"Ce seuil correspond en réalité au contexte de dyspnée aiguë, pas à la présentation non aiguë."},{"t":"< 125 pg/mL","ok":false,"why":"Ce seuil correspond au NT-proBNP, pas au BNP, en présentation non aiguë."},{"t":"< 300 pg/mL","ok":false,"why":"Ce seuil correspond au NT-proBNP en contexte de dyspnée aiguë."},{"t":"< 450 pg/mL","ok":false,"why":"Ce seuil correspond à une valeur orientant vers l'IC chez le sujet jeune en contexte aigu, pas à un seuil d'exclusion."}],"explanation":"En dehors de l'urgence, un BNP < 35 pg/mL (ou NT-proBNP < 125 pg/mL) rend le diagnostic d'IC très improbable.","src":"p. 465"},{"id":"234-qcm-014","type":"QRM","rank":"B","objective":"234-obj-13","tags":["paraclinique"],"difficulty":1,"stem":"Concernant l'échocardiographie transthoracique (ETT) couplée au doppler dans l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Elle catégorise l'IC selon la FEVG (< 40 %, 41-49 %, > 50 %).","ok":true,"why":"C'est l'un des apports essentiels de l'ETT décrits par le chapitre."},{"t":"Elle constitue un examen facultatif, non indispensable au bilan.","ok":false,"why":"Le chapitre la qualifie au contraire d'examen clé indispensable en cas d'IC ou de suspicion d'IC."},{"t":"Elle peut orienter vers une étiologie, par exemple une anomalie segmentaire ou une valvulopathie.","ok":true,"why":"Le chapitre décrit ces orientations étiologiques possibles à l'ETT."},{"t":"Elle ne renseigne jamais sur le niveau des pressions de remplissage.","ok":false,"why":"Au contraire, elle permet une estimation semi-qualitative des pressions de remplissage."},{"t":"Elle explore la taille et la fonction du ventricule droit.","ok":true,"why":"C'est l'un des paramètres explorés par l'ETT, cité par le chapitre."}],"explanation":"L'ETT couplée au doppler est l'examen clé : elle catégorise la FEVG, explore les cavités, les valves et les pressions, et oriente vers une étiologie.","src":"p. 466"},{"id":"234-qru-005","type":"QRU","rank":"B","objective":"234-obj-06","tags":["physiopathologie","pièges"],"difficulty":3,"stem":"Concernant l'œdème pulmonaire lésionnel (non cardiogénique), quelle proposition est exacte selon le chapitre ?","options":[{"t":"Il résulte de lésions de la membrane alvéolocapillaire, à la différence du mécanisme hydrostatique de l'OAP cardiogénique.","ok":true,"why":"C'est la distinction physiopathologique exacte donnée par le chapitre entre œdème lésionnel et hydrostatique."},{"t":"Il est dû à une augmentation isolée de la pression capillaire pulmonaire, comme l'OAP cardiogénique.","ok":false,"why":"C'est au contraire le mécanisme propre à l'OAP cardiogénique, différent de la lésion membranaire de l'œdème lésionnel."},{"t":"Il ne peut jamais survenir chez un patient sans cardiopathie sous-jacente.","ok":false,"why":"Au contraire, ses origines sont nombreuses et indépendantes d'une cardiopathie."},{"t":"Il s'accompagne toujours d'une fraction d'éjection ventriculaire gauche abaissée.","ok":false,"why":"L'œdème lésionnel n'est pas lié à un trouble de la fonction ventriculaire gauche."},{"t":"Sa distinction avec l'œdème cardiogénique n'a aucune conséquence pratique.","ok":false,"why":"Le chapitre souligne au contraire l'implication immédiate de cette distinction sur la prise en charge."}],"explanation":"L'œdème lésionnel provient d'une atteinte de la membrane alvéolocapillaire (mécanisme différent), alors que l'OAP cardiogénique résulte d'une élévation de la pression capillaire pulmonaire ; les distinguer conditionne la prise en charge.","src":"p. 459"},{"id":"234-qcm-015","type":"QRM","rank":"A","objective":"234-obj-15","tags":["imagerie"],"difficulty":1,"stem":"Concernant l'imagerie radiographique typique d'un OAP d'origine hémodynamique décrite dans le chapitre, lesquelles de ces propositions sont exactes ?","options":[{"t":"Elle montre un syndrome alvéolo-interstitiel prédominant aux bases, gravitodépendant.","ok":true,"why":"C'est la description exacte donnée par le chapitre pour ce syndrome radiologique."},{"t":"Des épanchements pleuraux peuvent apparaître au bout de quelques heures.","ok":true,"why":"Le chapitre précise ce délai d'apparition des épanchements pleuraux."},{"t":"Les opacités sont exclusivement périhilaires, jamais basales.","ok":false,"why":"Les opacités floconneuses des bases sont décrites en premier lieu ; les opacités périhilaires ne surviennent qu'en cas de tableau brutal."},{"t":"En cas de survenue brutale, des opacités alvéolaires à prédominance périhilaire peuvent être observées.","ok":true,"why":"Le chapitre précise cette particularité pour les formes de survenue brutale."},{"t":"Ce syndrome radiologique est totalement indépendant de la position du patient.","ok":false,"why":"Il est au contraire décrit comme gravitodépendant, donc lié à la position."}],"explanation":"Le syndrome alvéolo-interstitiel de l'OAP hémodynamique est gravitodépendant (bases), avec des épanchements pleuraux différés et des opacités périhilaires en cas de survenue brutale.","src":"p. 456-457"},{"id":"234-qroc-001","type":"QROC","rank":"A","objective":"234-obj-02","tags":["définition"],"difficulty":1,"question":"Citez les deux composantes qui, associées à une anomalie cardiaque sous-jacente, définissent le syndrome d'insuffisance cardiaque sur le plan clinique.","answer":"Des symptômes et des signes cliniques","accept":["signes et symptômes","symptômes et signes physiques"],"keywords":["symptômes","signes"],"explanation":"La définition clinique de l'IC associe des symptômes (dyspnée, fatigue, prise de poids) et des signes cliniques (œdèmes, râles) à un trouble cardiaque sous-jacent.","src":"p. 458"},{"id":"234-qroc-002","type":"QROC","rank":"B","objective":"234-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est la tranche d'âge moyenne au diagnostic d'insuffisance cardiaque en Europe ?","answer":"75 à 80 ans","accept":["75-80 ans","entre 75 et 80 ans"],"keywords":["75","80","ans"],"explanation":"L'âge moyen au diagnostic se situe entre 75 et 80 ans en Europe, avec une prévalence qui augmente avec l'âge.","src":"p. 458"},{"id":"234-qroc-003","type":"QROC","rank":"B","objective":"234-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"Quelle loi physique relie la contrainte pariétale, la pression développée, le rayon de la cavité et l'épaisseur de la paroi ventriculaire ?","answer":"La loi de Laplace","accept":["Laplace"],"keywords":["laplace"],"explanation":"Selon la loi de Laplace, l'hypertrophie concentrique (épaississement pariétal) permet de normaliser la contrainte pariétale en réponse à une surcharge de pression.","src":"p. 460"},{"id":"234-qroc-004","type":"QROC","rank":"B","objective":"234-obj-05","tags":["physiopathologie"],"difficulty":2,"question":"Selon la loi de Starling, quel est l'effet de l'augmentation de la précharge sur l'inotropie, jusqu'à une certaine limite de dilatation ?","answer":"Elle augmente l'inotropie du ventricule","accept":["augmentation de la contractilité","augmentation de la force de contraction"],"keywords":["inotropie","augmente"],"explanation":"L'étirement des fibres myocardiques lié à l'augmentation de la précharge accroît transitoirement l'inotropie, jusqu'à une limite au-delà de laquelle ce mécanisme devient délétère.","src":"p. 460"},{"id":"234-qroc-005","type":"QROC","rank":"A","objective":"234-obj-08","tags":["diagnostic"],"difficulty":1,"question":"Quel intervalle de FEVG définit l'insuffisance cardiaque à fraction d'éjection légèrement diminuée ?","answer":"41 à 49 %","accept":["41-49 %","entre 41 et 49 %"],"keywords":["41","49"],"explanation":"Entre 41 et 49 % de FEVG, on parle d'IC à FE légèrement diminuée, forme se rapprochant cliniquement du profil de l'IC à FE diminuée.","src":"p. 461"},{"id":"234-qroc-006","type":"QROC","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":1,"question":"Quelle classification permet de graduer la dyspnée d'effort de l'insuffisant cardiaque en quatre stades ?","answer":"La classification NYHA","accept":["classification de la New York Heart Association","NYHA"],"keywords":["nyha"],"explanation":"La classification NYHA, de I à IV, quantifie la tolérance fonctionnelle et reflète la sévérité de la maladie.","src":"p. 461"},{"id":"234-qroc-007","type":"QROC","rank":"A","objective":"234-obj-09","tags":["clinique"],"difficulty":2,"question":"Quel signe physique, recherché en position demi-assise après compression manuelle du foie, traduit la congestion hépatique dans l'IC droite ?","answer":"Le reflux hépatojugulaire","accept":["reflux hépato-jugulaire"],"keywords":["reflux","hépatojugulaire"],"explanation":"Le reflux hépatojugulaire correspond à une dilatation anormale de la veine jugulaire après compression du foie, traduisant la congestion hépatique et l'incapacité du cœur droit à gérer le volume ainsi déplacé.","src":"p. 462"},{"id":"234-qroc-008","type":"QROC","rank":"B","objective":"234-obj-09","tags":["clinique","paraclinique"],"difficulty":2,"question":"Quelle concentration en protides définit le caractère transsudatif d'un épanchement pleural au cours de l'IC ?","answer":"Moins de 30 g/L","accept":["< 30 g/L","inférieure à 30 g/L"],"keywords":["30","g/l"],"explanation":"Un épanchement pleural transsudatif, évoquant une origine hémodynamique, se définit par une concentration en protides inférieure à 30 g/L.","src":"p. 462"},{"id":"234-qroc-009","type":"QROC","rank":"A","objective":"234-obj-10","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle durée de QRS, associée à un bloc de branche gauche, a des implications thérapeutiques majeures au cours de l'IC ?","answer":"Supérieure à 120 ms","accept":["> 120 ms","plus de 120 ms"],"keywords":["120","ms"],"explanation":"Un bloc de branche gauche avec QRS > 120 ms fait discuter une resynchronisation ventriculaire par stimulateur biventriculaire.","src":"p. 463"},{"id":"234-qroc-010","type":"QROC","rank":"A","objective":"234-obj-12","tags":["biologie"],"difficulty":1,"question":"Quel dosage biologique est recommandé en première intention devant une suspicion d'insuffisance cardiaque, en raison de sa bonne valeur prédictive négative ?","answer":"Le dosage du BNP ou du NT-proBNP","accept":["BNP","NT-proBNP","peptides natriurétiques"],"keywords":["bnp"],"explanation":"Le BNP ou le NT-proBNP est le marqueur de première intention, avec une excellente valeur prédictive négative sous certains seuils.","src":"p. 465"},{"id":"234-qroc-011","type":"QROC","rank":"B","objective":"234-obj-13","tags":["paraclinique"],"difficulty":1,"question":"Quel examen d'imagerie, couplé au doppler, est considéré comme l'examen clé du diagnostic positif et étiologique de l'IC ?","answer":"L'échocardiographie transthoracique (ETT)","accept":["échographie cardiaque","ETT"],"keywords":["échocardiographie","ett"],"explanation":"L'ETT couplée au doppler catégorise la FEVG, explore les cavités et les valves, et oriente le diagnostic étiologique.","src":"p. 466"},{"id":"234-open-01","type":"OPEN","rank":"A","objective":"234-obj-09","tags":["clinique","diagnostic"],"difficulty":2,"prompt":"Un homme de 68 ans, connu pour une cardiopathie ischémique ancienne, se plaint depuis plusieurs semaines d'un essoufflement croissant. Décrivez les principaux signes fonctionnels et physiques qui doivent faire évoquer une insuffisance cardiaque chez ce patient, en précisant leur valeur diagnostique respective (sensibilité/spécificité).","rubric":[{"point":"Cite la dyspnée d'effort comme symptôme fréquent mais peu spécifique, quantifiée par la NYHA","weight":2},{"point":"Cite l'orthopnée et la dyspnée paroxystique nocturne comme signes plus spécifiques","weight":2},{"point":"Cite les signes droits (turgescence jugulaire, reflux hépatojugulaire) comme très spécifiques","weight":2},{"point":"Mentionne que l'examen physique peut être pauvre sous traitement sans éliminer le diagnostic","weight":2},{"point":"Évoque un signe trompeur (asthme cardiaque, toux, hémoptysies)","weight":1},{"point":"Mentionne un signe auscultatoire cardiaque (galop B3, souffle fonctionnel)","weight":1}],"model":"La dyspnée d'effort, fréquente, est le symptôme le moins spécifique ; son degré (classification NYHA) reflète la sévérité. L'orthopnée et la dyspnée paroxystique nocturne sont plus spécifiques. Sur le plan physique, la turgescence jugulaire et le reflux hépatojugulaire sont les signes les plus spécifiques d'IC droite, associés à une hépatomégalie ferme et douloureuse et à des œdèmes déclives mous indolores. Des râles crépitants bilatéraux et un galop B3 peuvent s'associer. Des formes trompeuses existent (asthme cardiaque, toux d'effort). L'examen peut cependant rester pauvre chez un patient bien traité, ce qui ne doit pas faire éliminer le diagnostic.","src":"p. 461-463"},{"id":"234-open-02","type":"OPEN","rank":"B","objective":"234-obj-08","tags":["physiopathologie","diagnostic"],"difficulty":2,"prompt":"Expliquez la différence physiopathologique entre l'insuffisance cardiaque à fraction d'éjection diminuée et l'insuffisance cardiaque à fraction d'éjection préservée.","rubric":[{"point":"IC à FE diminuée : défaut de contraction/éjection, VG dilaté, FEVG < 40 %","weight":3},{"point":"IC à FE préservée : trouble du remplissage, VG non dilaté mais épaissi/fibrosé, FEVG > 50 %","weight":3},{"point":"Mentionne la forme légèrement diminuée (41-49 %), proche du profil FE diminuée","weight":2},{"point":"Précise que l'IC à FE préservée est plus fréquente chez le sujet âgé et la femme, associée à l'HTA/obésité","weight":2}],"model":"Dans l'IC à fraction d'éjection diminuée (< 40 %), le mécanisme principal est un défaut de contraction du ventricule gauche, qui se dilate et éjecte un volume insuffisant à chaque systole. Dans l'IC à fraction d'éjection préservée (> 50 %), le cœur se contracte normalement mais se remplit mal : le VG n'est en général pas dilaté, mais ses parois sont épaissies et fibrosées, le rendant rigide. Cette forme, plus fréquente chez le sujet âgé et la femme, est volontiers associée à l'HTA et à l'obésité. Entre les deux, la FE légèrement diminuée (41-49 %) se comporte cliniquement de façon proche de l'IC à FE diminuée.","src":"p. 460-461"},{"id":"234-open-03","type":"OPEN","rank":"A","objective":"234-obj-12","tags":["biologie","paraclinique","diagnostic"],"difficulty":2,"prompt":"Décrivez la stratégie d'utilisation du dosage des peptides natriurétiques (BNP/NT-proBNP) et de l'échocardiographie transthoracique dans la démarche diagnostique d'une suspicion d'insuffisance cardiaque en dehors de l'urgence.","rubric":[{"point":"Dosage du BNP/NT-proBNP en première intention devant une suspicion clinique","weight":2},{"point":"Seuils d'exclusion en présentation non aiguë (BNP < 35, NT-proBNP < 125 pg/mL)","weight":2},{"point":"Si peptides au-dessus du seuil (ou non disponibles) : réalisation d'une échocardiographie","weight":2},{"point":"L'ETT confirme ou infirme le diagnostic et catégorise la FEVG","weight":2},{"point":"Mentionne l'excellente valeur prédictive négative des peptides natriurétiques","weight":1},{"point":"Évoque les facteurs pouvant modifier l'interprétation (âge, fonction rénale, obésité, FA)","weight":1}],"model":"Devant une suspicion d'IC en dehors de l'urgence, le dosage du BNP ou du NT-proBNP est réalisé en première intention, en raison de son excellente valeur prédictive négative. Des valeurs basses (BNP < 35 pg/mL, NT-proBNP < 125 pg/mL) rendent l'IC très improbable. Au-delà de ces seuils, ou si le dosage n'est pas disponible, une échocardiographie transthoracique doit être réalisée : elle confirme ou infirme le diagnostic et catégorise l'IC selon la FEVG. L'interprétation des peptides natriurétiques doit toujours tenir compte de facteurs modificateurs (âge, fonction rénale, fibrillation atriale, obésité).","src":"p. 465-467"},{"id":"234-qcm-101","type":"QRM","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":1,"stem":"Concernant les étiologies de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"La cardiopathie ischémique est aujourd'hui la première cause d'IC.","ok":true,"why":"Le chapitre l'indique explicitement en ouverture du chapitre sur le diagnostic étiologique."},{"t":"La cardiomyopathie dilatée est la première cause d'IC chez le sujet jeune.","ok":true,"why":"C'est le fait cité par le chapitre pour cette population."},{"t":"L'HTA ne peut jamais être responsable d'une IC à FE diminuée.","ok":false,"why":"L'HTA peut aussi entraîner une baisse de la FEVG via l'augmentation chronique de la postcharge."},{"t":"Toutes les valvulopathies gauches peuvent se compliquer d'une insuffisance cardiaque.","ok":true,"why":"Le chapitre indique qu'IM, IA, RM et RA peuvent toutes aboutir à l'IC."},{"t":"Les troubles du rythme ne sont jamais responsables d'insuffisance cardiaque.","ok":false,"why":"Une tachycardie rapide et prolongée peut au contraire provoquer une tachycardiomyopathie."}],"explanation":"La cardiopathie ischémique domine les étiologies globales, la CMD domine chez le sujet jeune ; HTA, valvulopathies et arythmies peuvent toutes conduire à l'IC.","src":"p. 469-471"},{"id":"234-qru-101","type":"QRU","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"stem":"Un homme de 45 ans développe une dysfonction ventriculaire gauche après plusieurs années de consommation excessive d'alcool. Quelle étiologie évoquez-vous en premier lieu ?","options":[{"t":"Une cardiomyopathie dilatée d'origine toxique","ok":true,"why":"L'alcool figure parmi les causes toxiques de cardiomyopathie dilatée citées par le chapitre."},{"t":"Une cardiomyopathie hypertrophique","ok":false,"why":"Cette entité est le plus souvent génétique, non liée à une intoxication alcoolique chronique."},{"t":"Une amylose cardiaque","ok":false,"why":"L'amylose est une cardiomyopathie restrictive sans lien avec l'alcool."},{"t":"Un rétrécissement mitral","ok":false,"why":"Il s'agit d'une valvulopathie organique, sans rapport avec une intoxication éthylique."},{"t":"Un cœur pulmonaire chronique","ok":false,"why":"Il résulte d'une pathologie respiratoire chronique, non de la consommation d'alcool."}],"explanation":"L'alcool est une cause toxique classique de cardiomyopathie dilatée ; l'arrêt total de la consommation peut permettre une régression partielle voire totale.","src":"p. 470"},{"id":"234-qcm-102","type":"QRM","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"stem":"Concernant la cardiomyopathie dilatée (CMD), lesquelles de ces propositions sont exactes ?","options":[{"t":"Une origine familiale/génétique est retrouvée dans environ 25 % des cas.","ok":true,"why":"C'est la proportion donnée par le chapitre pour les formes monogéniques familiales."},{"t":"La transmission est le plus souvent autosomique dominante.","ok":true,"why":"C'est le mode de transmission le plus fréquent cité par le chapitre pour les formes familiales."},{"t":"Les anthracyclines et le trastuzumab figurent parmi les causes médicamenteuses possibles.","ok":true,"why":"Ces molécules de chimiothérapie sont explicitement citées comme cardiotoxiques."},{"t":"Elle épargne systématiquement la grossesse.","ok":false,"why":"Il existe au contraire une cardiomyopathie du péripartum liée à la grossesse."},{"t":"Aucun cas de CMD ne reste sans cause identifiée.","ok":false,"why":"Le chapitre indique qu'il n'est pas rare qu'aucune cause ne soit retrouvée (forme idiopathique)."}],"explanation":"La CMD a de multiples origines (génétique ~25 %, toxique, infectieuse, auto-immune, médicamenteuse, péripartum) mais reste parfois idiopathique.","src":"p. 469-470"},{"id":"234-qcm-103","type":"QRM","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"stem":"Concernant la cardiomyopathie hypertrophique (CMH), quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Une obstruction sous-aortique est présente dans environ 25 % des cas.","ok":true,"why":"C'est la proportion donnée par le chapitre pour la forme obstructive de la CMH."},{"t":"Elle est presque toujours une maladie acquise, jamais génétique.","ok":false,"why":"Il s'agit au contraire le plus souvent d'une maladie familiale monogénique du sarcomère."},{"t":"La fraction d'éjection est typiquement abaissée.","ok":false,"why":"Elle est au contraire conservée, avec un trouble du remplissage plutôt qu'un défaut de contraction."},{"t":"Elle peut se compliquer de mort subite, notamment chez le jeune athlète.","ok":true,"why":"Le chapitre la cite comme la première cause de mort subite du jeune athlète."},{"t":"L'hypertrophie prédomine toujours sur la paroi inférieure du ventricule gauche.","ok":false,"why":"Elle prédomine le plus souvent sur le septum interventriculaire."}],"explanation":"La CMH est une maladie génétique du sarcomère, à FE conservée, avec obstruction sous-aortique dans 25 % des cas et risque de mort subite chez le jeune athlète.","src":"p. 470"},{"id":"234-qcm-104","type":"QRM","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"stem":"Concernant les cardiomyopathies restrictives, lesquelles de ces propositions sont exactes ?","options":[{"t":"L'amylose cardiaque en est la cause la plus fréquente.","ok":true,"why":"Le chapitre cite l'amylose comme la cardiomyopathie restrictive la plus fréquente."},{"t":"Les parois ventriculaires deviennent épaissies et rigides, moins compliantes.","ok":true,"why":"C'est la description exacte des dépôts amyloïdes donnée par le chapitre."},{"t":"Le remplissage ventriculaire est facilité par cette rigidité.","ok":false,"why":"C'est l'inverse : la rigidité pariétale rend le remplissage difficile."},{"t":"Le pronostic est en général sévère lorsque des manifestations d'IC apparaissent.","ok":true,"why":"Le chapitre qualifie ce pronostic de sévère à ce stade."},{"t":"La fonction systolique est altérée précocement, avant tout trouble du remplissage.","ok":false,"why":"C'est l'inverse : le trouble du remplissage précède l'atteinte systolique, plus tardive."}],"explanation":"L'amylose cardiaque, cardiomyopathie restrictive la plus fréquente, entraîne rigidité pariétale et difficulté de remplissage, avec un pronostic sévère au stade symptomatique.","src":"p. 470"},{"id":"234-qcm-105","type":"QRM","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":1,"stem":"Quelle valvulopathie gauche peut entraîner un œdème aigu pulmonaire alors que le ventricule gauche lui-même n'est pas atteint ?","options":[{"t":"Le rétrécissement mitral","ok":true,"why":"Le chapitre précise cette particularité propre au RM : l'obstacle est en amont du VG."},{"t":"L'insuffisance aortique","ok":false,"why":"L'insuffisance aortique retentit directement sur le ventricule gauche par surcharge de volume."},{"t":"Le rétrécissement aortique","ok":false,"why":"Le RA retentit directement sur le VG par surcharge de pression et hypertrophie concentrique."},{"t":"L'insuffisance mitrale","ok":false,"why":"L'IM entraîne une surcharge de volume qui retentit sur le ventricule gauche."},{"t":"Une bicuspidie aortique non sténosante et non fuyante","ok":false,"why":"Une bicuspidie non compliquée n'a par elle-même aucun retentissement hémodynamique."}],"explanation":"Le rétrécissement mitral peut être à l'origine de manifestations d'IC gauche (OAP) sans que le ventricule gauche soit lui-même atteint, l'obstacle étant en amont.","src":"p. 470"},{"id":"234-qcm-106","type":"QRM","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"stem":"Concernant les causes d'insuffisance cardiaque droite isolée, lesquelles de ces propositions sont exactes ?","options":[{"t":"L'embolie pulmonaire aiguë peut entraîner un cœur pulmonaire aigu.","ok":true,"why":"C'est le mécanisme décrit par le chapitre pour l'insuffisance cardiaque droite aiguë brutale."},{"t":"La dysplasie arythmogène du ventricule droit en est une cause.","ok":true,"why":"Le chapitre la cite parmi les causes d'atteinte spécifique du ventricule droit."},{"t":"Elle résulte toujours d'une insuffisance cardiaque gauche préexistante.","ok":false,"why":"Il existe au contraire des causes d'IC droite isolée, indépendantes d'une atteinte gauche."},{"t":"La péricardite chronique constrictive peut en être responsable.","ok":true,"why":"Elle figure parmi les causes citées d'IC droite isolée."},{"t":"L'hypertension artérielle pulmonaire ne joue aucun rôle dans ce contexte.","ok":false,"why":"L'HTAP primitive ou secondaire est au contraire une cause classique d'IC droite isolée."}],"explanation":"L'IC droite isolée peut résulter de pathologies pulmonaires, d'HTAP, de dysplasie arythmogène du VD, d'atteintes tricuspidiennes ou de péricardite constrictive, indépendamment d'une IC gauche.","src":"p. 471"},{"id":"234-qcm-107","type":"QRM","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":1,"stem":"Concernant l'insuffisance cardiaque à débit augmenté, lesquelles de ces propositions sont exactes ?","options":[{"t":"L'anémie chronique peut en être une cause.","ok":true,"why":"L'anémie chronique figure parmi les causes de surcharge en volume citées par le chapitre."},{"t":"L'hyperthyroïdie peut en être une cause.","ok":true,"why":"Le chapitre la cite explicitement comme cause d'IC à débit augmenté."},{"t":"La carence en thiamine (béribéri) peut en être une cause.","ok":true,"why":"Le béribéri est cité comme cause nutritionnelle d'IC à débit augmenté."},{"t":"Elle est exclusivement liée à une maladie valvulaire.","ok":false,"why":"Ses causes sont variées (anémie, fistules artérioveineuses, hyperthyroïdie, béribéri, Paget), non limitées aux valvulopathies."},{"t":"Les fistules artérioveineuses ne jouent aucun rôle dans ce contexte.","ok":false,"why":"Elles sont au contraire citées, notamment chez les patients hémodialysés."}],"explanation":"L'IC à débit augmenté regroupe anémie chronique, fistules artérioveineuses, hyperthyroïdie, béribéri et maladie de Paget, toutes causes de surcharge volumique chronique.","src":"p. 471"},{"id":"234-qru-102","type":"QRU","rank":"A","objective":"234-obj-07","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un patient consulte pour une dyspnée aiguë fébrile avec un foyer de crépitants localisé et un dosage de peptides natriurétiques normal. Quel diagnostic différentiel de l'OAP est le plus probable ?","options":[{"t":"Une pneumopathie aiguë infectieuse","ok":true,"why":"Le contexte fébrile, le foyer localisé et des peptides natriurétiques normaux orientent vers ce diagnostic selon le chapitre."},{"t":"Un OAP cardiogénique","ok":false,"why":"Des peptides natriurétiques normaux rendent ce diagnostic peu probable."},{"t":"Une exacerbation de BPCO","ok":false,"why":"Ce tableau évoquerait plutôt des ronchi et sibilants diffus, pas un foyer localisé fébrile."},{"t":"Une crise d'asthme","ok":false,"why":"L'asthme se caractérise par une dyspnée expiratoire sifflante, pas par un foyer fébrile localisé."},{"t":"Un choc cardiogénique","ok":false,"why":"Aucun signe d'hypoperfusion périphérique n'est décrit dans cette vignette."}],"explanation":"Un tableau fébrile avec foyer localisé et peptides natriurétiques normaux ou peu élevés oriente vers une pneumopathie infectieuse plutôt que vers un OAP cardiogénique.","src":"p. 472"},{"id":"234-qcm-108","type":"QRM","rank":"A","objective":"234-obj-07","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Concernant les diagnostics différentiels d'une dyspnée aiguë évoquant un OAP, lesquelles de ces propositions sont exactes ?","options":[{"t":"L'embolie pulmonaire s'accompagne souvent d'une auscultation pulmonaire normale.","ok":true,"why":"Le chapitre décrit cette particularité comme un argument d'orientation vers l'EP."},{"t":"L'exacerbation de BPCO s'accompagne de ronchi et de sibilants.","ok":true,"why":"Ce sont les signes auscultatoires décrits par le chapitre pour la BPCO."},{"t":"La crise d'asthme se caractérise par une dyspnée inspiratoire sifflante.","ok":false,"why":"La dyspnée de la crise d'asthme est expiratoire, et non inspiratoire."},{"t":"La pneumopathie infectieuse s'associe à une opacité systématisée à la radiographie.","ok":true,"why":"C'est l'aspect radiologique typique décrit par le chapitre pour la pneumopathie."},{"t":"Ces diagnostics différentiels n'ont aucun intérêt en pratique clinique devant une dyspnée aiguë.","ok":false,"why":"Le chapitre insiste au contraire sur la nécessité de les évoquer systématiquement."}],"explanation":"Devant une dyspnée aiguë, il faut savoir évoquer pneumopathie, embolie pulmonaire, exacerbation de BPCO et crise d'asthme, chacune ayant des caractéristiques distinctives.","src":"p. 472"},{"id":"234-qcm-109","type":"QRM","rank":"A","objective":"234-obj-11","tags":["urgence","paraclinique"],"difficulty":1,"stem":"Devant un tableau d'OAP cardiogénique aux urgences, quels examens complémentaires demandez-vous sans retarder le traitement ?","options":[{"t":"Un électrocardiogramme","ok":true,"why":"L'ECG fait partie du bilan à réaliser en urgence devant un OAP, cité par le chapitre."},{"t":"Des gaz du sang artériels","ok":true,"why":"La gazométrie artérielle est explicitement citée parmi les examens urgents d'un OAP."},{"t":"Une radiographie thoracique","ok":true,"why":"Elle est demandée pour rechercher les opacités périhilaires typiques."},{"t":"Un dosage des peptides natriurétiques et de la troponine","ok":true,"why":"Ces dosages sont cités parmi les examens à demander sans retarder le traitement."},{"t":"Une IRM cardiaque systématique en urgence","ok":false,"why":"L'IRM n'est pas un examen d'urgence dans ce contexte, contrairement aux autres examens cités."}],"explanation":"Le bilan urgent d'un OAP associe ECG, gaz du sang, radiographie thoracique, peptides natriurétiques, troponine et échocardiographie, sans jamais retarder le traitement symptomatique.","src":"p. 472"},{"id":"234-qru-103","type":"QRU","rank":"A","objective":"234-obj-11","tags":["urgence","pièges"],"difficulty":2,"stem":"Chez un patient en OAP, une élévation modérée de la troponine est mesurée. Quelle interprétation est exacte selon le chapitre ?","options":[{"t":"Elle peut se voir même en l'absence de syndrome coronarien aigu.","ok":true,"why":"Le chapitre précise explicitement qu'une élévation modérée peut survenir sans pathologie coronarienne aiguë."},{"t":"Elle affirme à elle seule un infarctus du myocarde en cours.","ok":false,"why":"Une élévation modérée ne suffit pas à affirmer un syndrome coronarien aigu associé."},{"t":"Elle doit faire suspendre le traitement de l'OAP en cours.","ok":false,"why":"Le traitement symptomatique de l'OAP ne doit jamais être retardé par les résultats biologiques."},{"t":"Elle élimine formellement toute cardiopathie ischémique sous-jacente.","ok":false,"why":"Elle ne permet ni d'affirmer ni d'éliminer une cardiopathie ischémique à elle seule."},{"t":"Elle n'a strictement aucune valeur interprétative au cours de l'OAP.","ok":false,"why":"Elle a une valeur d'interprétation, mais nuancée, ne devant pas être surinterprétée isolément."}],"explanation":"Une troponine modérément élevée au cours d'un OAP ne signe pas forcément un syndrome coronarien aigu associé et ne doit pas retarder le traitement symptomatique.","src":"p. 472"},{"id":"234-qcm-110","type":"QRM","rank":"A","objective":"234-obj-17","tags":["urgence","clinique"],"difficulty":1,"stem":"Un patient est admis pour une détresse respiratoire aiguë avec orthopnée forcée, sueurs, expectoration mousseuse et râles crépitants remontant haut dans les champs pulmonaires. Concernant ce tableau d'OAP, lesquelles de ces propositions sont exactes ?","options":[{"t":"Il s'agit d'une inondation alvéolaire liée à l'augmentation de la pression capillaire pulmonaire.","ok":true,"why":"C'est le mécanisme physiopathologique exact de l'OAP cardiogénique décrit par le chapitre."},{"t":"La hauteur des râles crépitants reflète la sévérité du tableau (« marée montante »).","ok":true,"why":"C'est l'image utilisée par le chapitre pour décrire ce signe de gravité."},{"t":"Une poussée hypertensive peut accompagner cet épisode.","ok":true,"why":"Le chapitre précise que l'OAP peut s'accompagner d'une poussée hypertensive."},{"t":"Ce tableau ne nécessite jamais d'hospitalisation.","ok":false,"why":"L'OAP est au contraire une grande urgence cardiovasculaire nécessitant une prise en charge immédiate."},{"t":"L'expectoration typique est purulente et fétide.","ok":false,"why":"L'expectoration typique de l'OAP est mousseuse et saumonée, non purulente."}],"explanation":"L'OAP cardiogénique associe polypnée, orthopnée, sueurs, expectoration mousseuse et râles crépitants ascendants, parfois avec poussée hypertensive ; c'est une urgence vitale.","src":"p. 472"},{"id":"234-qru-104","type":"QRU","rank":"A","objective":"234-obj-17","tags":["urgence"],"difficulty":2,"stem":"Quel facteur déclenchant d'une décompensation cardiaque doit être recherché en priorité chez un insuffisant cardiaque chronique ?","options":[{"t":"Une rupture ou une observance imparfaite du traitement, ou un écart du régime sans sel","ok":true,"why":"Le chapitre désigne explicitement ce facteur comme le premier à rechercher."},{"t":"Une hyperthyroïdie","ok":false,"why":"Ce facteur figure dans la liste mais n'est pas cité comme prioritaire."},{"t":"Une carence martiale","ok":false,"why":"La carence martiale est une complication associée à l'IC, non un facteur déclenchant classiquement recherché en priorité."},{"t":"Un syndrome d'apnées du sommeil","ok":false,"why":"Ce n'est pas le premier facteur déclenchant cité par le chapitre."},{"t":"Une carence en vitamine D","ok":false,"why":"Ce facteur n'est pas mentionné parmi les facteurs déclenchants du chapitre."}],"explanation":"Devant tout épisode d'IC aiguë, il faut rechercher un facteur déclenchant, le premier étant une rupture de traitement ou d'observance du régime sans sel.","src":"p. 473"},{"id":"234-qcm-111","type":"QRM","rank":"A","objective":"234-obj-17","tags":["urgence","pièges"],"difficulty":2,"stem":"Parmi les facteurs déclenchants d'une insuffisance cardiaque aiguë cités par le chapitre, lesquels sont exacts ?","options":[{"t":"Une surinfection bronchique","ok":true,"why":"Elle figure dans la liste des facteurs déclenchants du chapitre."},{"t":"Une fibrillation atriale rapide","ok":true,"why":"Les troubles du rythme, en particulier la FA, sont cités comme facteur déclenchant."},{"t":"Une anémie","ok":true,"why":"L'anémie figure explicitement parmi les facteurs déclenchants cités."},{"t":"Une carence en fer isolée, sans anémie ni autre anomalie associée","ok":false,"why":"Ce facteur isolé n'est pas mentionné dans la liste des facteurs déclenchants du chapitre."},{"t":"Une poussée hypertensive","ok":true,"why":"Elle est explicitement citée parmi les facteurs déclenchants d'IC aiguë."}],"explanation":"Les facteurs déclenchants classiques comprennent rupture de traitement, écarts de régime, surinfection, troubles du rythme, anémie, embolie pulmonaire, dysthyroïdie, causes iatrogènes et poussée hypertensive.","src":"p. 473"},{"id":"234-qru-105","type":"QRU","rank":"A","objective":"234-obj-04","tags":["urgence","définition"],"difficulty":1,"stem":"Quelle est la définition du choc cardiogénique selon le chapitre ?","options":[{"t":"Une défaillance aiguë et sévère de la fonction cardiaque entraînant une hypoperfusion périphérique profonde et une anoxie tissulaire","ok":true,"why":"C'est la définition exacte donnée par le chapitre pour le choc cardiogénique."},{"t":"Une élévation brutale de la pression artérielle avec œdème pulmonaire","ok":false,"why":"Cette description correspond plutôt à un OAP hypertensif, non à la définition du choc."},{"t":"Un trouble du rythme ventriculaire isolé sans retentissement hémodynamique","ok":false,"why":"Le choc cardiogénique implique par définition un retentissement hémodynamique majeur."},{"t":"L'état d'un patient ambulatoire suivant un traitement oral, sans décompensation","ok":false,"why":"Cette description correspond à l'insuffisance cardiaque chronique, non au choc cardiogénique."},{"t":"Un épanchement péricardique abondant sans tamponnade","ok":false,"why":"Cette description est indépendante du tableau clinique de choc cardiogénique."}],"explanation":"Le choc cardiogénique est le tableau ultime d'une défaillance cardiaque aiguë et sévère, avec effondrement du débit entraînant hypoperfusion tissulaire profonde et anoxie.","src":"p. 456, 473"},{"id":"234-qcm-112","type":"QRM","rank":"A","objective":"234-obj-22","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Un patient présente une PAS à 78 mmHg depuis 40 minutes, des extrémités froides et marbrées, une diurèse à 15 mL/h et une confusion. Concernant le diagnostic de choc cardiogénique, lesquelles de ces propositions sont exactes ?","options":[{"t":"Le critère tensionnel (PAS < 90 mmHg maintenue au moins 30 minutes) est rempli.","ok":true,"why":"La PAS à 78 mmHg depuis 40 minutes répond exactement à ce critère du chapitre."},{"t":"L'oligurie (< 20 mL/h) constitue un critère supplémentaire en faveur du diagnostic.","ok":true,"why":"Une diurèse à 15 mL/h est inférieure au seuil de 20 mL/h cité par le chapitre."},{"t":"L'altération de la conscience doit être recherchée systématiquement.","ok":true,"why":"La confusion/agitation fait partie des critères cliniques cités par le chapitre."},{"t":"Une échocardiographie confirmant un bas débit n'apporte aucune information utile.","ok":false,"why":"Elle est au contraire citée comme un des éléments du diagnostic (diminution du débit mesuré à l'échographie)."},{"t":"Le diagnostic ne peut être retenu qu'en présence d'une fièvre élevée.","ok":false,"why":"La fièvre n'est pas un critère diagnostique du choc cardiogénique selon le chapitre."}],"explanation":"Le choc cardiogénique associe PAS effondrée, signes de mauvaise perfusion (marbrures, oligurie), altération de la conscience et preuve échographique de bas débit.","src":"p. 473"},{"id":"234-qcm-113","type":"QRM","rank":"B","objective":"234-obj-23","tags":["urgence","traitement"],"difficulty":3,"stem":"Concernant les principes du traitement du choc cardiogénique, lesquelles de ces propositions sont exactes ?","options":[{"t":"Les inotropes (dobutamine) sont utilisés pour soutenir le débit cardiaque.","ok":true,"why":"Le traitement inotrope est explicitement cité comme principe de prise en charge du choc cardiogénique."},{"t":"Le lévosimendan peut aider au sevrage des inotropes.","ok":true,"why":"C'est le rôle attribué au lévosimendan, sensibilisateur calcique, par le chapitre."},{"t":"Une assistance circulatoire peut être discutée en l'absence de réponse au traitement médical.","ok":true,"why":"Le chapitre évoque cette option (ECMO, assistance prolongée) en cas d'échec du traitement médical."},{"t":"Le sondage urinaire est contre-indiqué dans cette situation.","ok":false,"why":"Au contraire, un sondage urinaire systématique est recommandé pour surveiller la diurèse."},{"t":"Le monitorage invasif de la pression artérielle n'a aucun intérêt.","ok":false,"why":"Un monitorage invasif (cathéter radial) est au contraire recommandé dans ce contexte."}],"explanation":"Le choc cardiogénique relève d'un traitement inotrope, d'un monitorage invasif et d'un sondage urinaire systématique, avec discussion d'une assistance circulatoire en l'absence de réponse.","src":"p. 486"},{"id":"234-qru-106","type":"QRU","rank":"B","objective":"234-obj-06","tags":["physiopathologie","diagnostic"],"difficulty":2,"stem":"Quelle caractéristique distingue le mécanisme de l'œdème pulmonaire lésionnel de celui de l'œdème pulmonaire cardiogénique ?","options":[{"t":"L'œdème lésionnel résulte d'une atteinte de la membrane alvéolocapillaire, indépendamment du niveau de pression capillaire pulmonaire.","ok":true,"why":"C'est la distinction exacte donnée par le chapitre entre mécanisme lésionnel et mécanisme hydrostatique."},{"t":"L'œdème lésionnel est toujours dû à une élévation de la pression capillaire pulmonaire.","ok":false,"why":"C'est au contraire le mécanisme propre à l'œdème cardiogénique, non lésionnel."},{"t":"L'œdème cardiogénique ne comporte jamais de composante transsudative.","ok":false,"why":"L'œdème cardiogénique est au contraire un transsudat lié à l'hyperpression hydrostatique."},{"t":"L'œdème lésionnel régresse toujours spontanément, sans traitement.","ok":false,"why":"Cette affirmation n'est pas soutenue par le chapitre et ne correspond pas à sa gravité potentielle."},{"t":"Les deux mécanismes sont rigoureusement identiques.","ok":false,"why":"Le chapitre insiste au contraire sur leur différence et sur l'implication immédiate de cette distinction."}],"explanation":"L'œdème lésionnel provient d'une atteinte directe de la membrane alvéolocapillaire, à la différence de l'œdème cardiogénique lié à l'élévation de la pression capillaire pulmonaire.","src":"p. 459"},{"id":"234-qcm-114","type":"QRM","rank":"B","objective":"234-obj-10","tags":["paraclinique"],"difficulty":2,"stem":"Concernant les examens complémentaires du bilan étiologique de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Le coroscanner est privilégié chez les patients ayant une probabilité coronarienne faible ou intermédiaire.","ok":true,"why":"C'est l'indication de première intention du coroscanner décrite par le chapitre."},{"t":"La coronarographie est réservée aux patients ayant un angor, une probabilité intermédiaire à haute, ou une ischémie documentée avec projet de revascularisation.","ok":true,"why":"Ce sont exactement les indications de la coronarographie données par le chapitre."},{"t":"Le cathétérisme droit mesure le débit cardiaque par thermodilution.","ok":true,"why":"C'est la technique de mesure du débit décrite par le chapitre pour le cathétérisme droit."},{"t":"L'IRM cardiaque ne peut jamais orienter vers une amylose ou une myocardite.","ok":false,"why":"L'IRM peut au contraire orienter vers ces diagnostics grâce au rehaussement tardif et à d'autres séquences spécifiques."},{"t":"Le pic de consommation d'oxygène (VO2) à l'épreuve d'effort n'a aucune valeur pronostique.","ok":false,"why":"Il a au contraire une valeur pronostique reconnue, pouvant orienter vers une greffe cardiaque si très abaissé."}],"explanation":"Coroscanner et coronarographie ont des indications différentes selon la probabilité coronarienne ; cathétérisme droit, IRM et épreuve d'effort avec VO2 complètent le bilan étiologique et pronostique.","src":"p. 467-468"},{"id":"234-qcm-115","type":"QRM","rank":"A","objective":"234-obj-21","tags":["complications","suivi"],"difficulty":2,"stem":"Concernant les complications et le pronostic de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"La mortalité moyenne à 5 ans avoisine 50 %.","ok":true,"why":"C'est le chiffre donné par le chapitre pour la mortalité moyenne à 5 ans."},{"t":"La mortalité annuelle peut atteindre 40 à 50 % au stade NYHA IV.","ok":true,"why":"C'est la valeur exacte donnée par le chapitre pour ce stade sévère."},{"t":"La mort subite rythmique et l'IC réfractaire sont les deux principaux mécanismes de décès.","ok":true,"why":"Ce sont les deux causes de décès explicitement citées par le chapitre."},{"t":"Les comorbidités n'influencent pas le pronostic de l'IC.","ok":false,"why":"Le chapitre insiste au contraire sur leur impact défavorable sur le pronostic et la tolérance des traitements."},{"t":"Une hyponatrémie constitue un facteur pronostique favorable.","ok":false,"why":"C'est l'inverse : l'hyponatrémie est citée comme facteur pronostique défavorable."}],"explanation":"La mortalité de l'IC reste élevée (50 % à 5 ans, jusqu'à 40-50 %/an en NYHA IV), dominée par la mort subite et l'IC réfractaire ; comorbidités et hyponatrémie aggravent le pronostic.","src":"p. 475"},{"id":"234-qcm-116","type":"QRM","rank":"A","objective":"234-obj-19","tags":["prévention","suivi"],"difficulty":1,"stem":"Concernant les mesures hygiénodiététiques de l'insuffisance cardiaque, lesquelles de ces propositions sont exactes ?","options":[{"t":"Le régime hyposodé cible ne pas dépasser 5 à 6 g de sel par jour.","ok":true,"why":"C'est l'objectif quantitatif donné par le chapitre pour le régime sans sel."},{"t":"Une prise de poids de 2 à 3 kg en 2-3 jours doit inciter à consulter rapidement.","ok":true,"why":"C'est le seuil d'alerte donné par le chapitre pour la surveillance pondérale."},{"t":"Le repos physique strict est recommandé en dehors des poussées.","ok":false,"why":"Le chapitre indique au contraire que le repos strict est délétère, favorisant le déconditionnement."},{"t":"L'arrêt du tabac est impératif chez tous les patients.","ok":true,"why":"Le chapitre le qualifie d'impératif, en particulier en cas de cardiopathie ischémique."},{"t":"Les vaccinations antigrippale et antipneumococcique sont déconseillées.","ok":false,"why":"Elles sont au contraire recommandées, une surinfection pouvant déclencher une décompensation."}],"explanation":"Les mesures générales associent régime hyposodé (5-6 g/j), surveillance du poids, activité physique régulière (jamais de repos strict), sevrage tabagique et vaccinations recommandées.","src":"p. 476-477"},{"id":"234-qroc-101","type":"QROC","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":1,"question":"Quelle est la première cause d'insuffisance cardiaque aujourd'hui, toutes causes confondues ?","answer":"La cardiopathie ischémique","accept":["cause ischémique","coronaropathie"],"keywords":["ischémique"],"explanation":"La cardiopathie ischémique, le plus souvent par infarctus du myocarde, est la première cause globale d'IC.","src":"p. 469"},{"id":"234-qroc-102","type":"QROC","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":1,"question":"Chez le sujet jeune, quelle cardiomyopathie représente la première cause d'insuffisance cardiaque et de transplantation ?","answer":"La cardiomyopathie dilatée (CMD)","accept":["CMD"],"keywords":["dilatée"],"explanation":"La CMD est la première cause d'IC et de transplantation cardiaque chez le sujet jeune, avec de multiples étiologies possibles.","src":"p. 469"},{"id":"234-qroc-103","type":"QROC","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"question":"Quel gène est, avec celui de la protéine C cardiaque, le plus fréquemment en cause dans la cardiomyopathie hypertrophique familiale ?","answer":"Le gène de la chaîne lourde bêta de la myosine","accept":["gène de la myosine","chaîne lourde de la myosine"],"keywords":["myosine"],"explanation":"La CMH familiale est le plus souvent liée à des mutations des gènes du sarcomère, en particulier celui de la chaîne lourde bêta de la myosine et celui de la protéine C cardiaque.","src":"p. 470"},{"id":"234-qroc-104","type":"QROC","rank":"B","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"question":"Quelle cardiomyopathie restrictive est la plus fréquente, avec un pronostic généralement sévère ?","answer":"L'amylose cardiaque","accept":["amylose"],"keywords":["amylose"],"explanation":"L'amylose cardiaque, par dépôts extracellulaires, est la cardiomyopathie restrictive la plus fréquente et son pronostic est sévère une fois l'IC symptomatique.","src":"p. 470"},{"id":"234-qroc-105","type":"QROC","rank":"A","objective":"234-obj-07","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic différentiel de l'OAP évoquer devant une dyspnée aiguë avec un contexte à risque et une auscultation pulmonaire souvent normale ?","answer":"L'embolie pulmonaire","accept":["EP"],"keywords":["embolie","pulmonaire"],"explanation":"L'embolie pulmonaire se caractérise par une auscultation pulmonaire souvent normale malgré une dyspnée aiguë, contrairement à l'OAP ou à la BPCO.","src":"p. 472"},{"id":"234-qroc-106","type":"QROC","rank":"A","objective":"234-obj-17","tags":["urgence"],"difficulty":1,"question":"Quelle expression imagée décrit la remontée progressive des râles crépitants, proportionnelle à la sévérité de l'OAP ?","answer":"La marée montante des râles crépitants","accept":["marée montante"],"keywords":["marée","montante"],"explanation":"Plus les râles crépitants remontent haut dans les champs pulmonaires, plus le tableau d'OAP est sévère : c'est l'image de la « marée montante ».","src":"p. 472"},{"id":"234-qroc-107","type":"QROC","rank":"A","objective":"234-obj-17","tags":["urgence","pièges"],"difficulty":2,"question":"Quel est le premier facteur déclenchant à rechercher devant une décompensation cardiaque chez un patient déjà suivi ?","answer":"Une rupture de traitement ou d'observance du régime sans sel","accept":["mauvaise observance thérapeutique","écart de régime"],"keywords":["rupture","traitement"],"explanation":"Le chapitre désigne la rupture ou l'observance imparfaite du traitement (médicamenteux ou du régime sans sel) comme le premier facteur déclenchant à rechercher.","src":"p. 473"},{"id":"234-qroc-108","type":"QROC","rank":"A","objective":"234-obj-04","tags":["urgence","définition"],"difficulty":1,"question":"En dessous de quelle valeur de pression artérielle systolique, maintenue au moins 30 minutes, retient-on le critère tensionnel du choc cardiogénique ?","answer":"90 mmHg","accept":["< 90 mmHg"],"keywords":["90"],"explanation":"Une PAS < 90 mmHg (ou une chute > 30 mmHg par rapport à la valeur de base) maintenue au moins 30 minutes définit le critère tensionnel du choc cardiogénique.","src":"p. 473"},{"id":"234-qroc-109","type":"QROC","rank":"A","objective":"234-obj-22","tags":["urgence"],"difficulty":1,"question":"Quel seuil de diurèse horaire définit l'oligurie du choc cardiogénique ?","answer":"Moins de 20 mL/h","accept":["< 20 mL/h"],"keywords":["20"],"explanation":"Une diurèse inférieure à 20 mL/h fait partie des critères d'hypoperfusion périphérique du choc cardiogénique.","src":"p. 473"},{"id":"234-qroc-110","type":"QROC","rank":"A","objective":"234-obj-08","tags":["diagnostic"],"difficulty":2,"question":"Citez au moins trois critères diagnostiques de l'insuffisance cardiaque à fraction d'éjection préservée mentionnés dans le chapitre.","answer":"Symptômes/signes d'IC, FEVG > 50 % à l'échographie, élévation du BNP/NT-proBNP, argument pour des pressions de remplissage élevées ou une HVG/dilatation de l'atrium gauche","accept":["fevg normale, bnp eleve, hvg"],"keywords":["fevg","bnp","remplissage"],"explanation":"Le diagnostic d'IC à FE préservée associe des symptômes/signes d'IC, une FEVG > 50 % sans autre cause, une élévation du BNP/NT-proBNP et des arguments de trouble du remplissage.","src":"p. 473-474"},{"id":"234-qroc-111","type":"QROC","rank":"B","objective":"234-obj-10","tags":["paraclinique"],"difficulty":2,"question":"Au-delà de quelle valeur de résistances artérielles pulmonaires (en unités Wood) la greffe cardiaque est-elle contre-indiquée ?","answer":"5 unités Wood","accept":["> 5 unités Wood","supérieur à 5 unités Wood"],"keywords":["5","wood"],"explanation":"Des résistances artérielles pulmonaires supérieures à 5 unités Wood, mesurées au cathétérisme droit, contre-indiquent la transplantation cardiaque.","src":"p. 468"},{"id":"234-open-11","type":"OPEN","rank":"A","objective":"234-obj-17","tags":["urgence","diagnostic"],"difficulty":2,"prompt":"M. B., 74 ans, connu pour une cardiopathie ischémique, est amené aux urgences en détresse respiratoire aiguë avec orthopnée, sueurs et râles crépitants bilatéraux remontant à mi-champs. Sa pression artérielle est à 145/85 mmHg. Décrivez votre démarche diagnostique immédiate (sans retarder le traitement) et les principaux diagnostics différentiels à écarter.","rubric":[{"point":"Évoque un OAP cardiogénique devant ce tableau clinique typique","weight":2},{"point":"Cite le bilan à réaliser sans retarder le traitement : ECG, gaz du sang, radiographie, peptides natriurétiques, troponine, échographie","weight":3},{"point":"Cite les diagnostics différentiels à évoquer : pneumopathie, embolie pulmonaire, exacerbation de BPCO, crise d'asthme","weight":3},{"point":"Précise un argument distinctif pour au moins deux de ces diagnostics différentiels","weight":2}],"model":"Le tableau (orthopnée, sueurs, râles crépitants ascendants) évoque en premier lieu un OAP cardiogénique chez ce patient à risque. Le bilan (ECG, gaz du sang artériels, radiographie thoracique, dosage des peptides natriurétiques et de la troponine, échocardiographie) doit être réalisé sans retarder le traitement symptomatique. Il faut évoquer systématiquement les diagnostics différentiels d'une dyspnée aiguë : pneumopathie infectieuse (contexte fébrile, foyer localisé, opacité systématisée), embolie pulmonaire (auscultation souvent normale, contexte à risque), exacerbation de BPCO (ronchi, sibilants, antécédents) et crise d'asthme (dyspnée expiratoire sifflante).","src":"p. 472"},{"id":"234-open-12","type":"OPEN","rank":"A","objective":"234-obj-16","tags":["étiologie"],"difficulty":2,"prompt":"Décrivez les principales étiologies de l'insuffisance cardiaque à prendre en compte devant une FEVG abaissée de découverte récente, en précisant la cause à rechercher en priorité.","rubric":[{"point":"Recherche prioritaire d'une cardiopathie ischémique (coronarographie ou coroscanner)","weight":3},{"point":"Évoque l'HTA comme cause directe (postcharge) ou indirecte (athérome)","weight":2},{"point":"Évoque les cardiomyopathies (dilatée, hypertrophique, restrictive) après élimination des causes précédentes","weight":2},{"point":"Cite les valvulopathies gauches et les causes rythmiques (tachycardiomyopathie)","weight":2},{"point":"Mentionne que le diagnostic de cardiomyopathie est un diagnostic d'élimination","weight":1}],"model":"Devant toute FEVG abaissée, il faut en priorité éliminer une cause ischémique par coronarographie ou coroscanner, la cardiopathie ischémique étant la première cause globale d'IC. L'HTA peut également être en cause, directement (surcharge de postcharge) ou indirectement (favorisant l'athérome coronaire). Une fois ces causes, ainsi qu'une valvulopathie ou une cardiopathie congénitale, éliminées, on évoque une cardiomyopathie (dilatée, hypertrophique ou restrictive), diagnostic d'élimination. Il faut enfin rechercher une cause rythmique, une tachycardie rapide et prolongée pouvant entraîner une tachycardiomyopathie curable par le traitement du trouble du rythme.","src":"p. 469-471"},{"id":"234-open-13","type":"OPEN","rank":"A","objective":"234-obj-22","tags":["urgence","diagnostic","traitement"],"difficulty":3,"prompt":"Un patient hospitalisé pour un infarctus étendu développe une hypotension à 75/50 mmHg, des marbrures et une oligurie. Décrivez la démarche diagnostique du choc cardiogénique et les grands principes de sa prise en charge selon le chapitre.","rubric":[{"point":"Cite les critères diagnostiques : PAS < 90 mmHg ≥ 30 min, hypoperfusion périphérique, oligurie < 20 mL/h, altération de la conscience, bas débit à l'échographie","weight":3},{"point":"Précise que le pronostic est très défavorable","weight":1},{"point":"Cite le traitement inotrope (dobutamine, éventuellement lévosimendan)","weight":2},{"point":"Cite la surveillance (sondage urinaire, monitorage invasif de la pression artérielle)","weight":2},{"point":"Évoque l'assistance circulatoire en l'absence de réponse","weight":2}],"model":"Le diagnostic de choc cardiogénique associe une PAS < 90 mmHg (ou une chute > 30 mmHg) maintenue au moins 30 minutes, des signes d'hypoperfusion périphérique (extrémités froides, marbrées), une oligurie < 20 mL/h, une altération de la conscience et une preuve échographique de bas débit ; le pronostic est très défavorable. La prise en charge repose sur un traitement inotrope (dobutamine, ou inhibiteurs des phosphodiestérases si le patient est sous bêtabloquant), avec sondage urinaire systématique et monitorage invasif de la pression artérielle. Le lévosimendan peut aider au sevrage des inotropes. En l'absence de réponse, une assistance circulatoire (ECMO ou assistance prolongée) doit être discutée.","src":"p. 473, 486"},{"id":"234-qcm-201","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":1,"stem":"Parmi les molécules suivantes, lesquelles ont démontré une efficacité en tant que bêtabloquant dans l'insuffisance cardiaque à FE diminuée ?","options":[{"t":"Carvédilol","ok":true,"why":"Une des quatre molécules dont l'efficacité a été démontrée dans l'IC à FE diminuée."},{"t":"Métoprolol","ok":true,"why":"Une des quatre molécules dont l'efficacité a été démontrée dans l'IC à FE diminuée."},{"t":"Bisoprolol","ok":true,"why":"Une des quatre molécules dont l'efficacité a été démontrée dans l'IC à FE diminuée."},{"t":"Nébivolol","ok":true,"why":"Une des quatre molécules dont l'efficacité a été démontrée dans l'IC à FE diminuée."},{"t":"Aténolol","ok":false,"why":"N'est pas cité parmi les bêtabloquants validés dans cette indication."}],"explanation":"Seuls quatre bêtabloquants ont une efficacité démontrée dans l'IC à FE diminuée : carvédilol, métoprolol, bisoprolol et nébivolol. Les autres molécules de la classe ne sont pas validées dans cette indication.","src":"p. 479"},{"id":"234-qcm-202","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant les bénéfices attendus d'un traitement bêtabloquant bien conduit chez un patient stabilisé en insuffisance cardiaque à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"Il améliore les symptômes","ok":true,"why":"Effet symptomatique démontré chez le patient stabilisé."},{"t":"Il diminue la mortalité globale","ok":true,"why":"Effet sur la mortalité démontré, comme les autres classes cardioprotectrices."},{"t":"Il diminue la fréquence des hospitalisations pour IC aiguë","ok":true,"why":"Réduction du risque de décompensation nécessitant une hospitalisation."},{"t":"Il diminue le risque de mort subite par arythmie","ok":true,"why":"Effet antiarythmique protecteur démontré."},{"t":"Il doit être débuté d'emblée à la dose maximale tolérée","ok":false,"why":"L'instauration se fait au contraire à très faible dose, avec augmentation très progressive."}],"explanation":"Chez un patient stabilisé, le bêtabloquant améliore les symptômes et réduit la mortalité, les hospitalisations pour IC et le risque de mort subite rythmique. Ces bénéfices supposent une instauration prudente, à dose initiale très faible.","src":"p. 479"},{"id":"234-qcm-203","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Un patient de 70 ans, insuffisant cardiaque à FE diminuée, débute un traitement par bisoprolol. Quelles modalités d'introduction sont conformes ?","options":[{"t":"Le traitement est débuté chez un patient stabilisé, sans signe de décompensation","ok":true,"why":"Condition indispensable avant toute introduction."},{"t":"La dose initiale est très faible, de l'ordre du huitième de la dose maximale","ok":true,"why":"Principe général d'instauration à très faible dose."},{"t":"La dose est augmentée par paliers hebdomadaires selon la tolérance","ok":true,"why":"Titration progressive, semaine après semaine."},{"t":"La dose cible de bisoprolol peut atteindre 10 mg par jour","ok":true,"why":"Dose maximale citée pour le bisoprolol."},{"t":"Le traitement peut être débuté en pleine poussée d'insuffisance cardiaque aiguë pour accélérer la stabilisation","ok":false,"why":"Une introduction en pleine poussée aiguë est une faute ; il faut attendre la stabilisation du patient."}],"explanation":"L'introduction d'un bêtabloquant obéit à des règles strictes : patient stabilisé, dose initiale très faible (environ 1/8e de la dose maximale), titration par paliers hebdomadaires jusqu'à la dose cible (10 mg/j pour le bisoprolol). Le débuter en pleine décompensation est une faute reconnue.","src":"p. 479","trap":"Confondre « patient hospitalisé pour IC » et « patient en pleine poussée aiguë » : l'introduction reste possible juste avant la sortie, une fois le patient stabilisé."},{"id":"234-qru-201","type":"QRU","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":1,"stem":"Quelle est la contre-indication absolue suivante à l'introduction d'un traitement bêtabloquant dans l'IC à FE diminuée ?","options":[{"t":"Un asthme ou une BPCO sévère","ok":true,"why":"Contre-indication formelle citée par le référentiel, avec la bradycardie/hypotension symptomatique et le BAV de haut degré."},{"t":"Une fraction d'éjection à 32 %","ok":false,"why":"C'est au contraire l'indication même du traitement bêtabloquant."},{"t":"Un antécédent d'infarctus du myocarde","ok":false,"why":"N'est pas une contre-indication ; le bêtabloquant est même recommandé en post-IDM avec FE basse."},{"t":"Une classe NYHA II","ok":false,"why":"N'est pas une contre-indication ; c'est au contraire une situation où le traitement est indiqué."},{"t":"Un traitement par IEC bien toléré","ok":false,"why":"L'association IEC-bêtabloquant est au contraire la base du traitement de fond."}],"explanation":"Les contre-indications au bêtabloquant dans l'IC sont l'asthme ou la BPCO sévère, la bradycardie ou l'hypotension symptomatique, et le BAV du 2e ou 3e degré.","src":"p. 479"},{"id":"234-qcm-204","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":3,"stem":"Un patient insuffisant cardiaque déjà traité au long cours par bêtabloquant est hospitalisé pour une décompensation cardiaque. Que faut-il faire vis-à-vis du bêtabloquant ?","options":[{"t":"Il n'est en règle pas recommandé de l'arrêter systématiquement","ok":true,"why":"Le maintien du bêtabloquant est en règle préconisé chez un patient déjà traité au long cours qui se décompense."},{"t":"Un arrêt peut se discuter en cas de mauvaise réponse au traitement","ok":true,"why":"Situation où l'arrêt devient justifié."},{"t":"Un arrêt peut se discuter en cas de choc cardiogénique","ok":true,"why":"Le choc cardiogénique justifie l'arrêt ou la réduction du bêtabloquant."},{"t":"Il doit être systématiquement augmenté dès l'admission pour accélérer l'amélioration","ok":false,"why":"Aucune augmentation de dose n'est recommandée en phase de décompensation."},{"t":"Il doit être remplacé d'emblée par de l'amiodarone","ok":false,"why":"L'amiodarone n'est pas un substitut du bêtabloquant ; ce sont deux classes différentes."}],"explanation":"Chez un patient déjà sous bêtabloquant au long cours qui se décompense, l'arrêt systématique n'est pas recommandé : il n'est envisagé qu'en cas de mauvaise réponse au traitement ou de choc cardiogénique. Ceci diffère de l'OAP inaugural, où le bêtabloquant n'est jamais débuté et où un traitement déjà en cours est le plus souvent réduit ou arrêté.","src":"p. 479","trap":"Ne pas confondre l'attitude vis-à-vis d'un bêtabloquant déjà en cours (maintien préférentiel) et l'attitude vis-à-vis de son introduction (jamais en poussée aiguë)."},{"id":"234-qcm-205","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":1,"stem":"Concernant les antialdostérones (spironolactone, éplérénone) dans l'IC à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"Ce sont des diurétiques épargneurs de potassium","ok":true,"why":"Classe pharmacologique de base des antialdostérones."},{"t":"Ils sont indiqués chez tous les patients en classe NYHA II à IV avec FE basse","ok":true,"why":"Indication large dans l'IC à FE diminuée symptomatique."},{"t":"Leur prescription réduit la mortalité et les épisodes de décompensation","ok":true,"why":"Bénéfice démontré sur la mortalité et les décompensations."},{"t":"Ils sont dépourvus de tout risque lorsqu'ils sont associés à un IEC","ok":false,"why":"L'association à un IEC majore au contraire le risque d'hyperkaliémie et d'insuffisance rénale."},{"t":"Ils sont contre-indiqués en cas d'hyperkaliémie","ok":true,"why":"Contre-indication formelle en cas d'hyperkaliémie ou d'insuffisance rénale."}],"explanation":"Les antialdostérones sont des diurétiques épargneurs de potassium indiqués dès la classe NYHA II avec FE basse ; ils réduisent la mortalité et les décompensations, mais exposent à l'hyperkaliémie et à l'insuffisance rénale, surtout en association à un IEC, ce qui les contre-indique en cas d'hyperkaliémie.","src":"p. 479"},{"id":"234-qcm-206","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant les effets indésirables propres à la spironolactone, quelles propositions sont exactes ?","options":[{"t":"Gynécomastie","ok":true,"why":"Effet indésirable classique de la spironolactone, lié à son action antiandrogénique."},{"t":"Impuissance","ok":true,"why":"Effet indésirable classique de la spironolactone."},{"t":"Hyperkaliémie","ok":true,"why":"Effet indésirable partagé avec l'ensemble de la classe des antialdostérones."},{"t":"Toux sèche","ok":false,"why":"Effet indésirable typique des IEC, pas des antialdostérones."},{"t":"Acidocétose","ok":false,"why":"Effet indésirable des gliflozines, pas des antialdostérones."}],"explanation":"Outre l'hyperkaliémie commune à la classe, la spironolactone expose spécifiquement à la gynécomastie et à l'impuissance. La toux sèche évoque un IEC, l'acidocétose une gliflozine.","src":"p. 479"},{"id":"234-qcm-207","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":1,"stem":"Concernant les gliflozines (dapagliflozine, empagliflozine) dans l'insuffisance cardiaque, quelles propositions sont exactes ?","options":[{"t":"Elles ont été initialement développées comme antidiabétiques","ok":true,"why":"Classe issue du traitement du diabète, par effet glycosurique."},{"t":"Leur efficacité concerne aussi bien le patient diabétique que non diabétique","ok":true,"why":"Bénéfice démontré quel que soit le statut diabétique."},{"t":"Elles diminuent la mortalité cardiovasculaire et les hospitalisations pour IC","ok":true,"why":"Bénéfice majeur démontré sur ces deux critères."},{"t":"Elles ont un fort effet hypotenseur limitant leur usage","ok":false,"why":"Elles sont au contraire très peu hypotensives."},{"t":"Tous leurs mécanismes d'action dans l'IC sont parfaitement élucidés","ok":false,"why":"En dehors de l'effet diurétique, leurs autres mécanismes ne sont pas encore parfaitement élucidés."}],"explanation":"Les gliflozines, développées à l'origine comme antidiabétiques, réduisent la mortalité cardiovasculaire et les hospitalisations pour IC, que le patient soit diabétique ou non. Elles sont peu hypotensives, et leurs mécanismes d'action au-delà de l'effet diurétique restent partiellement incompris.","src":"p. 479-480"},{"id":"234-qru-202","type":"QRU","rank":"A","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Chez un patient diabétique traité par gliflozine pour son insuffisance cardiaque, quel effet indésirable redouter particulièrement ?","options":[{"t":"Une acidocétose","ok":true,"why":"Risque particulier chez le patient diabétique traité par gliflozine."},{"t":"Une hypertension artérielle sévère","ok":false,"why":"Les gliflozines sont très peu hypotensives, elles n'induisent pas d'hypertension."},{"t":"Une hyperkaliémie majeure","ok":false,"why":"N'est pas l'effet indésirable caractéristique des gliflozines."},{"t":"Une bradycardie extrême","ok":false,"why":"N'est pas rapporté avec les gliflozines."},{"t":"Une gynécomastie","ok":false,"why":"Effet indésirable de la spironolactone, non des gliflozines."}],"explanation":"Les effets indésirables des gliflozines sont surtout les infections génitales et, chez le patient diabétique, l'acidocétose. Elles peuvent aussi entraîner une discrète altération initiale de la fonction rénale, avec un effet protecteur rénal à long terme.","src":"p. 480"},{"id":"234-qcm-208","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant les diurétiques de l'anse dans l'IC à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"Le furosémide en fait partie","ok":true,"why":"Diurétique de l'anse de référence (Lasilix®)."},{"t":"La posologie orale est adaptée aux apports sodés du patient","ok":true,"why":"Principe d'adaptation individuelle de la dose."},{"t":"La dose peut varier d'environ 20 mg/j dans les formes légères à 500 mg/j, voire 1 g/j dans les formes sévères","ok":true,"why":"Fourchette posologique citée pour les formes légères à sévères."},{"t":"Un patient bien éduqué peut adapter lui-même sa posologie à ses apports sodés","ok":true,"why":"Autonomie thérapeutique possible chez le patient éduqué."},{"t":"Ils ont démontré une réduction de la mortalité dans l'IC","ok":false,"why":"Les diurétiques de l'anse traitent la congestion mais n'ont pas d'effet démontré sur la mortalité."}],"explanation":"Les diurétiques de l'anse (furosémide, bumétanide) traitent la rétention hydrosodée à une dose adaptée aux apports sodés, de 20 mg/j à 1 g/j selon la sévérité ; un patient éduqué peut ajuster lui-même sa dose. Contrairement aux 4 classes cardioprotectrices, ils n'ont pas démontré de bénéfice sur la mortalité.","src":"p. 480"},{"id":"234-qru-203","type":"QRU","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Dans quelle situation les diurétiques thiazidiques sont-ils utilisés dans l'IC à FE diminuée ?","options":[{"t":"En association au furosémide, dans les formes résistantes avec signes congestifs persistants","ok":true,"why":"Indication précise réservée aux formes résistantes, en association au diurétique de l'anse."},{"t":"En 1re intention systématique, avant tout diurétique de l'anse","ok":false,"why":"Ce sont au contraire les diurétiques de l'anse qui sont utilisés en 1re intention."},{"t":"Seulement chez le patient normotendu sans signe congestif","ok":false,"why":"Ils sont au contraire réservés aux formes avec rétention hydrosodée persistante."},{"t":"En remplacement systématique des antialdostérones","ok":false,"why":"Ce sont deux classes distinctes, non interchangeables."},{"t":"Uniquement en cas de contre-indication aux IEC","ok":false,"why":"Leur indication ne dépend pas du statut vis-à-vis des IEC."}],"explanation":"Les thiazidiques sont réservés aux formes graves d'IC résistantes aux diurétiques de l'anse, lorsque persistent des signes de rétention hydrosodée malgré de fortes doses de furosémide ; ils sont alors associés au furosémide.","src":"p. 480"},{"id":"234-qcm-209","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant l'ivabradine dans l'IC à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"Son seul effet pharmacologique est de ralentir la fréquence cardiaque","ok":true,"why":"Mécanisme d'action unique par blocage du courant If."},{"t":"Elle est réservée au patient en rythme sinusal","ok":true,"why":"Condition indispensable à son utilisation, inefficace en FA."},{"t":"Elle peut être proposée en cas de fréquence cardiaque élevée malgré un bêtabloquant bien conduit","ok":true,"why":"Indication princeps chez le patient restant tachycarde sous bêtabloquant."},{"t":"Elle peut être envisagée en cas d'intolérance ou de contre-indication aux bêtabloquants","ok":true,"why":"Alternative possible lorsque le bêtabloquant n'est pas utilisable."},{"t":"Elle a démontré une réduction de la mortalité globale","ok":false,"why":"Le bénéfice démontré porte sur la réduction du risque d'hospitalisation pour IC, non sur la mortalité globale."}],"explanation":"L'ivabradine ralentit spécifiquement la fréquence cardiaque en bloquant le courant If ; elle est réservée au patient symptomatique en rythme sinusal, avec une fréquence cardiaque élevée malgré (ou en cas d'intolérance à) un bêtabloquant. Elle diminue le risque d'hospitalisation pour IC, sans bénéfice démontré sur la mortalité.","src":"p. 480"},{"id":"234-qcm-210","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant la digoxine dans l'insuffisance cardiaque, quelles propositions sont exactes ?","options":[{"t":"Elle peut améliorer les symptômes chez un patient restant symptomatique malgré un traitement optimal","ok":true,"why":"Bénéfice symptomatique possible en association aux traitements précédents."},{"t":"Son effet sur la survie est neutre","ok":true,"why":"Absence d'effet démontré sur la mortalité."},{"t":"Sa marge thérapeutique est étroite, avec un risque de surdosage notamment en cas d'insuffisance rénale","ok":true,"why":"Risque de toxicité bien connu de la digoxine."},{"t":"Elle garde une place en cas de fibrillation atriale pour ralentir la fréquence cardiaque","ok":true,"why":"Indication conservée dans le contrôle de la fréquence en FA."},{"t":"Sa prescription ne nécessite aucune surveillance biologique particulière","ok":false,"why":"Elle justifie au contraire un dosage régulier de sa concentration plasmatique."}],"explanation":"La digoxine, molécule la plus ancienne de l'IC, améliore parfois les symptômes des patients restant symptomatiques mais a un effet neutre sur la survie ; sa marge thérapeutique étroite impose une surveillance régulière de sa concentration plasmatique, en particulier en cas d'insuffisance rénale.","src":"p. 480"},{"id":"234-qcm-211","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":3,"stem":"Concernant l'amiodarone chez l'insuffisant cardiaque à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"C'est le seul antiarythmique utilisable dans cette population","ok":true,"why":"Statut particulier de l'amiodarone, seul antiarythmique autorisé dans l'IC à FE diminuée."},{"t":"Elle a démontré une réduction de la mortalité chez l'insuffisant cardiaque","ok":false,"why":"Aucune preuve d'efficacité sur la mortalité ou la mort subite n'a été apportée."},{"t":"Elle peut être associée à un traitement bêtabloquant","ok":true,"why":"Association possible avec le bêtabloquant."},{"t":"Elle est réservée aux troubles du rythme ventriculaire graves ou à la fibrillation atriale réduite pour prévenir les récidives","ok":true,"why":"Indications précises de l'amiodarone dans l'IC."},{"t":"Elle peut être prescrite en 1re intention pour tout patient en fibrillation atriale permanente sans autre indication","ok":false,"why":"N'est pas une indication systématique ; elle est réservée à la prévention des récidives après réduction."}],"explanation":"L'amiodarone est le seul antiarythmique utilisable dans l'IC à FE diminuée, réservé aux troubles du rythme ventriculaire graves ou à la prévention des récidives après réduction d'une FA ; elle peut être associée au bêtabloquant, mais n'a jamais démontré de bénéfice sur la mortalité.","src":"p. 481"},{"id":"234-qcm-212","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant les antithrombotiques chez l'insuffisant cardiaque, quelles propositions sont exactes ?","options":[{"t":"Le score CHA2DS2-VA évalue le risque embolique en cas de fibrillation atriale","ok":true,"why":"Score de référence pour l'évaluation du risque thromboembolique en FA."},{"t":"Le score HAS-BLED évalue le risque hémorragique","ok":true,"why":"Score de référence pour le risque hémorragique."},{"t":"En cas de fibrillation atriale, les anticoagulants oraux directs sont privilégiés par rapport aux antivitamines K","ok":true,"why":"Préférence donnée aux AOD sur les AVK en cas de FA."},{"t":"Un thrombus intracavitaire ne justifie pas d'anticoagulation","ok":false,"why":"Un thrombus intracavitaire est au contraire une indication d'anticoagulation."},{"t":"Une cardiopathie ischémique stable justifie habituellement un traitement par aspirine","ok":true,"why":"Antiagrégation simple habituelle en cas de cardiopathie ischémique stable."}],"explanation":"Chez l'insuffisant cardiaque, l'aspirine est habituelle en cas de cardiopathie ischémique stable, les anticoagulants oraux directs sont privilégiés aux AVK en cas de FA (évaluation par CHA2DS2-VA et HAS-BLED), et un thrombus intracavitaire ou un AVC embolique justifie également une anticoagulation.","src":"p. 481"},{"id":"234-qru-204","type":"QRU","rank":"A","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Quel médicament est formellement contre-indiqué dans l'insuffisance cardiaque systolique en raison de son effet inotrope négatif ?","options":[{"t":"Le vérapamil","ok":true,"why":"Inhibiteur calcique bradycardisant contre-indiqué dans l'IC systolique pour son effet dépresseur sur la contractilité."},{"t":"L'amlodipine","ok":false,"why":"Dihydropyridine à effet neutre sur la mortalité, utilisable si une indication associée existe."},{"t":"Le bisoprolol","ok":false,"why":"Bêtabloquant recommandé dans l'IC à FE diminuée, non contre-indiqué."},{"t":"La dapagliflozine","ok":false,"why":"Gliflozine recommandée dans l'IC, non contre-indiquée."},{"t":"La spironolactone","ok":false,"why":"Antialdostérone recommandée dans l'IC à FE diminuée, non contre-indiquée."}],"explanation":"Le vérapamil et le diltiazem, inhibiteurs calciques bradycardisants, sont contre-indiqués dans l'IC systolique car ils peuvent déprimer la contractilité myocardique. Les dihydropyridines (amlodipine, félodipine) sont en revanche neutres sur la mortalité et utilisables si besoin.","src":"p. 481"},{"id":"234-qcm-213","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement","pièges"],"difficulty":1,"stem":"Parmi les médicaments suivants, lesquels sont contre-indiqués ou à éviter dans l'IC à FE diminuée ?","options":[{"t":"Le diltiazem","ok":true,"why":"Effet inotrope négatif contre-indiquant son usage dans l'IC systolique."},{"t":"Le flécaïnide","ok":true,"why":"Antiarythmique de classe I contre-indiqué dans l'IC."},{"t":"Les anti-inflammatoires non stéroïdiens","ok":true,"why":"À éviter en raison du risque de rétention hydrosodée."},{"t":"L'amlodipine","ok":false,"why":"Dihydropyridine neutre sur la mortalité, utilisable si indication associée."},{"t":"Le furosémide","ok":false,"why":"Traitement symptomatique usuel de la rétention hydrosodée dans l'IC, non contre-indiqué."}],"explanation":"Sont contre-indiqués ou déconseillés dans l'IC à FE diminuée : le diltiazem et le vérapamil (effet inotrope négatif), le flécaïnide et les autres antiarythmiques de classe I, ainsi que les AINS (risque de rétention hydrosodée). Le furosémide et l'amlodipine ne sont pas concernés.","src":"p. 481"},{"id":"234-qcm-214","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant la resynchronisation cardiaque par stimulateur biventriculaire, quelles propositions sont exactes ?","options":[{"t":"Elle nécessite une sonde en atrium droit, une en ventricule droit et une en regard de la paroi latérale du VG","ok":true,"why":"Description du positionnement des trois sondes, la dernière via le sinus coronaire."},{"t":"Elle est réservée aux patients ayant une FEVG inférieure ou égale à 35 %","ok":true,"why":"Seuil de FEVG requis pour l'indication."},{"t":"Elle nécessite une durée de QRS supérieure ou égale à 130 ms","ok":true,"why":"Seuil de durée de QRS requis pour l'indication."},{"t":"Son efficacité est indépendante de la morphologie du QRS et de l'étiologie de la cardiopathie","ok":false,"why":"L'efficacité est au contraire meilleure en cas de bloc de branche gauche, de QRS ≥ 150 ms et de cardiopathie non ischémique."},{"t":"Elle peut être proposée dès la classe NYHA II si les critères électriques sont réunis","ok":true,"why":"Indication possible dès la classe NYHA II jusqu'à la classe IV."}],"explanation":"La resynchronisation par stimulateur biventriculaire (sondes en atrium droit, ventricule droit et paroi latérale du VG) est indiquée en cas d'IC symptomatique de classe NYHA II à IV, avec FEVG ≤ 35 % et QRS ≥ 130 ms ; elle est d'autant plus efficace qu'il existe un bloc de branche gauche, un QRS ≥ 150 ms et une cardiopathie non ischémique.","src":"p. 481"},{"id":"234-qcm-215","type":"QRM","rank":"A","objective":"234-obj-20","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant les indications du défibrillateur automatique implantable (DAI) dans l'IC à FE diminuée, quelles propositions sont exactes ?","options":[{"t":"Après un arrêt cardiaque par fibrillation ventriculaire récupéré","ok":true,"why":"Indication de prévention secondaire du DAI."},{"t":"Après une tachycardie ventriculaire symptomatique","ok":true,"why":"Indication de prévention secondaire du DAI."},{"t":"En prévention primaire chez un patient symptomatique avec FEVG < 35 %, à distance d'un infarctus revascularisé","ok":true,"why":"Indication de prévention primaire sur cardiopathie ischémique, au moins 6 semaines après le geste."},{"t":"Systématiquement chez tout patient en classe NYHA IV, quelle que soit la perspective de greffe","ok":false,"why":"Le stade NYHA IV ne relève pas du DAI, sauf projet de greffe ou d'assistance circulatoire, en raison du mauvais pronostic vital à court terme."},{"t":"En prévention primaire sur cardiopathie non ischémique, après au moins 3 mois de traitement médical bien conduit","ok":true,"why":"Délai requis avant l'implantation sur cardiopathie non ischémique."}],"explanation":"Le DAI est proposé en prévention secondaire (après FV récupérée ou TV symptomatique) et en prévention primaire chez le patient symptomatique avec FEVG < 35 %, à distance d'un infarctus revascularisé (≥ 6 semaines) ou après ≥ 3 mois de traitement optimal sur cardiopathie non ischémique. Il est réservé aux patients dont l'espérance de survie dépasse 1 an, ce qui exclut en règle le stade NYHA IV sauf projet de greffe ou d'assistance.","src":"p. 481-482","trap":"Un patient en NYHA IV n'est en règle pas candidat au DAI, sauf s'il est éligible à une greffe ou à une assistance circulatoire."},{"id":"234-qru-205","type":"QRU","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":1,"stem":"Quelles sont les deux principales complications décrites du défibrillateur automatique implantable ?","options":[{"t":"Infection de sonde et chocs inappropriés","ok":true,"why":"Les deux complications explicitement citées du DAI."},{"t":"Rupture de cordage et endocardite","ok":false,"why":"Complications d'une valvulopathie, non du DAI."},{"t":"Hyperkaliémie et insuffisance rénale","ok":false,"why":"Effets indésirables des antialdostérones, non du DAI."},{"t":"Acidocétose et infection génitale","ok":false,"why":"Effets indésirables des gliflozines, non du DAI."},{"t":"Gynécomastie et impuissance","ok":false,"why":"Effets indésirables de la spironolactone, non du DAI."}],"explanation":"Les complications du DAI décrites sont l'infection de sonde et la survenue de chocs inappropriés.","src":"p. 482"},{"id":"234-qcm-216","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":3,"stem":"Concernant le traitement percutané de la fuite mitrale secondaire chez l'insuffisant cardiaque, quelles propositions sont exactes ?","options":[{"t":"Une insuffisance mitrale secondaire importante persistant malgré un traitement optimal est associée à une surmortalité","ok":true,"why":"Constat justifiant l'intérêt du traitement percutané dans cette situation."},{"t":"La pose d'un clip percutané peut être discutée en réunion pluridisciplinaire si l'IC n'est pas trop avancée","ok":true,"why":"Modalité décisionnelle décrite pour cette procédure."},{"t":"Cette technique s'appuie sur des critères échocardiographiques précis","ok":true,"why":"Sélection des patients fondée sur l'échocardiographie."},{"t":"La correction percutanée des fuites tricuspides fonctionnelles est un traitement validé et systématiquement remboursé en France","ok":false,"why":"Cette technique est encore en cours d'évaluation et n'est pas remboursée en France."},{"t":"Cette technique remplace systématiquement la chirurgie valvulaire chez tout patient insuffisant cardiaque","ok":false,"why":"Il ne s'agit pas d'un traitement systématique ; l'indication repose sur une sélection précise des patients."}],"explanation":"Une insuffisance mitrale secondaire significative persistant malgré un traitement optimal expose à une surmortalité ; un clip percutané peut alors être discuté en réunion pluridisciplinaire, sur des critères échographiques précis, si l'IC n'est pas trop avancée. La correction percutanée des fuites tricuspides fonctionnelles reste en évaluation, non remboursée en France.","src":"p. 483"},{"id":"234-qcm-217","type":"QRM","rank":"B","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"stem":"Concernant les contre-indications à la transplantation cardiaque, quelles propositions sont exactes ?","options":[{"t":"Une hypertension artérielle pulmonaire fixée avec résistances supérieures à 5 unités Wood","ok":true,"why":"Contre-indication citée en raison du risque de défaillance ventriculaire droite du greffon."},{"t":"Une infection active","ok":true,"why":"Contre-indication classique avant tout geste lourd et immunosuppression."},{"t":"Une insuffisance rénale sévère","ok":true,"why":"Contre-indication citée du fait du pronostic et de la tolérance des traitements post-greffe."},{"t":"Un âge chronologique strictement supérieur à 50 ans","ok":false,"why":"Il n'existe pas de limite d'âge chronologique stricte ; l'appréciation se fait sur l'âge physiologique, la greffe restant rare au-delà de 65-70 ans."},{"t":"Une artériopathie périphérique diffuse","ok":true,"why":"Contre-indication citée parmi les atteintes vasculaires étendues."}],"explanation":"Les principales contre-indications à la transplantation cardiaque sont une pathologie limitant l'espérance de vie, une infection active, une insuffisance rénale sévère, une HTAP fixée (résistances > 5 unités Wood) et une artériopathie diffuse. Il n'existe pas de limite d'âge chronologique stricte, mais la greffe reste rare après 65-70 ans du fait de l'âge physiologique.","src":"p. 483"},{"id":"234-qroc-201","type":"QROC","rank":"B","objective":"234-obj-08","tags":["traitement"],"difficulty":1,"question":"Quel traitement spécifique est aujourd'hui disponible pour l'amylose cardiaque à transthyrétine ?","answer":"Tafamidis","accept":["tafamidis"],"keywords":["tafamidis"],"explanation":"Dans l'amylose cardiaque à transthyrétine, une forme particulière de cardiomyopathie restrictive, un traitement spécifique existe désormais : le tafamidis. D'autres molécules sont en cours de développement.","src":"p. 484"},{"id":"234-qroc-202","type":"QROC","rank":"B","objective":"234-obj-08","tags":["traitement"],"difficulty":2,"question":"Dans le traitement de l'IC à FE préservée, quelles classes médicamenteuses sont utilisées pour ralentir la fréquence cardiaque et allonger la diastole afin d'améliorer le remplissage ventriculaire ?","answer":"Bêtabloquant ou inhibiteur calcique bradycardisant","accept":["bêtabloquants et inhibiteurs calciques bradycardisants"],"keywords":["bêtabloquant","inhibiteur calcique"],"explanation":"Le premier axe du traitement de l'IC à FE préservée vise à éviter et traiter les arythmies et la tachycardie, en s'appuyant sur un bêtabloquant ou un inhibiteur calcique bradycardisant : en ralentissant la fréquence cardiaque, ils allongent la diastole et améliorent le remplissage du ventricule gauche.","src":"p. 483"},{"id":"234-qroc-203","type":"QROC","rank":"B","objective":"234-obj-08","tags":["traitement"],"difficulty":2,"question":"Quelle classe de diurétiques utiliser en traitement de fond de l'IC à FE préservée en présence de manifestations congestives ?","answer":"Diurétiques thiazidiques ou de l'anse","accept":["diurétiques thiazidiques ou diurétiques de l'anse"],"keywords":["thiazidique","diurétique","anse"],"explanation":"Dans l'IC à FE préservée, un traitement diurétique de fond, thiazidique ou par inhibiteur de l'anse de Henle, est utilisé en présence de signes congestifs, avec surveillance de la fonction rénale.","src":"p. 484"},{"id":"234-qroc-204","type":"QROC","rank":"B","objective":"234-obj-08","tags":["traitement"],"difficulty":2,"question":"Quel antialdostérone de nouvelle génération a montré un bénéfice sur la mortalité cardiovasculaire et les hospitalisations dans l'IC à FE préservée, mais n'est pas disponible en France ?","answer":"Finérénone","accept":["finérénone"],"keywords":["finérénone"],"explanation":"Une étude a montré l'intérêt d'un antialdostérone de nouvelle génération, la finérénone, pour réduire la mortalité cardiovasculaire et les hospitalisations pour IC à FE préservée ; cette molécule n'est cependant pas disponible en France.","src":"p. 484"},{"id":"234-qroc-205","type":"QROC","rank":"A","objective":"234-obj-19","tags":["traitement","suivi"],"difficulty":1,"question":"Quels trois paramètres simples sont transmis quasi quotidiennement dans les programmes de télésurveillance de l'insuffisance cardiaque ?","answer":"Pression artérielle, fréquence cardiaque et poids","accept":["PA, FC et poids"],"keywords":["pression artérielle","fréquence cardiaque","poids"],"explanation":"Les programmes de télésurveillance de l'IC, aujourd'hui remboursés, transmettent quasi quotidiennement la pression artérielle, la fréquence cardiaque et le poids du patient à une plateforme qui génère des alertes.","src":"p. 484"},{"id":"234-qroc-206","type":"QROC","rank":"A","objective":"234-obj-19","tags":["traitement","suivi"],"difficulty":1,"question":"Quel professionnel de santé contacte habituellement le patient lorsqu'une alerte est déclenchée par la plateforme de télésurveillance de l'IC ?","answer":"Un infirmier","accept":["infirmier","infirmière"],"keywords":["infirmier"],"explanation":"Lorsqu'une alerte est déclenchée par la plateforme, le patient est le plus souvent appelé par un infirmier, dans le but de dépister précocement une décompensation et d'éviter une hospitalisation.","src":"p. 484"},{"id":"234-qroc-207","type":"QROC","rank":"A","objective":"234-obj-18","tags":["traitement","urgence"],"difficulty":1,"question":"Quelle dose de furosémide intraveineux administrer au domicile d'un patient présentant un œdème aigu pulmonaire, avant son transfert ?","answer":"1 mg/kg, à répéter si nécessaire","accept":["1 mg par kg"],"keywords":["furosémide","1 mg/kg"],"explanation":"Au domicile, devant un OAP, le médecin injecte du furosémide en intraveineux à la dose de 1 mg/kg, à répéter si besoin, avant l'appel du Samu selon la gravité et l'hospitalisation.","src":"p. 485"},{"id":"234-qroc-208","type":"QROC","rank":"A","objective":"234-obj-18","tags":["traitement","urgence"],"difficulty":2,"question":"Au-delà de quel seuil de pression artérielle systolique les dérivés nitrés intraveineux sont-ils indiqués dans la prise en charge hospitalière d'un OAP ?","answer":"PAS > 110 mmHg","accept":["pression artérielle systolique supérieure à 110 mmHg"],"keywords":["110","PAS"],"explanation":"À l'hôpital, les dérivés nitrés intraveineux (trinitrine, environ 1 mg/h, adaptée à la pression artérielle) sont indiqués si la PAS est supérieure à 110 mmHg, seuil différent de celui retenu au domicile pour la voie sublinguale (PAS > 100 mmHg).","src":"p. 485"},{"id":"234-qroc-209","type":"QROC","rank":"A","objective":"234-obj-18","tags":["traitement","urgence"],"difficulty":2,"question":"Quels critères respiratoires définissent l'échec du traitement médicamenteux justifiant le recours à la CPAP au cours d'un OAP ?","answer":"Fréquence respiratoire > 25/min et SpO2 < 90 %","accept":["FR > 25/min et saturation < 90 %"],"keywords":["fréquence respiratoire","SpO2"],"explanation":"En cas de non-réponse aux traitements médicamenteux, définie par une fréquence respiratoire supérieure à 25/min et une SpO2 inférieure à 90 %, la ventilation par CPAP peut améliorer les symptômes et la saturation en oxygène.","src":"p. 485"},{"id":"234-qroc-210","type":"QROC","rank":"B","objective":"234-obj-23","tags":["traitement","urgence"],"difficulty":2,"question":"Chez un patient en choc cardiogénique déjà traité par bêtabloquant, quelle classe d'inotropes préférer à la dobutamine ?","answer":"Les inhibiteurs des phosphodiestérases (milrinone ou énoximone)","accept":["inhibiteurs des phosphodiestérases"],"keywords":["phosphodiestérase","milrinone","énoximone"],"explanation":"Chez un patient sous bêtabloquant, l'effet de la dobutamine peut être atténué : on lui préfère alors un inhibiteur des phosphodiestérases, milrinone ou énoximone, dont l'effet inotrope ne dépend pas des récepteurs bêta-adrénergiques.","src":"p. 486"},{"id":"234-qroc-211","type":"QROC","rank":"B","objective":"234-obj-23","tags":["traitement","urgence"],"difficulty":3,"question":"Quel est le mécanisme d'action du lévosimendan utilisé dans le choc cardiogénique ?","answer":"Sensibilisateur calcique des protéines contractiles, à la fois inotrope et vasodilatateur","accept":["sensibilisateur calcique inotrope et vasodilatateur"],"keywords":["sensibilisateur calcique","inotrope","vasodilatateur"],"explanation":"Le lévosimendan est un sensibilisateur des protéines contractiles au calcium, aux propriétés à la fois inotropes et vasodilatatrices ; il est parfois utilisé chez les patients difficiles à sevrer du traitement par inotropes classiques.","src":"p. 486"},{"id":"234-qroc-212","type":"QROC","rank":"A","objective":"234-obj-18","tags":["traitement","urgence"],"difficulty":2,"question":"Que recherche la lettre « M » de l'acronyme CHAMPIT devant une insuffisance cardiaque aiguë ?","answer":"Une cause mécanique compliquant un syndrome coronarien aigu (rupture, CIV, insuffisance mitrale aiguë)","accept":["cause mécanique d'un SCA"],"keywords":["mécanique","SCA"],"explanation":"Dans l'acronyme CHAMPIT, le « M » désigne une cause mécanique lors d'un syndrome coronarien aigu : rupture, communication interventriculaire ou insuffisance mitrale aiguë, à rechercher systématiquement devant une IC aiguë inexpliquée.","src":"p. 486"},{"id":"234-open-21","type":"OPEN","rank":"A","objective":"234-obj-18","tags":["traitement","urgence"],"difficulty":2,"prompt":"Décrivez la prise en charge hospitalière initiale d'un œdème aigu pulmonaire cardiogénique, du monitorage au traitement médicamenteux de première intention.","rubric":[{"point":"Installation en position assise avec voie veineuse (soluté glucosé) et monitorage (fréquence cardiaque, pression artérielle, oxymétrie, scope)","weight":2.0},{"point":"Bilan initial sans retarder le traitement (ECG, radiographie thoracique, biologie, ± échographie)","weight":1.0},{"point":"Oxygénothérapie adaptée à l'objectif SpO2 > 90 %, avec prudence chez le patient à risque d'hypercapnie","weight":1.0},{"point":"Furosémide intraveineux à 1 mg/kg, adapté ensuite à la diurèse","weight":2.0},{"point":"Dérivés nitrés intraveineux si la PAS est supérieure à 110 mmHg","weight":1.0},{"point":"Morphine intraveineuse réservée à l'anxiété importante non contrôlée ou à la douleur thoracique, non systématique","weight":1.0},{"point":"Recherche et traitement d'un facteur déclenchant (digoxine et anticoagulation efficace si FA rapide, nicardipine IV si poussée hypertensive)","weight":1.0},{"point":"Anticoagulation préventive systématique par HBPM","weight":1.0}],"model":"L'OAP cardiogénique est une urgence : le patient est installé en position assise, une voie veineuse est posée, avec monitorage continu (FC, PA, SpO2, scope) et un bilan rapide (ECG, radiographie, biologie) qui ne doit jamais retarder le traitement. L'oxygénothérapie vise une SpO2 > 90 %, avec prudence chez le patient à risque d'hypercapnie. Le traitement médicamenteux repose sur le furosémide IV (1 mg/kg, adapté à la diurèse) et, si la PAS dépasse 110 mmHg, des dérivés nitrés IV. La morphine IV n'est utilisée qu'en cas d'anxiété importante ou de douleur, jamais systématiquement. Il faut rechercher un facteur déclenchant à traiter spécifiquement (digoxine et anticoagulation efficace si FA rapide, nicardipine IV en cas de poussée hypertensive) et prescrire une anticoagulation préventive systématique par HBPM. Le bêtabloquant n'est jamais introduit à ce stade.","src":"p. 485"},{"id":"234-open-22","type":"OPEN","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":3,"prompt":"Quelles sont les indications du défibrillateur automatique implantable (DAI) en prévention secondaire et en prévention primaire dans l'insuffisance cardiaque à FE diminuée, et dans quelle situation ce dispositif n'est-il en règle pas proposé malgré une FEVG basse ?","rubric":[{"point":"Prévention secondaire : après un arrêt cardiaque par fibrillation ventriculaire récupéré ou une tachycardie ventriculaire symptomatique","weight":2.0},{"point":"Prévention primaire sur cardiopathie ischémique : patient symptomatique (NYHA II-III), FEVG < 35 %, à distance (≥ 6 semaines) d'une revascularisation ou d'un infarctus","weight":2.0},{"point":"Prévention primaire sur cardiopathie non ischémique : après au moins 3 mois de traitement médical bien conduit","weight":1.0},{"point":"Condition générale : espérance de survie supérieure à 1 an","weight":1.0},{"point":"Le stade NYHA IV ne relève en règle pas du DAI, sauf projet de greffe ou d'assistance circulatoire","weight":2.0},{"point":"Un dispositif combiné DAI-resynchronisation est possible lorsque les deux indications coexistent","weight":1.0}],"model":"Le DAI est indiqué en prévention secondaire après un arrêt cardiaque par FV récupéré ou une TV symptomatique. En prévention primaire, il concerne le patient symptomatique (NYHA II-III) avec une FEVG inférieure à 35 %, sur cardiopathie ischémique à distance d'une revascularisation ou d'un infarctus (au moins 6 semaines), ou sur cardiopathie non ischémique après au moins 3 mois de traitement médical optimal. Ce dispositif suppose une espérance de survie supérieure à 1 an : les patients en stade NYHA IV n'en relèvent donc en règle pas, sauf s'ils sont candidats à une greffe cardiaque ou à une assistance circulatoire. Lorsque les critères de resynchronisation et de DAI coexistent, un dispositif combiné (DAI-CRT) peut être choisi.","src":"p. 481-482"},{"id":"234-open-23","type":"OPEN","rank":"A","objective":"234-obj-20","tags":["traitement"],"difficulty":2,"prompt":"Détaillez les quatre classes médicamenteuses qui réduisent la mortalité dans l'insuffisance cardiaque à FE diminuée, en précisant pour chacune une règle essentielle de prescription ou une précaution.","rubric":[{"point":"Bloqueurs du système rénine-angiotensine (IEC, ou ARA2/sacubitril-valsartan en cas d'intolérance) : surveillance de la kaliémie et de la fonction rénale","weight":2.0},{"point":"Bêtabloquants (carvédilol, métoprolol, bisoprolol, nébivolol) : instauration à très faible dose chez un patient stabilisé, jamais en pleine poussée aiguë","weight":2.0},{"point":"Antialdostérones (spironolactone, éplérénone) : indiqués dès la classe NYHA II, risque d'hyperkaliémie surtout associés à un IEC","weight":2.0},{"point":"Gliflozines (dapagliflozine, empagliflozine) : efficaces quel que soit le statut diabétique, peu hypotensives","weight":2.0},{"point":"Les diurétiques de l'anse restent un traitement symptomatique associé de la rétention hydrosodée, sans bénéfice démontré sur la mortalité","weight":1.0}],"model":"Quatre classes réduisent la mortalité et les hospitalisations dans l'IC à FE diminuée. Les bloqueurs du système rénine-angiotensine (IEC, ou l'association sacubitril-valsartan/ARA2 en cas d'intolérance) nécessitent une surveillance de la kaliémie et de la créatininémie. Les bêtabloquants (carvédilol, métoprolol, bisoprolol, nébivolol) ne doivent être introduits qu'à très faible dose, chez un patient stabilisé, jamais en pleine poussée aiguë. Les antialdostérones (spironolactone, éplérénone) sont indiqués dès la classe NYHA II mais exposent à l'hyperkaliémie, surtout associés à un IEC. Les gliflozines (dapagliflozine, empagliflozine) sont efficaces quel que soit le statut diabétique et peu hypotensives. À ces quatre classes s'ajoutent, à visée purement symptomatique, les diurétiques de l'anse, qui traitent la congestion sans bénéfice démontré sur la mortalité.","src":"p. 479-480"},{"id":"234-open-24","type":"OPEN","rank":"A","objective":"234-obj-23","tags":["traitement","urgence"],"difficulty":3,"prompt":"Un patient connu insuffisant cardiaque chronique à FE diminuée est admis pour un choc cardiogénique. Décrivez les critères diagnostiques, la prise en charge thérapeutique initiale et la stratégie en cas d'échec du traitement médical.","rubric":[{"point":"Critères diagnostiques : PAS < 90 mmHg, signes d'hypoperfusion périphérique (marbrures, extrémités froides), oligurie, altération de la conscience, bas débit confirmé à l'échographie","weight":2.0},{"point":"Traitement inotrope : dobutamine IV, ou inhibiteur des phosphodiestérases (milrinone/énoximone) si le patient est sous bêtabloquant","weight":2.0},{"point":"Surveillance rapprochée : sondage urinaire systématique, monitorage invasif de la pression artérielle par cathéter radial","weight":1.0},{"point":"Lévosimendan possible pour aider au sevrage du traitement inotrope","weight":1.0},{"point":"Recherche systématique d'une cause curable selon l'acronyme CHAMPIT","weight":1.0},{"point":"En l'absence de réponse : discussion d'une assistance circulatoire (ECMO ou assistance prolongée), voire d'une greffe cardiaque en urgence","weight":2.0}],"model":"Le choc cardiogénique associe une PAS inférieure à 90 mmHg, des signes d'hypoperfusion périphérique (marbrures, extrémités froides), une oligurie, une altération de la conscience et un bas débit confirmé à l'échocardiographie. Le traitement initial repose sur les inotropes : dobutamine intraveineuse, ou un inhibiteur des phosphodiestérases (milrinone, énoximone) si le patient est déjà sous bêtabloquant, avec sondage urinaire systématique et monitorage invasif de la pression artérielle par cathéter radial. Le lévosimendan, sensibilisateur calcique inotrope et vasodilatateur, peut aider au sevrage des inotropes. Il faut systématiquement rechercher une cause curable résumée par l'acronyme CHAMPIT (coronaire, hypertensive, arythmie, mécanique, pulmonaire, infection, tamponnade). En l'absence de réponse au traitement médical, une assistance circulatoire (ECMO de courte durée ou assistance prolongée) voire une greffe cardiaque en urgence doivent être discutées.","src":"p. 486"}],"edn":[{"id":"234-kfp-01","type":"KFP","rank":"A","objective":"234-obj-09","difficulty":2,"scenario":"Mme V., 79 ans, hypertendue depuis 20 ans, consulte pour un essoufflement progressif depuis 3 mois, désormais présent au moindre effort, y compris pour s'habiller ou se laver. Elle rapporte des œdèmes des chevilles le soir et un réveil nocturne par une sensation d'étouffement l'obligeant à s'asseoir. L'examen retrouve une turgescence jugulaire, des râles crépitants bilatéraux aux bases et une hépatomégalie ferme et douloureuse. La pression artérielle est à 150/90 mmHg.","questions":[{"stem":"Quel stade de la classification NYHA correspond à la gêne fonctionnelle décrite chez cette patiente ?","max":1,"options":["Stade I","Stade II","Stade III","Stade IV","Stade non classable","Stade 0","Stade V","Indéterminé sans épreuve d'effort"],"correct":[3],"explanation":"Une dyspnée présente pour des efforts minimes de la vie courante, comme s'habiller ou se laver, correspond au stade IV de la classification NYHA."},{"stem":"Parmi les éléments cliniques rapportés, lesquels sont des signes physiques spécifiques d'insuffisance cardiaque droite ?","max":2,"options":["Turgescence jugulaire","Hépatomégalie ferme et douloureuse","Râles crépitants bilatéraux","Œdèmes des chevilles vespéraux","Réveil nocturne par étouffement","Pression artérielle à 150/90 mmHg","Essoufflement progressif depuis 3 mois","Âge de la patiente"],"correct":[0,1],"explanation":"La turgescence jugulaire et l'hépatomégalie ferme et douloureuse sont les signes physiques les plus spécifiques d'une insuffisance cardiaque droite, traduisant la congestion veineuse systémique."},{"stem":"Quel symptôme rapporté par cette patiente est le plus spécifique d'une origine cardiaque de sa dyspnée ?","max":1,"options":["Essoufflement à l'effort","Réveil nocturne par une sensation d'étouffement","Œdèmes des chevilles vespéraux","Hypertension artérielle connue","Fatigue générale","Toux sèche occasionnelle","Palpitations occasionnelles","Prise de poids modérée"],"correct":[1],"explanation":"La dyspnée paroxystique nocturne, qui réveille le patient et l'oblige à se lever pour reprendre son souffle, est décrite comme très spécifique de l'insuffisance cardiaque, contrairement à la simple dyspnée d'effort."}],"src":"p. 461-463"},{"id":"234-kfp-02","type":"KFP","rank":"A","objective":"234-obj-18","difficulty":2,"scenario":"M. T., 80 ans, appelle le Samu pour une détresse respiratoire brutale avec orthopnée forcée, sueurs profuses et toux ramenant une expectoration mousseuse rosée. À l'arrivée, la pression artérielle est à 175/95 mmHg, la fréquence respiratoire à 32/min et la saturation à 84 % en air ambiant. L'auscultation retrouve des râles crépitants remontant jusqu'aux sommets.","questions":[{"stem":"Quelles mesures thérapeutiques immédiates sont indiquées chez ce patient en OAP, compte tenu d'une pression artérielle conservée ?","max":3,"options":["Position demi-assise ou assise","Oxygénothérapie pour SpO2 > 90 %","Furosémide intraveineux (1 mg/kg)","Introduction immédiate d'un bêtabloquant","Remplissage vasculaire abondant","Décubitus strict","Arrêt de toute oxygénothérapie","Morphine IV systématique en première intention"],"correct":[0,1,2],"explanation":"La prise en charge initiale de l'OAP associe position assise, oxygénothérapie adaptée à la saturation, et furosémide IV à 1 mg/kg ; le bêtabloquant et le remplissage vasculaire sont à proscrire à ce stade."},{"stem":"Quelle mesure est formellement contre-indiquée à la phase aiguë de cet épisode ?","max":1,"options":["Introduction d'un bêtabloquant en pleine poussée aiguë","Furosémide intraveineux","Position assise","Oxygénothérapie adaptée","Recherche d'un facteur déclenchant","Voie veineuse périphérique"],"correct":[0],"explanation":"Le chapitre précise que le bêtabloquant n'est jamais débuté en pleine poussée d'insuffisance cardiaque aiguë."},{"stem":"Quel facteur déclenchant doit être recherché en priorité chez ce patient présentant une poussée hypertensive associée ?","max":1,"options":["Poussée hypertensive ou rupture de traitement/régime sans sel","Carence en vitamine D","Consommation excessive de thé","Excès de sommeil","Amélioration récente de la fonction rénale","Diminution récente du tabagisme","Perte de poids récente","Absence de toute comorbidité connue"],"correct":[0],"explanation":"La poussée hypertensive et la rupture de traitement ou de régime sans sel figurent parmi les facteurs déclenchants classiques d'un OAP à rechercher systématiquement."}],"src":"p. 472-473, 485-486"},{"id":"234-kfp-03","type":"KFP","rank":"A","objective":"234-obj-20","difficulty":2,"scenario":"M. G., 65 ans, suivi pour une insuffisance cardiaque à FEVG à 30 %, stabilisée depuis 2 mois sans signe congestif, vient en consultation pour optimiser son traitement de fond. Il est actuellement traité par furosémide seul. La pression artérielle est à 118/70 mmHg, la fréquence cardiaque à 78/min, la créatininémie et la kaliémie sont normales.","questions":[{"stem":"Parmi les classes suivantes, lesquelles doivent être introduites progressivement chez ce patient stabilisé, en dehors de toute poussée ?","max":4,"options":["Un IEC (ou ARA2/sacubitril-valsartan)","Un bêtabloquant","Un antialdostérone","Une gliflozine","Le vérapamil","La flécaïnide","Un anti-inflammatoire non stéroïdien","La digoxine en première intention"],"correct":[0,1,2,3],"explanation":"Les 4 classes qui réduisent mortalité et hospitalisations dans l'IC à FE diminuée sont les bloqueurs du SRA, les bêtabloquants, les antialdostérones et les gliflozines, à introduire chez un patient stabilisé."},{"stem":"Quelle association médicamenteuse expose particulièrement à un risque d'hyperkaliémie et doit être surveillée de près ?","max":1,"options":["IEC et antialdostérone","Bêtabloquant et gliflozine","IEC et gliflozine","Antialdostérone et bêtabloquant","Gliflozine seule","IEC et bêtabloquant"],"correct":[0],"explanation":"L'association d'un IEC et d'un antialdostérone majore le risque d'hyperkaliémie et d'insuffisance rénale, ce qui impose une surveillance biologique rapprochée."},{"stem":"Quel paramètre biologique doit être surveillé une semaine après l'introduction ou l'augmentation de dose d'un IEC ?","max":1,"options":["Créatininémie et kaliémie","Glycémie à jeun","TSH","Bilan hépatique","Ferritinémie","Numération plaquettaire"],"correct":[0],"explanation":"La pression artérielle, la créatininémie et la kaliémie doivent être surveillées une semaine après l'introduction d'un IEC et après chaque palier de dose."}],"src":"p. 477-480"},{"id":"234-tcs-01","type":"TCS","rank":"A","objective":"234-obj-09","difficulty":2,"vignette":"Un homme de 70 ans consulte pour une dyspnée d'aggravation progressive depuis un mois, sans douleur thoracique. Il n'a pas d'antécédent cardiovasculaire connu.","items":[{"hypothesis":"Si vous pensiez à une insuffisance cardiaque,","newInfo":"et que vous constatez une orthopnée et une turgescence jugulaire à l'examen,","panel":[0,0,3,5,7],"explanation":"L'orthopnée et la turgescence jugulaire sont des signes évocateurs et assez spécifiques d'insuffisance cardiaque, renforçant fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à une insuffisance cardiaque,","newInfo":"et que le NT-proBNP revient à 40 pg/mL,","panel":[7,5,3,0,0],"explanation":"Un NT-proBNP aussi bas rend le diagnostic d'insuffisance cardiaque très improbable, compte tenu de son excellente valeur prédictive négative."},{"hypothesis":"Si vous pensiez à une exacerbation de BPCO,","newInfo":"et que le patient n'a aucun antécédent respiratoire ni tabagique,","panel":[5,6,3,1,0],"explanation":"L'absence d'antécédent respiratoire ou tabagique rend une exacerbation de BPCO peu probable, ce diagnostic reposant habituellement sur des antécédents connus."},{"hypothesis":"Si vous pensiez à une embolie pulmonaire,","newInfo":"et que l'auscultation pulmonaire est strictement normale, sans contexte à risque particulier,","panel":[2,3,7,2,1],"explanation":"Une auscultation normale est compatible avec une embolie pulmonaire mais n'apporte pas d'argument fort dans un sens ou dans l'autre en l'absence de facteur de risque."}],"src":"p. 461-465, 472"},{"id":"234-tcs-02","type":"TCS","rank":"A","objective":"234-obj-18","difficulty":2,"vignette":"Une femme de 68 ans est admise pour une détresse respiratoire aiguë avec orthopnée et sueurs profuses. Sa pression artérielle est à 165/90 mmHg.","items":[{"hypothesis":"Si vous pensiez à un OAP cardiogénique,","newInfo":"et que l'auscultation retrouve des râles crépitants remontant jusqu'aux sommets,","panel":[0,0,2,4,9],"explanation":"Des râles crépitants remontant haut dans les champs pulmonaires traduisent la sévérité de l'inondation alvéolaire, renforçant fortement l'hypothèse d'OAP."},{"hypothesis":"Si vous pensiez à un OAP cardiogénique,","newInfo":"et que la saturation remonte à 96 % avec une nette amélioration après furosémide IV et dérivés nitrés,","panel":[0,1,2,4,8],"explanation":"L'amélioration rapide sous traitement spécifique de l'OAP (diurétique, dérivés nitrés) est un argument supplémentaire en faveur de ce diagnostic."},{"hypothesis":"Si vous envisagiez d'introduire un bêtabloquant en urgence pour ralentir la fréquence cardiaque,","newInfo":"sachant que la patiente est en pleine poussée aiguë d'OAP,","panel":[9,4,2,0,0],"explanation":"Le bêtabloquant n'est jamais introduit en pleine poussée aiguë d'insuffisance cardiaque : cette hypothèse est fortement défavorisée par cette information."},{"hypothesis":"Si vous pensiez à une origine hypertensive à ce tableau,","newInfo":"et que la PAS reste élevée à 165 mmHg malgré le traitement initial,","panel":[1,2,4,6,2],"explanation":"Une poussée hypertensive persistante peut accompagner et entretenir un OAP, ce qui renforce modérément cette hypothèse."}],"src":"p. 472, 485"},{"id":"234-tcs-03","type":"TCS","rank":"A","objective":"234-obj-22","difficulty":3,"vignette":"Un patient de 60 ans, hospitalisé pour un infarctus antérieur étendu, présente une hypotension à 78/50 mmHg depuis 40 minutes malgré un remplissage prudent.","items":[{"hypothesis":"Si vous pensiez à un choc cardiogénique,","newInfo":"et que les extrémités sont froides, marbrées, avec une diurèse à 15 mL/h,","panel":[0,0,1,4,10],"explanation":"Les signes d'hypoperfusion périphérique et l'oligurie sont des critères diagnostiques majeurs du choc cardiogénique, renforçant fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à un choc cardiogénique,","newInfo":"et que l'échocardiographie retrouve une fraction d'éjection très abaissée avec un bas débit mesuré,","panel":[0,0,2,4,9],"explanation":"La preuve échographique d'un bas débit cardiaque est l'un des critères diagnostiques du choc cardiogénique cités par le chapitre."},{"hypothesis":"Si vous pensiez à une hypovolémie simple comme cause de l'hypotension,","newInfo":"sachant que le patient présente une turgescence jugulaire et des râles crépitants bilatéraux,","panel":[9,4,2,0,0],"explanation":"La présence de signes congestifs (turgescence jugulaire, crépitants) est incompatible avec une simple hypovolémie et oriente au contraire vers une origine cardiogénique."},{"hypothesis":"Si vous envisagiez une assistance circulatoire,","newInfo":"et que l'état hémodynamique ne s'améliore pas malgré des inotropes à dose optimale,","panel":[0,1,2,4,8],"explanation":"En l'absence de réponse au traitement médical optimal, une assistance circulatoire (ECMO ou assistance prolongée) doit être discutée selon le chapitre."}],"src":"p. 473, 486"},{"id":"234-tcs-04","type":"TCS","rank":"B","objective":"234-obj-16","difficulty":2,"vignette":"Une femme de 35 ans, sans antécédent particulier, présente une insuffisance cardiaque à FEVG à 25 % découverte au décours immédiat d'un accouchement.","items":[{"hypothesis":"Si vous pensiez à une cardiomyopathie du péripartum,","newInfo":"et que l'échocardiographie ne retrouve ni valvulopathie ni cardiopathie ischémique,","panel":[0,0,2,4,9],"explanation":"L'absence de cause valvulaire ou ischémique identifiée, dans ce contexte temporel très évocateur, renforce fortement l'hypothèse de cardiomyopathie du péripartum."},{"hypothesis":"Si vous pensiez à une cardiomyopathie dilatée d'origine génétique familiale,","newInfo":"et qu'aucun apparenté du premier degré n'est atteint de cardiopathie,","panel":[3,6,4,2,0],"explanation":"L'absence de cas familial rend une origine génétique familiale moins probable, sans toutefois l'exclure formellement compte tenu d'une pénétrance variable."},{"hypothesis":"Si vous pensiez à une origine toxique (alcool, cocaïne),","newInfo":"et que la patiente ne rapporte aucune consommation de ce type,","panel":[8,5,2,0,0],"explanation":"L'absence de consommation toxique rapportée défavorise nettement cette hypothèse étiologique."}],"src":"p. 469-470"}],"trees":[{"id":"234-tree-01","title":"Diagnostiquer une IC hors urgence","rank":"A","objective":"234-obj-09","intro":"Démarche du livre (fig. 18.5) devant une suspicion d'insuffisance cardiaque chronique : terrain, symptômes ou signes, puis peptides natriurétiques, puis échocardiographie qui confirme ou infirme et classe selon la FEVG.","root":"n1","nodes":{"n1":{"type":"question","text":"Patient vu en consultation : terrain à risque, symptômes (dyspnée d'effort, orthopnée, fatigue, prise de poids) ou signes d'IC, ou ECG anormal ?","options":[{"label":"Oui, suspicion d'IC","to":"n2"},{"label":"Non","to":"n9"}]},"n2":{"type":"action","text":"Doser le BNP ou le NT-proBNP (1re intention, bonne valeur prédictive négative).","note":"Facteurs qui élèvent le taux : âge, insuffisance rénale, FA. L'obésité l'abaisse.","to":"n3"},"n3":{"type":"question","text":"BNP > 35 pg/mL ou NT-proBNP > 125 pg/mL, ou IC fortement suspectée, ou dosage indisponible ?","options":[{"label":"Oui","to":"n4"},{"label":"Non : BNP < 35 et NT-proBNP < 125","to":"n8"}]},"n4":{"type":"action","text":"Réaliser une échocardiographie transthoracique couplée au doppler : examen clé qui confirme ou infirme l'IC.","to":"n5"},"n5":{"type":"question","text":"Quelle est la FEVG mesurée à l'ETT ?","options":[{"label":"≤ 40 %","to":"n6"},{"label":"41–49 %","to":"n7"},{"label":"≥ 50 % avec pressions de remplissage élevées, HVG ou OG dilatée","to":"n10"},{"label":"Cœur normal, sans anomalie","to":"n8"}]},"n6":{"type":"end","tone":"warn","text":"IC à FE diminuée. Compléter le bilan étiologique (ischémie à éliminer) et débuter les 4 classes cardioprotectrices + diurétiques si congestion."},"n7":{"type":"end","tone":"warn","text":"IC à FE légèrement diminuée : forme proche de l'IC à FE diminuée ; mêmes traitements recommandés avec un niveau de preuve moindre (IIb, C)."},"n8":{"type":"end","tone":"ok","text":"IC peu probable. Rechercher une autre cause de dyspnée."},"n9":{"type":"end","tone":"info","text":"Pas d'argument pour une IC : poursuivre la prise en charge des facteurs de risque (HTA, diabète, toxiques)."},"n10":{"type":"end","tone":"warn","text":"IC à FE préservée (FEVG > 50 %) : symptômes + peptides élevés + HVG (masse > 115 g/m² homme, > 95 g/m² femme) ou OG > 34 mL/m² ou pressions de remplissage élevées."}},"src":"p. 465-467, 473-474"},{"id":"234-tree-02","title":"Dyspnée aiguë : OAP cardiogénique ou autre ?","rank":"A","objective":"234-obj-07","intro":"Aux urgences, le livre demande de reconnaître l'OAP sur la clinique, d'utiliser les peptides natriurétiques avec leurs seuils « aigus » et d'argumenter les diagnostics différentiels : pneumopathie, embolie pulmonaire, exacerbation de BPCO, asthme.","root":"n1","nodes":{"n1":{"type":"question","text":"Détresse respiratoire aiguë : orthopnée, sueurs, grésillement laryngé, crépitants bilatéraux en « marée montante », galop, tachycardie ?","options":[{"label":"Oui, tableau évocateur d'OAP","to":"n2"},{"label":"Tableau atypique","to":"n5"}]},"n2":{"type":"action","text":"Sans retarder le traitement : ECG, GDS artériels (hypoxie/hypocapnie), radio thoracique, BNP ou NT-proBNP, troponine, échocardiographie.","to":"n3"},"n3":{"type":"question","text":"Valeur des peptides natriurétiques ?","options":[{"label":"BNP < 100 ou NT-proBNP < 300 pg/mL","to":"n4"},{"label":"BNP > 300 ou NT-proBNP > 450 (< 50 ans), > 900 (50–75 ans), > 1 800 (> 75 ans)","to":"n10"},{"label":"Zone intermédiaire","to":"n11"}]},"n4":{"type":"end","tone":"info","text":"IC très improbable (bonne VPN) : remettre en cause l'origine cardiogénique et chercher un diagnostic différentiel."},"n5":{"type":"question","text":"Quels arguments cliniques dominent ?","options":[{"label":"Fièvre, foyer de crépitants localisé, opacité systématisée","to":"n6"},{"label":"Terrain thromboembolique, auscultation pulmonaire normale","to":"n7"},{"label":"BPCO connue, ronchi, sibilants, expectoration","to":"n8"},{"label":"Asthmatique, dyspnée expiratoire, sibilants","to":"n9"}]},"n6":{"type":"end","tone":"warn","text":"Pneumopathie aiguë : le BNP/NT-proBNP est normal ou peu augmenté."},"n7":{"type":"end","tone":"danger","text":"Embolie pulmonaire : penser au cœur pulmonaire aigu (IC droite aiguë)."},"n8":{"type":"end","tone":"warn","text":"Exacerbation de BPCO. Attention : l'asthme cardiaque (bradypnée expiratoire sifflante) peut mimer une cause pulmonaire."},"n9":{"type":"end","tone":"warn","text":"Crise d'asthme. Vérifier l'absence de cardiopathie sous-jacente si doute (peptides, ETT)."},"n10":{"type":"end","tone":"danger","text":"OAP cardiogénique très probable : traitement immédiat, ETT pour la cardiopathie sous-jacente, recherche des facteurs déclenchants (CHAMPIT)."},"n11":{"type":"end","tone":"info","text":"Diagnostic incertain : interpréter impérativement avec la clinique (âge, insuffisance rénale et FA élèvent le taux ; l'obésité l'abaisse) et l'ETT."}},"src":"p. 465, 472-473"},{"id":"234-tree-03","title":"Traitement d'urgence de l'OAP","rank":"A","objective":"234-obj-18","intro":"L'OAP est une des grandes urgences cardiovasculaires. Le livre décrit une prise en charge au domicile puis à l'hôpital, avec des seuils tensionnels précis pour les dérivés nitrés et une escalade ventilatoire en cas d'échec.","root":"n1","nodes":{"n1":{"type":"question","text":"Où se trouve le patient ?","options":[{"label":"Au domicile","to":"n2"},{"label":"À l'hôpital ou à l'arrivée du Samu","to":"n4"}]},"n2":{"type":"action","text":"Position assise ou demi-assise, furosémide IV 1 mg/kg (à répéter si besoin), appel du Samu selon la gravité, hospitalisation.","to":"n3"},"n3":{"type":"question","text":"PAS > 100 mmHg ?","options":[{"label":"Oui","to":"n13"},{"label":"Non","to":"n14"}]},"n4":{"type":"action","text":"Position assise, VVP avec G5 %, monitorage (FC, PA, SaO2, scope), ECG, cliché thoracique, bilan sanguin et urinaire, échographie pulmonaire éventuelle.","to":"n5"},"n5":{"type":"question","text":"SaO2 < 90 % ?","options":[{"label":"Oui","to":"n6"},{"label":"Non","to":"n7"}]},"n6":{"type":"action","text":"Oxygénothérapie (sonde nasale ou masque), objectif SaO2 > 90 %, prudence chez les patients à risque d'hypercapnie.","to":"n7"},"n7":{"type":"action","text":"Furosémide IV 1 mg/kg, adapté ensuite à la diurèse. HBPM préventive systématique. Morphine IV seulement si anxiété majeure non contrôlée ou douleur thoracique.","to":"n8"},"n8":{"type":"question","text":"PAS > 110 mmHg ?","options":[{"label":"Oui","to":"n9"},{"label":"Non","to":"n10"}]},"n9":{"type":"action","text":"Trinitrine IV 1 mg/h, adaptée à la pression artérielle.","to":"n10"},"n10":{"type":"question","text":"Facteur déclenchant à traiter ?","options":[{"label":"FA rapide","to":"n15"},{"label":"Poussée hypertensive","to":"n16"},{"label":"Aucun identifié","to":"n11"}]},"n11":{"type":"question","text":"Réponse au traitement médicamenteux ? (échec = FR > 25/min ou SaO2 < 90 %)","options":[{"label":"Amélioration","to":"n17"},{"label":"Échec","to":"n12"}]},"n12":{"type":"question","text":"Après CPAP : persistance de signes d'insuffisance respiratoire aiguë et épuisement respiratoire ?","options":[{"label":"Non, amélioration sous CPAP","to":"n17"},{"label":"Oui","to":"n18"}]},"n13":{"type":"action","text":"Dérivés nitrés en sublingual.","to":"n14"},"n14":{"type":"end","tone":"danger","text":"Transfert hospitalier (soins intensifs) pour poursuite du traitement IV."},"n15":{"type":"action","text":"Digoxine IV et anticoagulation efficace.","to":"n11"},"n16":{"type":"action","text":"Nicardipine IV en perfusion (1 à 5 mg/h).","to":"n11"},"n17":{"type":"end","tone":"ok","text":"Poursuite en soins intensifs. Pas de bêtabloquant pendant la poussée ; IEC/ARA2/sacubitril-valsartan seulement secondairement, une fois l'épisode contrôlé."},"n18":{"type":"end","tone":"danger","text":"Intubation trachéale et ventilation invasive."}},"src":"p. 485"},{"id":"234-tree-04","title":"Reconnaître et traiter un choc cardiogénique","rank":"A","objective":"234-obj-22","intro":"Le choc cardiogénique est le tableau ultime de la défaillance cardiaque aiguë. Le livre en donne les critères cliniques et les principes du traitement inotrope, puis l'escalade vers l'assistance circulatoire.","root":"n1","nodes":{"n1":{"type":"question","text":"PAS < 90 mmHg (ou chute de PAS > 30 mmHg par rapport à la base) pendant au moins 30 minutes ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"n9"}]},"n2":{"type":"question","text":"Signes d'hypoperfusion périphérique : extrémités froides, cyanosées, marbrures, oligurie < 20 mL/h, sueurs, confusion ou agitation, PA pincée ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n9"}]},"n3":{"type":"action","text":"Choc cardiogénique : confirmer la baisse du débit à l'échocardiographie, sonde urinaire systématique, monitorage invasif de la PA (cathéter radial).","to":"n4"},"n4":{"type":"question","text":"Le patient est-il sous bêtabloquant ?","options":[{"label":"Non","to":"n5"},{"label":"Oui","to":"n6"}]},"n5":{"type":"action","text":"Perfusion de dobutamine IV.","to":"n7"},"n6":{"type":"action","text":"Inhibiteur des phosphodiestérases (milrinone ou énoximone) ; arrêt du bêtabloquant (le choc est une des rares raisons de l'arrêter).","to":"n7"},"n7":{"type":"action","text":"Rechercher une cause justifiant un traitement spécifique : CHAMPIT (SCA, urgence hypertensive, arythmie, cause mécanique, EP, infection, tamponnade).","to":"n8"},"n8":{"type":"question","text":"Réponse aux inotropes ?","options":[{"label":"Amélioration","to":"n10"},{"label":"Dépendance aux inotropes, sevrage impossible","to":"n11"},{"label":"Absence de réponse","to":"n12"}]},"n9":{"type":"end","tone":"info","text":"Pas de choc : prise en charge de l'OAP ou de la poussée d'IC selon le tableau (diurétiques IV, dérivés nitrés si PAS le permet)."},"n10":{"type":"end","tone":"ok","text":"Sevrage progressif des inotropes, puis reprise et titration du traitement de fond de l'IC une fois le patient stabilisé."},"n11":{"type":"end","tone":"warn","text":"Lévosimendan (sensibilisateur au calcium, inotrope et vasodilatateur) parfois utilisé ; discuter l'assistance."},"n12":{"type":"end","tone":"danger","text":"Discuter une assistance circulatoire (ECMO de courte durée, assistance uni/biventriculaire), un cœur artificiel ou une greffe en urgence."}},"src":"p. 473, 486"},{"id":"234-tree-05","title":"Traitement de l'IC à FEVG diminuée","rank":"A","objective":"234-obj-20","intro":"Algorithme du livre (fig. 18.7, ESC 2021) : quatre classes de classe I plus diurétiques de l'anse si congestion, puis discussion du traitement « électrique » selon la FEVG, le rythme et la largeur du QRS, puis traitements de 2e intention.","root":"n1","nodes":{"n1":{"type":"action","text":"Prescrire les 4 classes de classe I : IEC (ou sacubitril/valsartan), bêtabloquant, antialdostérone, dapagliflozine ou empagliflozine.","note":"IEC : tous les patients à FE diminuée quelle que soit la classe NYHA. Antialdostérone : NYHA II à IV. ARA2 seulement si intolérance aux IEC.","to":"n2"},"n2":{"type":"question","text":"Signes de rétention hydrosodée ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"action","text":"Ajouter un diurétique de l'anse (furosémide) à la dose minimale contrôlant les œdèmes ; thiazidique en association seulement si résistance dans les formes graves.","to":"n4"},"n4":{"type":"question","text":"Après optimisation : patient symptomatique (NYHA II–IV) avec FEVG ≤ 35 % ?","options":[{"label":"Oui","to":"n5"},{"label":"Non, FEVG > 35 %","to":"n11"}]},"n5":{"type":"question","text":"Rythme sinusal avec QRS ≥ 130 ms ?","options":[{"label":"Oui, QRS 130–149 ms","to":"n6"},{"label":"Oui, QRS ≥ 150 ms","to":"n7"},{"label":"Non, QRS < 130 ms","to":"n8"}]},"n6":{"type":"end","tone":"info","text":"Resynchronisation (CRT-P ou CRT-D) de classe IIa ; efficacité meilleure si BBG et cardiopathie non ischémique."},"n7":{"type":"end","tone":"ok","text":"Resynchronisation de classe I (CRT-D si indication de DAI associée : dispositif combiné)."},"n8":{"type":"question","text":"Cardiopathie ischémique ?","options":[{"label":"Oui, ≥ 6 semaines après IDM ou revascularisation","to":"n9"},{"label":"Non ischémique, après ≥ 3 mois de traitement médical bien conduit","to":"n10"}]},"n9":{"type":"end","tone":"ok","text":"DAI en prévention primaire (classe I) si survie attendue > 1 an (pas de DAI en NYHA IV sauf projet de greffe ou d'assistance)."},"n10":{"type":"end","tone":"info","text":"DAI en prévention primaire (classe IIa) si survie attendue > 1 an."},"n11":{"type":"question","text":"Symptômes persistants malgré le traitement de classe I ?","options":[{"label":"Oui","to":"n12"},{"label":"Non","to":"n13"}]},"n12":{"type":"end","tone":"warn","text":"Traitements de classe II : ivabradine (sinusal, FC > 70–75/min), digoxine, dérivés nitrés ; clip mitral si IM secondaire importante ; greffe ou assistance si IC terminale."},"n13":{"type":"end","tone":"ok","text":"Poursuivre le traitement optimisé, éducation, réadaptation et suivi régulier cardiologue–généraliste."}},"src":"p. 477-483"},{"id":"234-tree-06","title":"Bilan étiologique d'une IC à FEVG basse","rank":"B","objective":"234-obj-10","intro":"Devant une IC à FEVG abaissée, le livre impose d'éliminer une origine ischémique. Le choix entre coroscanner et coronarographie dépend de la probabilité de maladie coronarienne, de l'angor et de l'éligibilité à une revascularisation.","root":"n1","nodes":{"n1":{"type":"action","text":"ETT : cinétique segmentaire, valves, hypertrophie ; ECG (ondes Q, BBG) ; bilan biologique standard (iono, créatinine, glycémie/HbA1c, lipides, hépatique, TSH, NFS, ferritine, CST).","to":"n2"},"n2":{"type":"question","text":"L'ETT révèle-t-elle une cause curable évidente ?","options":[{"label":"Valvulopathie organique significative","to":"n3"},{"label":"Hypertrophie asymétrique du SIV","to":"n4"},{"label":"Non : VG dilaté hypokinétique ou anomalie segmentaire","to":"n5"}]},"n3":{"type":"end","tone":"warn","text":"Valvulopathie gauche : discuter une correction radicale (remplacement, plastie, traitement percutané)."},"n4":{"type":"end","tone":"info","text":"Cardiomyopathie hypertrophique (maladie familiale monogénique, sarcomère) ; penser à l'amylose si épaississement diffus (scintigraphie au technétium)."},"n5":{"type":"question","text":"Angor, probabilité intermédiaire à haute de maladie coronarienne, ou ischémie documentée chez un patient éligible à une revascularisation ?","options":[{"label":"Oui","to":"n6"},{"label":"Non : probabilité faible ou intermédiaire","to":"n7"}]},"n6":{"type":"action","text":"Coronarographie.","to":"n8"},"n7":{"type":"action","text":"Coroscanner (examen à privilégier pour éliminer l'étiologie coronarienne, ou si les tests d'ischémie ne tranchent pas).","to":"n8"},"n8":{"type":"question","text":"Sténoses coronariennes retrouvées ?","options":[{"label":"Oui, avec ischémie ou viabilité","to":"n9"},{"label":"Non, réseau coronarien normal","to":"n10"}]},"n9":{"type":"end","tone":"ok","text":"Cardiopathie ischémique : discuter la revascularisation (dysfonction potentiellement réversible). IRM pour séquelle et viabilité."},"n10":{"type":"action","text":"Orientation vers une cardiomyopathie dilatée : rechercher familial (≥ 2 apparentés du 1er degré), toxiques, myocardite, auto-immune, endocrine, péripartum, médicaments.","to":"n11"},"n11":{"type":"end","tone":"info","text":"IRM cardiaque (myocardite, sarcoïdose, amylose, rehaussement tardif pronostique), holter, VO2 selon le contexte. Une cause n'est pas toujours retrouvée."}},"src":"p. 463, 466-470"},{"id":"234-tree-07","title":"Introduire et surveiller IEC et bêtabloquant","rank":"A","objective":"234-obj-20","intro":"Les encadrés 18.3 et 18.4 fixent les règles d'introduction et de titration des IEC et des bêtabloquants : patient stabilisé, faibles doses, paliers, surveillance biologique et tensionnelle, contre-indications à respecter.","root":"n1","nodes":{"n1":{"type":"question","text":"Le patient est-il stabilisé, sans signe de décompensation ?","options":[{"label":"Oui (y compris au décours d'une poussée, avant la sortie)","to":"n2"},{"label":"Non, poussée aiguë en cours","to":"n9"}]},"n2":{"type":"question","text":"Contre-indication à l'IEC : sténose bilatérale des artères rénales, antécédent d'angio-œdème, grossesse, hyperkaliémie ?","options":[{"label":"Non","to":"n3"},{"label":"Oui","to":"n10"}]},"n3":{"type":"action","text":"Débuter l'IEC à faible dose. Vigilance si patient âgé, déshydraté, fortes doses de diurétiques, diabétique, insuffisant rénal ou PAS < 100 mmHg.","note":"Ne pas introduire simultanément IEC et antialdostérone ; AINS proscrits.","to":"n4"},"n4":{"type":"question","text":"À 1 semaine (et après chaque palier) : PA, créatininémie, kaliémie. Hypotension symptomatique ou créatinine augmentée de > 20–30 % ?","options":[{"label":"Non","to":"n5"},{"label":"Oui","to":"n11"}]},"n5":{"type":"action","text":"Titrer vers les doses des essais si tolérées (énalapril 20 mg, captopril 150 mg, ramipril 10 mg).","to":"n6"},"n6":{"type":"question","text":"Contre-indication au bêtabloquant : asthme ou BPCO sévère, bradycardie ou hypotension symptomatique, BAV 2 ou 3 ?","options":[{"label":"Non","to":"n7"},{"label":"Oui","to":"n12"}]},"n7":{"type":"action","text":"Débuter à 1/8 de la dose maximale (carvédilol 3,125 mg × 2/j ou bisoprolol 1,25 mg/j), paliers hebdomadaires, surveiller FC et PA.","to":"n8"},"n8":{"type":"end","tone":"ok","text":"Cible selon tolérance : carvédilol 25 mg × 2/j ou bisoprolol 10 mg/j (molécules validées : carvédilol, métoprolol, bisoprolol, nébivolol)."},"n9":{"type":"end","tone":"danger","text":"Introduire un bêtabloquant en pleine poussée serait une faute ; attendre la stabilisation (quelques jours). IEC/ARA2/sacubitril-valsartan après la poussée."},"n10":{"type":"end","tone":"warn","text":"Pas d'IEC : discuter un autre bloqueur du SRA selon la contre-indication (ARA2 si intolérance, notamment toux) ; poursuivre bêtabloquant, antialdostérone, gliflozine."},"n11":{"type":"end","tone":"warn","text":"Diminuer la posologie ou arrêter l'IEC ; réévaluer PA, créatinine et kaliémie."},"n12":{"type":"end","tone":"info","text":"Sans bêtabloquant : si rythme sinusal et FC > 70–75/min chez un patient symptomatique, l'ivabradine est une alternative."}},"src":"p. 478-480, 485"},{"id":"234-tree-08","title":"Signes d'alerte et décompensation chez l'IC chronique","rank":"A","objective":"234-obj-19","intro":"Éducation et suivi : le livre fixe les signes d'alerte que le patient doit connaître, la conduite en cas d'écart de régime et la gradation de la réponse à une poussée d'IC globale sans OAP franc.","root":"n1","nodes":{"n1":{"type":"question","text":"Que rapporte le patient insuffisant cardiaque chronique éduqué ?","options":[{"label":"Écart de régime salé ponctuel, sans symptôme","to":"n2"},{"label":"Prise de poids de 2–3 kg, a fortiori en 2–3 jours","to":"n3"},{"label":"Aggravation de la dyspnée, orthopnée, œdèmes, météorisme abdominal","to":"n3"},{"label":"Perte de poids progressive sans œdème","to":"n8"}]},"n2":{"type":"end","tone":"info","text":"Augmenter la dose de diurétique le jour même, voire le lendemain (patient éduqué adaptant sa posologie aux apports sodés)."},"n3":{"type":"action","text":"Consulter sans attendre : examen à la recherche d'OAP, de bas débit, et d'un facteur déclenchant (encadré 18.2).","note":"Premier facteur : rupture de traitement ou de régime sans sel. Aussi : infection bronchique, FA, anémie, EP, dysthyroïdie, AINS, diltiazem/vérapamil, antiarythmiques, poussée HTA, SCA.","to":"n4"},"n4":{"type":"question","text":"Tableau clinique ?","options":[{"label":"OAP franc ou choc","to":"n5"},{"label":"Poussée d'IC globale sans OAP franc","to":"n6"}]},"n5":{"type":"end","tone":"danger","text":"Urgence : hospitalisation, traitement IV de l'OAP (furosémide, nitrés si PAS > 110) ou inotropes si choc."},"n6":{"type":"question","text":"Congestion modérée chez un IC chronique connu, contrôlable par une simple hausse des diurétiques oraux ?","options":[{"label":"Oui","to":"n7"},{"label":"Non","to":"n9"}]},"n7":{"type":"end","tone":"ok","text":"Augmentation de la posologie orale des diurétiques, traitement du facteur déclenchant, réévaluation rapprochée ; hospitalisation non systématique."},"n8":{"type":"end","tone":"warn","text":"Dénutrition : signe de gravité et de mauvais pronostic ; aide diététique (épices, éviter les sels de régime riches en potassium)."},"n9":{"type":"end","tone":"warn","text":"Hospitalisation : cure de diurétiques IV, rééquilibration du traitement oral (doses d'IEC, associations), recherche de la cause. Toute hospitalisation est un facteur de gravité."}},"src":"p. 473, 475-476, 485"}],"treatments":{"data":[{"id":"234-tx-01","rank":"A","class":"Inhibiteurs de l'enzyme de conversion (IEC)","molecules":["énalapril","captopril","ramipril"],"context":"1 des 4 classes de classe I dans l'IC à FE < 40 % ; même logique mais preuve moindre (IIb, C) entre 41 et 49 %","indications":["Tout patient en IC à FE diminuée, quelle que soit la classe NYHA","Objectif : viser les doses proches des essais si tolérées (ex. ramipril 10 mg/j)"],"contraindications":["Sténose bilatérale des artères rénales","Antécédent d'angio-œdème","Grossesse","Hyperkaliémie"],"sideEffects":["Hypotension artérielle","Insuffisance rénale fonctionnelle"],"monitoring":["Débuter à faible dose chez un patient stabilisé","Contrôler PA, créatininémie et kaliémie 1 semaine après l'introduction puis après chaque palier","Vigilance particulière chez le sujet âgé, déshydraté, sous fortes doses de diurétiques, diabétique, insuffisant rénal ou déjà hypotendu (PAS < 100 mmHg)"],"interactions":["Éviter l'introduction simultanée avec un antialdostérone","AINS à proscrire"],"pearls":["Réduire la posologie ou arrêter si créatinine augmentée de plus de 20-30 % ou hypotension symptomatique."],"src":"p. 477-478"},{"id":"234-tx-02","rank":"B","class":"Antagonistes des récepteurs de l'angiotensine 2 (ARA2)","molecules":[],"context":"Alternative aux IEC (recommandation I, B), efficacité comparable","indications":["Patients intolérants aux IEC, en particulier en cas de toux"],"contraindications":["Mêmes règles de prescription que les IEC"],"sideEffects":["Mieux tolérés que les IEC : moins de toux"],"monitoring":["Même surveillance PA / créatininémie / kaliémie que pour les IEC"],"interactions":[],"pearls":["Ne remplace les IEC qu'en cas d'intolérance, ne s'y associe pas."],"src":"p. 478"},{"id":"234-tx-03","rank":"B","class":"Inhibiteur des récepteurs de l'angiotensine 2 et de la néprilysine (ARNI, sacubitril/valsartan)","molecules":["valsartan/sacubitril"],"context":"Bloque le système rénine-angiotensine et la néprilysine, augmentant la disponibilité des peptides natriurétiques","indications":["1re intention possible (IIb, B) ou en remplacement d'un IEC chez un patient qui reste symptomatique sous traitement conventionnel optimal (I, B)"],"contraindications":["Non précisées par le chapitre au-delà des règles communes aux bloqueurs du SRA"],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Supériorité démontrée sur un IEC (énalapril) pour réduire mortalité et hospitalisations dans l'IC à FE basse."],"src":"p. 478-479"},{"id":"234-tx-04","rank":"A","class":"Bêtabloquants","molecules":["carvédilol","métoprolol","bisoprolol","nébivolol"],"context":"1 des 4 classes de classe I dans l'IC symptomatique à FE diminuée ; aussi en post-infarctus si FE basse même sans symptôme","indications":["IC symptomatique à FE diminuée, chez un patient stabilisé","Réduisent la mortalité, les hospitalisations pour IC aiguë et le risque de mort subite rythmique"],"contraindications":["Asthme ou BPCO sévère","Bradycardie ou hypotension symptomatique","BAV 2 ou 3"],"sideEffects":[],"monitoring":["Introduire seulement chez un patient stabilisé, sans signe de décompensation (possible au décours d'une poussée, avant la sortie)","Débuter à très faible dose (environ 1/8e de la dose maximale : carvédilol 3,125 mg × 2/j, bisoprolol 1,25 mg/j)","Augmenter par paliers hebdomadaires jusqu'à la dose maximale tolérée (carvédilol 25 mg × 2/j, bisoprolol 10 mg/j)","Surveiller fréquence cardiaque et pression artérielle"],"interactions":[],"pearls":["Introduire un bêtabloquant en pleine poussée aiguë est une faute.","Chez un patient déjà traité, hospitalisé pour décompensation, on ne l'arrête pas systématiquement, sauf mauvaise tolérance ou choc cardiogénique."],"src":"p. 479"},{"id":"234-tx-05","rank":"A","class":"Antialdostérones (antagonistes des récepteurs aux minéralocorticoïdes)","molecules":["spironolactone","éplérénone"],"context":"1 des 4 classes de classe I ; diurétiques épargneurs de potassium étudiés à part","indications":["Tout patient insuffisant cardiaque à FE basse, classes NYHA II à IV","Éplérénone en post-infarctus étendu avec FEVG < 40 % et/ou signes d'IC : réduit encore mortalité, mort subite et récidives"],"contraindications":["Hyperkaliémie","Insuffisance rénale"],"sideEffects":["Hyperkaliémie","Insuffisance rénale, surtout associée à un IEC","Spironolactone : gynécomastie, impuissance"],"monitoring":["Surveiller kaliémie et fonction rénale, notamment en association avec un IEC"],"interactions":["Risque majoré d'hyperkaliémie en association avec un IEC ou un ARA2"],"pearls":[],"src":"p. 479"},{"id":"234-tx-06","rank":"A","class":"Gliflozines (inhibiteurs du SGLT2)","molecules":["dapagliflozine","empagliflozine"],"context":"1 des 4 classes de classe I dans l'IC à FE diminuée ; aussi hautement recommandées (I, A) dans l'IC à FE préservée","indications":["Efficaces pour réduire mortalité cardiovasculaire et hospitalisations, que le patient soit diabétique ou non","À privilégier chez le diabétique à haut risque cardiovasculaire (traitement étiologique/préventif)"],"contraindications":[],"sideEffects":["Infections génitales","Acidocétose, surtout chez le diabétique","Discrète altération rénale initiale, puis effet protecteur rénal à long terme"],"monitoring":[],"interactions":[],"pearls":["Très peu hypotensives, contrairement aux autres classes de l'IC.","Mécanisme d'action au-delà de l'effet glycosurique et diurétique encore mal élucidé."],"src":"p. 479-480"},{"id":"234-tx-07","rank":"A","class":"Diurétiques de l'anse","molecules":["furosémide","bumétanide"],"context":"Traitement symptomatique de la rétention hydrosodée, en association aux 4 classes cardioprotectrices","indications":["Signes congestifs (œdèmes, rétention hydrosodée)"],"contraindications":[],"sideEffects":[],"monitoring":["Adapter la dose aux apports sodés : de 20 mg/j (formes légères) jusqu'à 500 mg/j voire 1 g/j (formes sévères)","Viser la dose minimale efficace"],"interactions":[],"pearls":["N'ont pas démontré de bénéfice sur la mortalité, contrairement aux 4 classes cardioprotectrices.","Un patient éduqué peut adapter lui-même la posologie à ses apports sodés."],"src":"p. 480"},{"id":"234-tx-08","rank":"B","class":"Diurétiques thiazidiques","molecules":["hydrochlorothiazide"],"context":"Réservés aux formes graves d'IC résistantes au diurétique de l'anse","indications":["Résistance aux diurétiques : persistance de signes congestifs malgré de fortes doses de furosémide"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":["Prescrits en association au furosémide, jamais seuls dans cette indication"],"pearls":[],"src":"p. 480"},{"id":"234-tx-09","rank":"B","class":"Ivabradine","molecules":["ivabradine"],"context":"2e intention, patient restant symptomatique malgré le traitement de classe I","indications":["Patient symptomatique (NYHA II-IV), en rythme sinusal, FC > 70-75/min malgré le bêtabloquant, ou en cas d'intolérance/contre-indication au bêtabloquant"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Ralentit uniquement la fréquence cardiaque (bloque le courant If) ; réduit le risque d'hospitalisation pour IC."],"src":"p. 480"},{"id":"234-tx-10","rank":"B","class":"Digoxine","molecules":["digoxine"],"context":"2e intention, forme la plus ancienne du traitement de l'IC","indications":["IC résistante au traitement conventionnel (améliore les symptômes)","Fibrillation atriale associée : ralentit la fréquence cardiaque"],"contraindications":[],"sideEffects":["Effet neutre sur la survie","Risque de surdosage, notamment si insuffisance rénale","Effets potentiellement proarythmogènes"],"monitoring":["Dosage régulier de la concentration plasmatique (marge thérapeutique étroite)"],"interactions":[],"pearls":[],"src":"p. 480"},{"id":"234-tx-11","rank":"B","class":"Dérivés nitrés (traitement chronique d'appoint)","molecules":[],"context":"Vasodilatateurs à prédominance veineuse","indications":["Patient symptomatique avec pressions de remplissage restant élevées"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 480"},{"id":"234-tx-12","rank":"A","class":"Amiodarone","molecules":["amiodarone"],"context":"Seul antiarythmique utilisable dans l'IC à FEVG diminuée","indications":["Troubles du rythme ventriculaire graves","Prévention des récidives après réduction d'une fibrillation atriale"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":["Peut être associée au bêtabloquant"],"pearls":["N'a pas démontré de bénéfice sur la mortalité ou la mort subite dans l'IC."],"src":"p. 481"},{"id":"234-tx-13","rank":"B","class":"Antiagrégants plaquettaires et anticoagulants","molecules":["aspirine","rivaroxaban","apixaban","dabigatran"],"context":"Selon l'étiologie de l'IC ou une fibrillation atriale associée","indications":["Aspirine chez le coronarien stable ; double antiagrégation plusieurs mois après SCA ou stent","Anticoagulant oral direct privilégié aux AVK en cas de FA","Anticoagulation en cas de thrombus intracavitaire ou d'AVC embolique"],"contraindications":[],"sideEffects":[],"monitoring":["Calculer le score CHA2DS2-VA pour le risque embolique et le score HAS-BLED pour le risque hémorragique"],"interactions":[],"pearls":[],"src":"p. 481"},{"id":"234-tx-14","rank":"A","class":"Traitements contre-indiqués dans l'IC à FE diminuée","molecules":["diltiazem","vérapamil","flécaïnide","AINS"],"context":"Classes à proscrire, à connaître comme pièges","indications":[],"contraindications":["Diltiazem et vérapamil : effet inotrope négatif délétère","Antiarythmiques de classe I (flécaïnide) : proscrits","AINS : risque de rétention hydrosodée"],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Les dihydropyridines (amlodipine, félodipine) ont un effet neutre et restent utilisables si une indication associée existe (angor, HTA)."],"src":"p. 481"},{"id":"234-tx-15","rank":"B","class":"Resynchronisation cardiaque (stimulateur biventriculaire, CRT)","molecules":[],"context":"Traitement « électrique » de l'IC à FEVG altérée","indications":["IC symptomatique (NYHA II-IV), FEVG ≤ 35 %, QRS ≥ 130 ms","Efficacité maximale si bloc de branche gauche, QRS ≥ 150 ms et cardiopathie non ischémique"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Sondes en atrium droit, ventricule droit et paroi latérale du VG via le sinus coronaire, pour restaurer une contraction synchrone."],"src":"p. 481-482"},{"id":"234-tx-16","rank":"A","class":"Défibrillateur automatique implantable (DAI)","molecules":[],"context":"Traitement « électrique » de l'IC à FEVG altérée","indications":["Prévention secondaire : après arrêt cardiaque récupéré sur FV, ou TV symptomatique","Prévention primaire : symptomatique (NYHA II-III), FEVG < 35 %, à distance (≥ 6 semaines) d'un infarctus/revascularisation si cardiopathie ischémique, ou après ≥ 3 mois de traitement médical optimal si cardiopathie non ischémique"],"contraindications":["Réservé aux patients dont l'espérance de survie dépasse 1 an ; le stade NYHA IV n'en relève pas, sauf projet de greffe ou d'assistance"],"sideEffects":["Infection de sonde","Chocs inappropriés"],"monitoring":[],"interactions":["Un dispositif combiné DAI-CRT est possible si les deux indications coexistent"],"pearls":[],"src":"p. 481-482"},{"id":"234-tx-17","rank":"B","class":"Traitement percutané des fuites valvulaires secondaires","molecules":[],"context":"IM ou IT fonctionnelles persistant malgré traitement optimal de l'IC","indications":["IM secondaire significative persistante malgré traitement optimal, si l'IC n'est pas trop avancée : clip percutané après discussion pluridisciplinaire","Correction percutanée de fuites tricuspidiennes fonctionnelles importantes : encore en évaluation"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 483"},{"id":"234-tx-18","rank":"B","class":"Transplantation cardiaque","molecules":[],"context":"IC terminale","indications":["Symptômes invalidants, mauvais pronostic, absence d'alternative, traitement médical et non médical déjà maximal, patient adhérent au futur traitement immunosuppresseur"],"contraindications":["Âge physiologique avancé (rarement au-delà de 65-70 ans)","Pathologie limitant l'espérance de vie","Infection active","Insuffisance rénale sévère","HTAP fixée (résistances pulmonaires > 5 unités Wood)","Artériopathie diffuse"],"sideEffects":["Rejet","Effets indésirables des immunosuppresseurs (infections, cancers, HTA, insuffisance rénale)","Maladie coronarienne du greffon"],"monitoring":["Suivi à vie sous traitement immunosuppresseur"],"interactions":[],"pearls":["Le principal facteur limitant reste le nombre de greffons disponibles."],"src":"p. 483"},{"id":"234-tx-19","rank":"B","class":"Assistance circulatoire mécanique","molecules":[],"context":"IC terminale, en pont vers la greffe ou comme traitement définitif","indications":["Courte durée (ECMO) en cas d'urgence","Longue durée (assistance mono ou biventriculaire) en pont vers greffe, ou en traitement définitif chez un patient non éligible à la greffe"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 483"},{"id":"234-tx-20","rank":"B","class":"Tafamidis (amylose cardiaque à transthyrétine)","molecules":["tafamidis"],"context":"Traitement spécifique de l'amylose cardiaque à transthyrétine, cause particulière d'IC à FE préservée/restrictive","indications":["Amylose cardiaque à transthyrétine"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["D'autres traitements sont en cours de développement pour cette étiologie."],"src":"p. 484"},{"id":"234-tx-21","rank":"A","class":"Mesures hygiénodiététiques et éducation thérapeutique","molecules":[],"context":"S'adressent à presque tous les patients insuffisants cardiaques, jamais validées par essai mais fondamentales","indications":["Régime pauvre en sel, 5 à 6 g/j","Pesée régulière : consulter si prise de poids de 2-3 kg, a fortiori en 2-3 jours","Activité physique régulière (le repos strict est délétère)","Sevrage tabagique impératif ; réduction ou arrêt de l'alcool (arrêt total si cardiomyopathie alcoolique)","Vaccination antigrippale, anti-Covid-19, antipneumococcique","Éviction des métiers à efforts physiques importants ou à horaires décalés dans les formes avérées","Contraception adaptée si IC sévère (minidosée en œstrogènes ou dispositif intra-utérin)"],"contraindications":[],"sideEffects":["Un régime sans sel trop strict peut conduire à une dénutrition chez certains patients"],"monitoring":[],"interactions":[],"pearls":["Une perte de poids progressive sans œdème traduit une dénutrition, signe de gravité et de mauvais pronostic."],"src":"p. 476-477"},{"id":"234-tx-22","rank":"B","class":"Télésurveillance de l'insuffisance cardiaque","molecules":[],"context":"Programme remboursé, mesures transmises quasi quotidiennement à une plateforme d'alerte","indications":["Patients IC chroniques, pour dépister précocement une décompensation et éviter une hospitalisation"],"contraindications":[],"sideEffects":[],"monitoring":["Paramètres suivis : pression artérielle, fréquence cardiaque, poids"],"interactions":[],"pearls":["Une alerte déclenche un appel du patient, le plus souvent par un infirmier."],"src":"p. 484"},{"id":"234-tx-23","rank":"A","class":"Oxygénothérapie et assistance ventilatoire de l'OAP","molecules":[],"context":"Mesures non médicamenteuses de l'OAP cardiogénique, en complément du traitement diurétique et vasodilatateur","indications":["Oxygénothérapie (sonde nasale puis masque) si SaO2 < 90 %, objectif SaO2 > 90 %","CPAP en cas d'échec du traitement médicamenteux (FR > 25/min, SaO2 < 90 %)","Intubation et ventilation invasive en dernier recours, si persistance de la détresse et épuisement respiratoire"],"contraindications":["Prudence pour l'oxygénothérapie chez les patients à risque d'hypercapnie"],"sideEffects":[],"monitoring":["Monitorage continu : fréquence cardiaque, pression artérielle, oxymétrie, scope"],"interactions":[],"pearls":[],"src":"p. 485"},{"id":"234-tx-24","rank":"A","class":"Inotropes du choc cardiogénique","molecules":["dobutamine","milrinone","énoximone","lévosimendan"],"context":"Traitement du choc cardiogénique, tableau ultime de l'IC aiguë","indications":["Dobutamine IV en 1re intention","Inhibiteur des phosphodiestérases (milrinone, énoximone) si le patient est déjà sous bêtabloquant","Lévosimendan (sensibilisateur calcique, inotrope et vasodilatateur) parfois utilisé pour aider au sevrage des inotropes"],"contraindications":[],"sideEffects":[],"monitoring":["Sonde urinaire systématique","Monitorage invasif de la pression artérielle (cathéter radial)"],"interactions":[],"pearls":["En l'absence de réponse : discuter une assistance circulatoire, un cœur artificiel ou une greffe en urgence."],"src":"p. 486"}],"strategies":[{"id":"234-strat-01","rank":"A","title":"Stratégie thérapeutique de l'IC chronique à FE diminuée (< 40 %)","content":"**Base (classe I, quelle que soit la NYHA)** : les 4 classes cardioprotectrices ensemble — bloqueur du SRA (IEC, ou ARA2 si intolérance, ou ARNI en remplacement chez le patient restant symptomatique), bêtabloquant, antialdostérone, gliflozine — plus un diurétique de l'anse si signes congestifs.\n\n**Étape suivante** : réévaluer après optimisation. Si le patient reste symptomatique (NYHA II-IV) avec FEVG ≤ 35 %, discuter le traitement électrique selon le rythme et le QRS :\n- rythme sinusal, QRS ≥ 130 ms → resynchronisation (CRT), classe IIa entre 130 et 149 ms, classe I si QRS ≥ 150 ms ;\n- QRS < 130 ms → DAI en prévention primaire si cardiopathie ischémique à distance d'un infarctus/revascularisation (classe I) ou non ischémique après ≥ 3 mois de traitement optimal (classe IIa), sous réserve d'une espérance de vie > 1 an.\n\n**Si symptômes persistants malgré ce traitement optimal** : traitements de classe II à discuter (ivabradine si rythme sinusal et FC élevée, digoxine, dérivés nitrés), clip mitral percutané si IM secondaire significative, puis évaluation d'une greffe ou d'une assistance circulatoire au stade terminal.\n\n**Suivi** : parcours de soins structuré, éducation thérapeutique sur les signes d'alerte, réadaptation cardiaque, télésurveillance possible.","src":"p. 477-483"},{"id":"234-strat-02","rank":"B","title":"Stratégie thérapeutique de l'IC à FE préservée (> 50 %)","content":"Moins codifiée que celle de l'IC à FE diminuée. Seule classe validée avec un haut niveau de preuve : les **gliflozines** (dapagliflozine, empagliflozine), qui réduisent mortalité cardiovasculaire et hospitalisations.\n\nLe traitement de fond peut être organisé selon un moyen mnémotechnique en 7 axes :\n- **A**rythmies : bêtabloquant ou inhibiteur calcique bradycardisant pour ralentir la FC et allonger la diastole ;\n- **B**lood pressure : bloqueurs du SRA (IEC/ARA2) et antialdostérones, pour améliorer la relaxation et faire régresser l'hypertrophie ventriculaire gauche ;\n- **C**omorbidités : cardiaques (FA, ischémie, valvulopathie) et non cardiaques (diabète, dysthyroïdie…) à traiter ;\n- **D**iurétique : thiazidique ou de l'anse si signes congestifs, avec surveillance rénale ;\n- **E**xercice : activité physique adaptée et régulière ;\n- **F**ollow-up : organiser un suivi régulier ;\n- **G**liflozines : dapagliflozine ou empagliflozine, hautement recommandées.\n\nDans l'amylose cardiaque à transthyrétine, un traitement spécifique (tafamidis) existe désormais.","src":"p. 483-484"},{"id":"234-strat-03","rank":"A","title":"Prise en charge de l'OAP cardiogénique","content":"**Au domicile** : position demi-assise, furosémide IV 1 mg/kg (à répéter si besoin), dérivés nitrés sublinguaux si PAS > 100 mmHg, appel du Samu selon la gravité, hospitalisation.\n\n**À l'hôpital / Samu** : position assise, voie veineuse (G5 %), monitorage complet (FC, PA, SpO2, scope), bilan sans retarder le traitement (ECG, radio thoracique, biologie, ± écho pulmonaire), oxygénothérapie si SpO2 < 90 % (prudence si risque d'hypercapnie), furosémide IV 1 mg/kg adapté à la diurèse, dérivés nitrés IV (trinitrine 1 mg/h) si PAS > 110 mmHg, morphine IV réservée à l'anxiété majeure ou à la douleur thoracique, traitement du facteur déclenchant (digoxine IV + anticoagulation efficace si FA rapide, nicardipine IV si poussée hypertensive), anticoagulation préventive systématique par HBPM.\n\n**Escalade en cas d'échec** (FR > 25/min, SpO2 < 90 %) : CPAP, puis intubation-ventilation invasive en dernier recours.\n\n**Règles de fond** : jamais de bêtabloquant introduit en pleine poussée (arrêt ou réduction si déjà prescrit) ; IEC/ARA2/ARNI réintroduits seulement après stabilisation ; rechercher systématiquement une cause curable (CHAMPIT).","src":"p. 485-486"},{"id":"234-strat-04","rank":"A","title":"Prise en charge du choc cardiogénique","content":"Confirmer le diagnostic (PAS < 90 mmHg, signes d'hypoperfusion périphérique, oligurie, altération de conscience, bas débit à l'échocardiographie), puis débuter les inotropes : dobutamine IV en 1re intention, ou inhibiteur des phosphodiestérases (milrinone, énoximone) si le patient est déjà sous bêtabloquant. Sonde urinaire systématique et monitorage invasif de la pression artérielle (cathéter radial). Le lévosimendan peut aider au sevrage des inotropes en cas de dépendance.\n\nRechercher systématiquement une cause curable à traiter spécifiquement (CHAMPIT). En l'absence de réponse satisfaisante, discuter une assistance circulatoire (ECMO de courte durée, assistance uni ou biventriculaire de plus longue durée), un cœur artificiel ou une greffe cardiaque en urgence.","src":"p. 486"},{"id":"234-strat-05","rank":"B","title":"Poussée d'insuffisance cardiaque globale sans OAP franc","content":"Hospitalisation fréquente mais non systématique chez un patient déjà connu comme insuffisant cardiaque chronique (parfois une simple majoration de la posologie orale des diurétiques suffit). En cas d'hospitalisation : cure de diurétiques par voie intraveineuse, rééquilibration du traitement oral (posologies, associations médicamenteuses), et recherche systématique de la cause de la déstabilisation.","src":"p. 485"}]},"cases":[{"id":"234-case-01","title":"M. R., 67 ans, dyspnée d'effort et antécédent d'infarctus","rank":"A","summary":"Homme de 67 ans, antécédent d'infarctus antérieur, dyspnée d'effort progressive : diagnostic d'IC à FE diminuée d'origine ischémique, bilan étiologique, puis titration du traitement de fond.","difficulty":2,"timeline":["Consultation initiale","Bilan diagnostique","Diagnostic étiologique","Traitement et titration","Suivi à long terme"],"steps":[{"id":"234-case-01-s01","phase":0,"narrative":"M. R., 67 ans, ancien fumeur, antécédent d'infarctus antérieur traité par angioplastie il y a 6 ans, consulte pour une gêne respiratoire apparue progressivement depuis 3 mois, présente désormais pour une marche rapide ou en côte mais pas au repos. Il signale aussi une fatigue inhabituelle et un œdème vespéral des chevilles.","question":{"type":"QRM","stem":"Parmi les éléments suivants, lesquels orientent vers une insuffisance cardiaque plutôt qu'une simple dyspnée d'effort banale ?","options":[{"t":"Le terrain : cardiopathie ischémique connue","ok":true,"why":"Une cardiopathie sous-jacente est nécessaire à la définition de l'IC ; l'antécédent d'infarctus est un facteur de risque majeur."},{"t":"La dyspnée d'effort isolée suffit à elle seule à affirmer le diagnostic","ok":false,"why":"La dyspnée d'effort est fréquente mais peu spécifique ; elle ne suffit pas au diagnostic."},{"t":"La fatigue associée","ok":true,"why":"La fatigue est un symptôme fréquemment associé à l'IC."},{"t":"L'œdème des membres inférieurs vespéral","ok":true,"why":"Les œdèmes déclives sont un signe évocateur de rétention hydrosodée."},{"t":"L'absence de douleur thoracique élimine toute atteinte cardiaque","ok":false,"why":"L'IC peut se présenter sans douleur thoracique, en particulier à distance de l'événement ischémique initial."}],"explanation":"L'IC associe toujours des symptômes, des signes physiques et une anomalie cardiaque sous-jacente ; chaque élément pris isolément manque de spécificité."},"reveal":"Le médecin décide d'approfondir l'interrogatoire et l'examen clinique avant de conclure.","src":"p. 458, 461-462"},{"id":"234-case-01-s02","phase":0,"narrative":"À l'examen : PA 128/78 mmHg, FC 78/min régulière, auscultation pulmonaire avec quelques râles crépitants aux bases, choc de pointe légèrement dévié, pas de turgescence jugulaire ni de reflux hépatojugulaire, discrets œdèmes des chevilles prenant le godet.","question":{"type":"QRU","stem":"Quel est, parmi les signes suivants, celui qui aurait été le plus spécifique d'une atteinte du cœur droit s'il avait été présent ?","options":[{"t":"Râles crépitants bilatéraux","ok":false,"why":"Signe pulmonaire de congestion gauche, peu spécifique."},{"t":"Turgescence jugulaire","ok":true,"why":"C'est le signe le plus spécifique d'IC droite décrit dans le chapitre."},{"t":"Œdèmes des membres inférieurs","ok":false,"why":"Sensible mais peu spécifique, peut avoir d'autres causes."},{"t":"Choc de pointe dévié","ok":false,"why":"Traduit une dilatation ventriculaire gauche, pas un signe droit spécifique."},{"t":"Tachycardie","ok":false,"why":"Peu spécifique et souvent absente sous bêtabloquant."}],"explanation":"La turgescence jugulaire, avec le reflux hépatojugulaire, est le signe le plus spécifique d'IC droite."},"reveal":"L'examen clinique reste pauvre : le médecin décide de doser les peptides natriurétiques.","src":"p. 463"},{"id":"234-case-01-s03","phase":1,"narrative":"Le dosage du NT-proBNP est prescrit en première intention devant cette présentation non aiguë.","question":{"type":"QROC","question":"En dehors d'un contexte aigu, en dessous de quelle valeur de NT-proBNP le diagnostic d'IC devient-il peu probable (bonne valeur prédictive négative) ?","answer":"125 pg/mL","accept":["< 125 pg/mL","125"],"keywords":["NT-proBNP","125"],"explanation":"En présentation non aiguë, le seuil d'exclusion est NT-proBNP < 125 pg/mL (ou BNP < 35 pg/mL)."},"reveal":"Le NT-proBNP de M. R. revient à 480 pg/mL, nettement au-dessus du seuil d'exclusion : une échocardiographie est demandée.","src":"p. 465"},{"id":"234-case-01-s04","phase":1,"narrative":"L'échocardiographie transthoracique montre un ventricule gauche dilaté avec une fraction d'éjection à 32 %, une hypokinésie de la paroi antérieure, sans valvulopathie significative.","question":{"type":"QRM","stem":"Que peut-on conclure à ce stade chez M. R. ?","options":[{"t":"Il s'agit d'une IC à fraction d'éjection diminuée (FEVG < 40 %)","ok":true,"why":"FEVG à 32 %, bien en dessous du seuil de 40 %."},{"t":"L'anomalie segmentaire est cohérente avec l'antécédent d'infarctus antérieur","ok":true,"why":"L'hypokinésie de la paroi antérieure est compatible avec la séquelle d'infarctus connue."},{"t":"Une cause ischémique doit être formellement éliminée malgré l'antécédent connu","ok":true,"why":"Devant toute FEVG abaissée, il faut rechercher une cause ischémique évolutive (ici réévaluer la coronaropathie)."},{"t":"La FEVG mesurée élimine toute possibilité de bénéfice d'une revascularisation","ok":false,"why":"Une dysfonction peut être partiellement réversible après revascularisation d'un myocarde viable."},{"t":"Le diagnostic d'IC à FE préservée est confirmé","ok":false,"why":"FEVG à 32 % correspond à une FE diminuée, pas préservée."}],"explanation":"L'ETT confirme l'IC à FE diminuée et oriente vers l'étiologie ischémique déjà connue, à réévaluer."},"reveal":"Un bilan étiologique complémentaire est programmé, avec réévaluation de la coronaropathie.","src":"p. 460-461, 466-468"},{"id":"234-case-01-s05","phase":1,"narrative":"Interrogé plus précisément, M. R. précise que la gêne apparaît désormais pour une marche sur terrain plat, sans qu'il n'ait de gêne au repos.","question":{"type":"QROC","question":"Quelle classe NYHA correspond à une gêne pour des efforts peu intenses, comme la marche sur terrain plat ?","answer":"NYHA III","accept":["III","stade III","classe III"],"keywords":["NYHA","III"],"explanation":"Le stade III correspond à une gêne pour des efforts peu intenses (terrain plat, moins de 2 étages)."},"reveal":"M. R. est donc classé NYHA III, ce qui influence la stratégie thérapeutique ultérieure.","src":"p. 461-462"},{"id":"234-case-01-s06","phase":2,"narrative":"Compte tenu de l'antécédent d'infarctus et de l'anomalie segmentaire, une coronarographie est réalisée : elle retrouve une sténose serrée de l'artère interventriculaire antérieure, jugée responsable d'une ischémie résiduelle sur le territoire hypokinétique.","question":{"type":"QRM","stem":"Quelles affirmations sont exactes concernant la prise en charge étiologique de M. R. ?","options":[{"t":"La cardiopathie ischémique est la première cause d'IC actuellement, ce qui est cohérent avec ce tableau","ok":true,"why":"Le chapitre cite la cardiopathie ischémique comme première cause globale d'IC aujourd'hui."},{"t":"Une revascularisation peut être discutée si le myocarde hypokinétique est viable","ok":true,"why":"Une dysfonction ischémique chronique peut être partiellement réversible après revascularisation d'un territoire viable."},{"t":"La coronarographie était l'examen le plus adapté ici plutôt qu'un coroscanner","ok":true,"why":"La coronarographie est privilégiée en cas d'angor, de probabilité intermédiaire/haute ou d'ischémie documentée avec projet de revascularisation."},{"t":"Cette découverte élimine la nécessité de traitement médicamenteux de fond de l'IC","ok":false,"why":"Le traitement médicamenteux de fond de l'IC à FE diminuée reste indiqué, que la revascularisation soit réalisée ou non."},{"t":"Une IRM cardiaque n'a plus aucun intérêt une fois la coronarographie réalisée","ok":false,"why":"L'IRM garde un intérêt pour préciser la viabilité et le pronostic."}],"explanation":"La revascularisation d'un myocarde viable peut améliorer la fonction, mais ne dispense pas du traitement de fond de l'IC à FE diminuée."},"reveal":"Une angioplastie de l'IVA est réalisée avec succès. Le traitement de fond de l'IC doit maintenant être instauré.","src":"p. 467-469"},{"id":"234-case-01-s07","phase":2,"narrative":"Avant de conclure le bilan étiologique, l'interne présente le dossier en staff et s'interroge sur la place respective de la coronarographie et du coroscanner dans le bilan de l'IC à FEVG abaissée.","question":{"type":"OPEN","prompt":"Expliquez, à partir des éléments donnés par le chapitre, dans quelles situations le coroscanner est préféré à la coronarographie pour le bilan étiologique d'une IC à FEVG abaissée, et inversement.","rubric":[{"point":"Coroscanner privilégié si probabilité de maladie coronarienne faible ou intermédiaire","weight":2},{"point":"Coronarographie privilégiée si angor, probabilité intermédiaire à haute, ou ischémie documentée avec projet de revascularisation","weight":2},{"point":"Le choix dépend donc de la probabilité pré-test et d'un projet thérapeutique de revascularisation","weight":1}],"model":"Le coroscanner est l'examen de 1re intention lorsque la probabilité de maladie coronarienne est faible ou intermédiaire, car il permet d'éliminer une cause coronarienne de façon non invasive. La coronarographie est réservée aux patients ayant un angor, une probabilité intermédiaire à haute de maladie coronarienne, ou une ischémie déjà documentée avec un projet de revascularisation, car elle permet un geste thérapeutique dans le même temps.","explanation":"Le choix entre coroscanner et coronarographie repose sur la probabilité pré-test et l'existence d'un projet de revascularisation."},"reveal":"Chez M. R., l'angor et l'anomalie segmentaire documentée justifiaient bien le recours direct à la coronarographie.","src":"p. 468-469"},{"id":"234-case-01-s08","phase":3,"narrative":"Une fois M. R. stabilisé après l'angioplastie, le cardiologue souhaite débuter le traitement de fond de l'IC à FE diminuée.","question":{"type":"QRM","stem":"Quelles sont les modalités correctes d'introduction du traitement chez ce patient stabilisé ?","options":[{"t":"Débuter simultanément un IEC à faible dose et un bêtabloquant à très faible dose","ok":true,"why":"Les deux classes peuvent être introduites chez un patient stabilisé, chacune à dose initiale faible, avec titration progressive séparée."},{"t":"Introduire d'emblée les doses cibles des essais cliniques pour aller plus vite","ok":false,"why":"Il faut débuter à faible dose et titrer progressivement selon la tolérance."},{"t":"Associer d'emblée un antialdostérone et un IEC dès le premier jour","ok":false,"why":"Il est recommandé d'éviter l'introduction simultanée d'un IEC et d'un antialdostérone, par risque d'hyperkaliémie."},{"t":"Prévoir une surveillance de la PA, de la créatininémie et de la kaliémie à 1 semaine","ok":true,"why":"C'est la surveillance recommandée après l'introduction d'un IEC et après chaque palier."},{"t":"Attendre impérativement un an après l'infarctus avant tout traitement de fond","ok":false,"why":"Le traitement de fond doit être débuté dès la stabilisation, sans délai injustifié."}],"explanation":"Chez un patient stabilisé, l'IEC et le bêtabloquant sont débutés à faible dose puis titrés progressivement, avec surveillance biologique rapprochée ; on évite l'introduction simultanée avec un antialdostérone."},"reveal":"Le cardiologue débute ramipril 2,5 mg/j et bisoprolol 1,25 mg/j, avec un contrôle biologique prévu à 1 semaine.","src":"p. 477-479"},{"id":"234-case-01-s09","phase":3,"narrative":"Une semaine plus tard, le bilan biologique de contrôle montre une kaliémie à 5,8 mmol/L et une créatininémie augmentée de 35 % par rapport à la valeur de base, sans hypotension symptomatique.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir la plus appropriée devant ce résultat ?","options":[{"t":"Diminuer la posologie ou arrêter l'IEC","ok":true,"why":"Une augmentation de la créatinine de plus de 20-30 % impose de réduire ou arrêter le bloqueur du SRA."},{"t":"Poursuivre l'IEC sans modification car le patient est asymptomatique","ok":false,"why":"L'hyperkaliémie à 5,8 mmol/L et l'élévation franche de la créatinine imposent une action, même sans symptôme."},{"t":"Introduire immédiatement un antialdostérone pour renforcer le blocage du SRA","ok":false,"why":"C'est contre-indiqué ici : l'antialdostérone est proscrit en cas d'hyperkaliémie et aggraverait le risque."},{"t":"Réévaluer la kaliémie et la fonction rénale après ajustement","ok":true,"why":"Un contrôle biologique rapproché est nécessaire après toute modification du traitement."},{"t":"Augmenter la dose de bêtabloquant pour compenser","ok":false,"why":"Le bêtabloquant n'a pas d'effet sur la kaliémie ni la fonction rénale ; ce n'est pas la réponse appropriée."}],"explanation":"Une hyperkaliémie associée à une élévation significative de la créatinine impose de réduire ou d'arrêter le bloqueur du SRA en cause, avec réévaluation biologique."},"reveal":"Le ramipril est temporairement réduit ; la kaliémie et la fonction rénale se normalisent en une semaine. La titration du bêtabloquant se poursuit.","src":"p. 477-478"},{"id":"234-case-01-s10","phase":3,"narrative":"La titration du bisoprolol se poursuit par paliers, avec une surveillance régulière.","question":{"type":"QRU","stem":"Quels paramètres doivent être surveillés à chaque palier d'augmentation du bêtabloquant ?","options":[{"t":"Fréquence cardiaque et pression artérielle","ok":true,"why":"Ce sont les deux paramètres de surveillance cités pour l'introduction et la titration du bêtabloquant."},{"t":"Kaliémie uniquement","ok":false,"why":"La kaliémie est surtout surveillée pour les bloqueurs du SRA et les antialdostérones, pas spécifiquement pour le bêtabloquant."},{"t":"Glycémie capillaire","ok":false,"why":"Non mentionnée dans la surveillance du bêtabloquant par le chapitre."},{"t":"INR","ok":false,"why":"Sans rapport avec la surveillance du bêtabloquant."},{"t":"Saturation en oxygène au repos","ok":false,"why":"Non mentionnée dans la surveillance du bêtabloquant."}],"explanation":"La surveillance du bêtabloquant repose sur la fréquence cardiaque et la pression artérielle à chaque palier."},"reveal":"M. R. atteint progressivement bisoprolol 7,5 mg/j, bien toléré, avec une fréquence cardiaque à 62/min.","src":"p. 479"},{"id":"234-case-01-s11","phase":4,"narrative":"Six mois plus tard, sous traitement optimisé (IEC, bêtabloquant, antialdostérone introduit secondairement, gliflozine), l'ECG montre un bloc de branche gauche avec QRS à 142 ms, en rythme sinusal, et l'échocardiographie de contrôle retrouve une FEVG à 30 %, le patient restant NYHA II-III.","question":{"type":"QRM","stem":"Quelles options thérapeutiques sont désormais à discuter chez M. R. ?","options":[{"t":"Resynchronisation cardiaque (CRT), classe IIa dans cette configuration de QRS","ok":true,"why":"QRS entre 130 et 149 ms avec BBG et FEVG ≤ 35 % correspond à une indication de classe IIa de resynchronisation."},{"t":"Défibrillateur automatique implantable en prévention primaire à discuter également","ok":true,"why":"FEVG < 35 %, patient symptomatique, à distance de l'événement ischémique : indication de DAI en prévention primaire à évaluer."},{"t":"Un dispositif combiné CRT-DAI peut être envisagé si les deux indications coexistent","ok":true,"why":"Le chapitre prévoit la possibilité d'un dispositif combinant les deux fonctions."},{"t":"Transplantation cardiaque immédiate, sans autre option","ok":false,"why":"La greffe est réservée aux formes invalidantes sans alternative, après optimisation maximale du traitement ; ce n'est pas l'étape ici."},{"t":"Arrêt du traitement médicamenteux au profit du seul dispositif électrique","ok":false,"why":"Le traitement médicamenteux de fond doit être poursuivi en association avec le traitement électrique."}],"explanation":"Avec un BBG, un QRS de 142 ms et une FEVG ≤ 35 % persistante malgré traitement optimal, la resynchronisation (et éventuellement un DAI associé) doit être discutée."},"reveal":"Après réunion pluridisciplinaire, un dispositif combiné CRT-DAI est implanté.","src":"p. 481-482"},{"id":"234-case-01-s12","phase":4,"narrative":"Un an après l'implantation, M. R. est stable, suit son traitement et participe à un programme de réadaptation cardiaque.","question":{"type":"QROC","question":"Quel signe d'alerte, en termes de prise de poids, doit inciter M. R. à consulter rapidement son médecin ?","answer":"Une prise de poids de 2 à 3 kg, surtout en 2 à 3 jours","accept":["2-3 kg en 2-3 jours","prise de poids rapide"],"keywords":["poids","2-3 kg","2-3 jours"],"explanation":"Une prise de poids de 2 à 3 kg, a fortiori en 2-3 jours, doit faire consulter rapidement car elle traduit une rétention hydrosodée débutante."},"reveal":"M. R. a bien intégré cette règle et adapte désormais sa dose de diurétique en cas d'écart de régime, comme convenu avec son cardiologue.","src":"p. 476"}]},{"id":"234-case-02","title":"Mme L., 74 ans, détresse respiratoire brutale","rank":"A","summary":"Femme de 74 ans, hypertendue, appelle le Samu pour une détresse respiratoire aiguë : OAP cardiogénique compliquant un syndrome coronarien aigu, évoluant vers un choc cardiogénique.","difficulty":3,"timeline":["Appel et prise en charge initiale","Bilan aux urgences","Diagnostic différentiel","Traitement de l'OAP","Évolution et choc cardiogénique"],"steps":[{"id":"234-case-02-s01","phase":0,"narrative":"Mme L., 74 ans, hypertendue traitée, appelle le Samu en pleine nuit pour une gêne respiratoire d'apparition brutale, avec impossibilité de rester allongée, sueurs profuses et toux ramenant une expectoration mousseuse rosée.","question":{"type":"QRM","stem":"Quels éléments de ce tableau sont évocateurs d'un œdème aigu pulmonaire cardiogénique ?","options":[{"t":"L'orthopnée forcée d'apparition brutale","ok":true,"why":"L'orthopnée forcée est un élément typique du tableau clinique de l'OAP décrit dans le chapitre."},{"t":"Les sueurs profuses","ok":true,"why":"Les sueurs font partie du tableau clinique classique de l'OAP."},{"t":"L'expectoration mousseuse rosée","ok":true,"why":"C'est un signe caractéristique de l'inondation alvéolaire par transsudat."},{"t":"Le caractère strictement diurne des symptômes","ok":false,"why":"Au contraire, la dyspnée paroxystique nocturne est un mode de révélation classique, pas la survenue diurne."},{"t":"L'absence totale de tout antécédent cardiovasculaire","ok":false,"why":"L'énoncé ne mentionne aucun élément excluant une cardiopathie ; ce critère n'est de toute façon pas discriminant pour l'OAP."}],"explanation":"Orthopnée forcée, sueurs, cyanose, grésillement laryngé et expectoration mousseuse rosée composent le tableau typique de l'OAP cardiogénique."},"reveal":"L'équipe du Samu arrive rapidement au domicile de Mme L.","src":"p. 472"},{"id":"234-case-02-s02","phase":0,"narrative":"À l'arrivée du Samu : FR 32/min, SpO2 88 % en air ambiant, PA 165/95 mmHg, auscultation avec crépitants remontant jusqu'aux sommets.","question":{"type":"QRU","stem":"Quel geste thérapeutique immédiat est recommandé au domicile devant ce tableau ?","options":[{"t":"Position demi-assise et furosémide IV 1 mg/kg","ok":true,"why":"C'est la prise en charge initiale recommandée au domicile devant un OAP."},{"t":"Décubitus strict pour limiter l'effort respiratoire","ok":false,"why":"Le décubitus aggrave la dyspnée ; la position assise ou demi-assise est recommandée."},{"t":"Bêtabloquant IV pour ralentir la fréquence cardiaque","ok":false,"why":"Le bêtabloquant n'est jamais introduit en pleine poussée aiguë."},{"t":"Antibiothérapie probabiliste systématique","ok":false,"why":"Rien n'indique une pneumopathie ; ce n'est pas le traitement de l'OAP."},{"t":"Remplissage vasculaire rapide","ok":false,"why":"Un remplissage serait délétère en cas de surcharge hydrosodée avec pressions de remplissage élevées."}],"explanation":"Au domicile, la prise en charge repose sur la position demi-assise et le furosémide IV 1 mg/kg, avec appel du Samu et hospitalisation."},"reveal":"Le furosémide IV est administré et Mme L. est transportée aux urgences.","src":"p. 485"},{"id":"234-case-02-s03","phase":1,"narrative":"Aux urgences, un bilan est réalisé sans retarder le traitement : ECG, gaz du sang, radiographie thoracique, biologie, dosage des peptides natriurétiques et de la troponine, échocardiographie.","question":{"type":"QROC","question":"Quel type d'anomalie gazométrique est classiquement retrouvé au cours d'un OAP cardiogénique ?","answer":"Hypoxie avec hypocapnie","accept":["hypoxémie-hypocapnie","hypoxie-hypocapnie"],"keywords":["hypoxie","hypocapnie"],"explanation":"Les gaz du sang montrent classiquement une hypoxie associée à une hypocapnie au cours de l'OAP."},"reveal":"Les gaz du sang confirment une hypoxie avec hypocapnie, cohérente avec l'OAP.","src":"p. 472"},{"id":"234-case-02-s04","phase":1,"narrative":"Les résultats reviennent : NT-proBNP très élevé à 6 200 pg/mL, troponine modérément augmentée, radiographie montrant des opacités périhilaires floues bilatérales.","question":{"type":"QRM","stem":"Comment interpréter ces résultats chez Mme L. ?","options":[{"t":"Le NT-proBNP très élevé conforte fortement l'origine cardiogénique de la dyspnée","ok":true,"why":"Des valeurs très élevées de peptides natriurétiques orientent fortement vers l'origine cardiaque."},{"t":"L'élévation modérée de la troponine affirme à elle seule un syndrome coronarien aigu associé","ok":false,"why":"Une élévation modérée de troponine au cours de l'OAP n'implique pas forcément un SCA associé."},{"t":"Les opacités périhilaires bilatérales sont compatibles avec un OAP de survenue brutale","ok":true,"why":"Des opacités périhilaires floues bilatérales sont décrites en cas de survenue brutale de l'OAP."},{"t":"Un NT-proBNP aussi élevé élimine formellement une pneumopathie associée","ok":false,"why":"Un taux élevé oriente vers l'origine cardiaque mais ne permet pas d'exclure une pathologie associée."},{"t":"Ces résultats permettent de retenir le diagnostic d'OAP cardiogénique comme hypothèse principale","ok":true,"why":"L'ensemble clinique, biologique et radiologique converge vers l'OAP cardiogénique."}],"explanation":"Un NT-proBNP très élevé conforte l'origine cardiogénique ; une troponine modérément augmentée ne signe pas forcément un SCA, mais doit rester surveillée."},"reveal":"L'échocardiographie confirme une hypokinésie étendue avec FEVG estimée à 25 %.","src":"p. 472-473"},{"id":"234-case-02-s05","phase":2,"narrative":"Avant de conclure, l'interne de garde reprend systématiquement les diagnostics différentiels d'une détresse respiratoire aiguë chez Mme L., qui n'a pas de fièvre ni de foyer auscultatoire net, et pas de facteur de risque thromboembolique connu.","question":{"type":"QRM","stem":"Quels arguments permettent d'écarter les principaux diagnostics différentiels chez Mme L. ?","options":[{"t":"L'absence de fièvre et de foyer localisé rend une pneumopathie infectieuse moins probable","ok":true,"why":"La pneumopathie s'accompagne classiquement de fièvre et d'un foyer localisé avec opacité systématisée."},{"t":"L'absence de terrain thromboembolique connu rend l'embolie pulmonaire moins probable, sans l'éliminer formellement","ok":true,"why":"Le contexte à risque est un argument, mais l'EP reste un diagnostic différentiel à garder en tête devant une dyspnée aiguë."},{"t":"L'absence d'antécédent de BPCO ou d'asthme rend ces diagnostics moins probables","ok":true,"why":"L'absence d'antécédents respiratoires chroniques diminue la probabilité de BPCO ou d'asthme comme cause principale."},{"t":"Un NT-proBNP élevé serait attendu de façon similaire dans une pneumopathie","ok":false,"why":"Au contraire, les peptides natriurétiques sont normaux ou peu augmentés en cas de pneumopathie isolée."},{"t":"L'auscultation pulmonaire normale est habituelle en cas d'embolie pulmonaire, contrairement au tableau de Mme L.","ok":true,"why":"L'auscultation est souvent normale dans l'embolie pulmonaire, contrastant avec les crépitants diffus de Mme L."}],"explanation":"L'absence de fièvre, de foyer localisé, de terrain thromboembolique et d'antécédent respiratoire chronique, associée à des crépitants diffus et un NT-proBNP très élevé, oriente vers l'OAP cardiogénique plutôt que vers les diagnostics différentiels classiques."},"reveal":"Le diagnostic d'OAP cardiogénique est retenu comme hypothèse principale, sans écarter formellement un événement coronarien associé.","src":"p. 472"},{"id":"234-case-02-s06","phase":2,"narrative":"En reprenant l'ECG initial, l'équipe note un sus-décalage du segment ST en territoire antérieur.","question":{"type":"QROC","question":"Quelle lettre de l'acronyme CHAMPIT correspond à la cause retrouvée ici (syndrome coronarien aigu) ?","answer":"C","accept":["C, coronaire","coronaire"],"keywords":["C","coronaire"],"explanation":"Le C de CHAMPIT correspond au syndrome coronarien aigu, cause curable à rechercher systématiquement devant une IC aiguë."},"reveal":"Un syndrome coronarien aigu ST+ est retenu comme facteur déclenchant : une double prise en charge (OAP et SCA) est nécessaire.","src":"p. 486"},{"id":"234-case-02-s07","phase":3,"narrative":"PA à 118/76 mmHg, le traitement de l'OAP est poursuivi en soins intensifs en parallèle de la prise en charge du syndrome coronarien aigu.","question":{"type":"QRM","stem":"Quelles mesures thérapeutiques sont appropriées à ce stade ?","options":[{"t":"Furosémide IV 1 mg/kg, à adapter ensuite selon la diurèse","ok":true,"why":"C'est le traitement diurétique de référence de l'OAP à l'hôpital."},{"t":"Dérivés nitrés IV (trinitrine) en l'adaptant à la pression artérielle, puisque la PAS est > 110 mmHg","ok":true,"why":"Les dérivés nitrés IV sont indiqués si la PAS est supérieure à 110 mmHg, ce qui est le cas ici."},{"t":"Introduction immédiate d'un bêtabloquant pour protéger le myocarde","ok":false,"why":"Le bêtabloquant n'est jamais débuté en pleine poussée d'IC aiguë."},{"t":"Oxygénothérapie pour maintenir une SpO2 supérieure à 90 %","ok":true,"why":"L'objectif d'oxygénothérapie recommandé est une SpO2 > 90 %."},{"t":"Morphine IV systématique dès l'admission, indépendamment de la douleur ou de l'anxiété","ok":false,"why":"La morphine n'est pas systématique ; elle est réservée à l'anxiété importante non contrôlée ou à la douleur thoracique."}],"explanation":"Le traitement associe furosémide IV, dérivés nitrés IV si la PAS le permet et oxygénothérapie ciblée, sans introduire de bêtabloquant ni de morphine systématique."},"reveal":"Mme L. bénéficie en parallèle d'une angioplastie en urgence sur l'IVA proximale.","src":"p. 485"},{"id":"234-case-02-s08","phase":3,"narrative":"L'équipe prescrit une anticoagulation préventive systématique en plus du traitement de l'OAP.","question":{"type":"QRU","stem":"Quelle est la molécule habituellement utilisée pour cette anticoagulation préventive systématique au cours d'un OAP hospitalisé ?","options":[{"t":"Une héparine de bas poids moléculaire (HBPM)","ok":true,"why":"Le chapitre préconise une anticoagulation préventive systématique par HBPM au cours de l'OAP hospitalisé."},{"t":"Un antivitamine K","ok":false,"why":"Non recommandé en préventif systématique dans ce contexte."},{"t":"Un anticoagulant oral direct à dose curative","ok":false,"why":"Il s'agit d'une anticoagulation préventive, pas curative, sauf indication spécifique associée (FA, thrombus)."},{"t":"De l'aspirine seule","ok":false,"why":"L'aspirine est un antiagrégant, pas un anticoagulant préventif de maladie thromboembolique veineuse."},{"t":"Aucune anticoagulation n'est nécessaire chez un patient alité pour OAP","ok":false,"why":"L'anticoagulation préventive par HBPM est systématique en l'absence de contre-indication."}],"explanation":"Une anticoagulation préventive par HBPM est systématique au cours d'un OAP hospitalisé."},"reveal":"L'HBPM préventive est instaurée, en l'absence de contre-indication.","src":"p. 485"},{"id":"234-case-02-s09","phase":4,"narrative":"Douze heures après l'admission, malgré le traitement médicamenteux bien conduit, Mme L. reste polypnéique à 28/min avec une SpO2 à 89 % sous oxygène au masque.","question":{"type":"QRM","stem":"Quelle escalade thérapeutique est justifiée devant cet échec du traitement médicamenteux ?","options":[{"t":"Mise en route d'une ventilation non invasive de type CPAP","ok":true,"why":"La CPAP est indiquée en cas d'échec du traitement médicamenteux, avec FR > 25/min et SpO2 < 90 %."},{"t":"Augmenter encore la dose de dérivés nitrés au-delà des recommandations sans limite de surveillance","ok":false,"why":"Les dérivés nitrés doivent être adaptés à la pression artérielle, pas augmentés sans surveillance."},{"t":"Intubation trachéale d'emblée sans essai de CPAP","ok":false,"why":"L'intubation est réservée au dernier recours, en cas de persistance de la détresse malgré la CPAP."},{"t":"Réévaluer la réponse clinique après la CPAP avant de décider d'une éventuelle intubation","ok":true,"why":"L'intubation est décidée en cas de persistance des signes de détresse et d'épuisement respiratoire après la CPAP."},{"t":"Arrêter le furosémide car son efficacité est jugée insuffisante","ok":false,"why":"Rien n'indique d'arrêter le diurétique ; il reste poursuivi et adapté à la diurèse."}],"explanation":"En cas d'échec du traitement médicamenteux (FR > 25/min, SpO2 < 90 %), la CPAP est proposée ; l'intubation reste le dernier recours si la détresse persiste."},"reveal":"La CPAP est débutée, avec une amélioration initiale de la saturation.","src":"p. 485"},{"id":"234-case-02-s10","phase":4,"narrative":"Quelques heures plus tard, malgré la CPAP, la pression artérielle de Mme L. chute à 82/54 mmHg, avec extrémités froides et marbrées, oligurie et confusion débutante. Elle est déjà sous bêtabloquant au long cours pour son hypertension.","question":{"type":"QRM","stem":"Quelle prise en charge est adaptée à ce tableau de choc cardiogénique ?","options":[{"t":"Confirmer le bas débit par échocardiographie et débuter un monitorage invasif de la pression artérielle","ok":true,"why":"Le diagnostic de choc cardiogénique associe critères cliniques et preuve échographique de bas débit ; un monitorage invasif est recommandé."},{"t":"Privilégier un inhibiteur des phosphodiestérases (milrinone) plutôt que la dobutamine, du fait du bêtabloquant en cours","ok":true,"why":"Chez un patient sous bêtabloquant, un inhibiteur des phosphodiestérases est préféré à la dobutamine dont l'effet peut être atténué."},{"t":"Poursuivre la dobutamine en 1re intention sans tenir compte du bêtabloquant","ok":false,"why":"Chez un patient sous bêtabloquant, la dobutamine est moins adaptée : on privilégie un inhibiteur des phosphodiestérases."},{"t":"Mettre en place une sonde urinaire pour surveiller la diurèse","ok":true,"why":"La sonde urinaire systématique fait partie de la prise en charge du choc cardiogénique."},{"t":"Introduire un IEC en urgence pour soutenir la fonction cardiaque","ok":false,"why":"Un bloqueur du SRA serait délétère dans ce contexte hypotensif ; il n'a pas sa place à ce stade."}],"explanation":"Le choc cardiogénique associe hypotension, hypoperfusion périphérique et bas débit échographique ; chez un patient sous bêtabloquant, un inhibiteur des phosphodiestérases est préféré à la dobutamine, avec monitorage invasif et sonde urinaire."},"reveal":"Sous milrinone, la pression artérielle se stabilise progressivement en 48 heures.","src":"p. 486"},{"id":"234-case-02-s11","phase":4,"narrative":"Après une semaine en soins intensifs, Mme L. peut être sevrée des inotropes et son état se stabilise, avec une FEVG en légère amélioration à 32 % sous traitement optimal.","question":{"type":"OPEN","prompt":"Résumez la démarche étiologique globale qui a permis d'identifier et de traiter la cause du tableau de Mme L., en citant l'acronyme utilisé par le chapitre pour les causes curables d'IC aiguë.","rubric":[{"point":"Citer l'acronyme CHAMPIT comme cadre de recherche systématique des causes curables","weight":2},{"point":"Identifier la cause retrouvée chez Mme L. : syndrome coronarien aigu (C de CHAMPIT)","weight":2},{"point":"Mentionner la double prise en charge nécessaire (traitement de l'OAP/choc et traitement du SCA)","weight":1}],"model":"Devant tout tableau d'IC aiguë, en particulier un OAP ou un choc cardiogénique, il faut rechercher systématiquement une cause curable selon l'acronyme CHAMPIT (Coronaire, Hypertensive, Arythmie, Mécanique, Pulmonaire, Infection, Tamponnade). Chez Mme L., la cause retrouvée était coronarienne (C), avec un syndrome coronarien aigu ST+ ayant nécessité une double prise en charge : traitement symptomatique de l'OAP puis du choc cardiogénique, et revascularisation en urgence de la lésion coronarienne responsable.","explanation":"L'acronyme CHAMPIT structure la recherche systématique d'une cause curable devant toute décompensation cardiaque aiguë."},"reveal":"Mme L. sort après trois semaines d'hospitalisation, avec un traitement de fond de l'IC à FE diminuée optimisé et un suivi cardiologique rapproché.","src":"p. 486"}]},{"id":"234-case-03","title":"M. D., 79 ans, essoufflement progressif et œdèmes","rank":"B","summary":"Homme de 79 ans, hypertendu et obèse, présentant une dyspnée d'effort progressive : diagnostic d'IC à fraction d'éjection préservée, prise en charge selon les 7 axes du traitement et suivi des comorbidités.","difficulty":2,"timeline":["Consultation de suivi","Bilan diagnostique","Diagnostic d'IC à FE préservée","Prise en charge thérapeutique","Suivi et comorbidités"],"steps":[{"id":"234-case-03-s01","phase":0,"narrative":"M. D., 79 ans, hypertendu de longue date, obèse (IMC 32), consulte son médecin traitant pour un essoufflement à l'effort apparu progressivement depuis plusieurs mois, avec quelques épisodes de gonflement des chevilles en fin de journée. Il n'a pas d'antécédent coronarien connu.","question":{"type":"QRM","stem":"Quels éléments du terrain de M. D. sont classiquement associés à l'insuffisance cardiaque à fraction d'éjection préservée ?","options":[{"t":"L'âge avancé","ok":true,"why":"L'IC à FE préservée touche surtout le sujet âgé."},{"t":"L'hypertension artérielle ancienne","ok":true,"why":"L'HTA est volontiers associée à l'IC à FE préservée, par hypertrophie et fibrose du VG."},{"t":"L'obésité","ok":true,"why":"L'obésité est un facteur associé fréquemment cité pour l'IC à FE préservée."},{"t":"Le sexe masculin, qui est le principal facteur de risque de cette forme d'IC","ok":false,"why":"Le chapitre indique au contraire que l'IC à FE préservée touche surtout la femme âgée."},{"t":"L'absence de tout facteur de risque cardiovasculaire","ok":false,"why":"Le terrain de M. D. comporte au contraire plusieurs facteurs de risque (âge, HTA, obésité)."}],"explanation":"L'IC à FE préservée est plus fréquente chez la femme âgée, mais l'âge avancé, l'HTA et l'obésité restent des facteurs de risque classiques, présents chez M. D."},"reveal":"Le médecin décide d'approfondir l'examen clinique.","src":"p. 473-474"},{"id":"234-case-03-s02","phase":0,"narrative":"Examen clinique : PA 152/88 mmHg, FC 84/min régulière, auscultation pulmonaire normale, discrets œdèmes des chevilles, pas de turgescence jugulaire.","question":{"type":"QRU","stem":"Quelle est la meilleure interprétation de cet examen clinique relativement pauvre ?","options":[{"t":"Un examen pauvre n'élimine pas le diagnostic d'IC, dont la sensibilité clinique est limitée","ok":true,"why":"Le chapitre insiste sur le fait que les signes physiques manquent de sensibilité, en particulier sous traitement ou aux stades précoces."},{"t":"Un examen normal élimine formellement une IC à FE préservée","ok":false,"why":"Ce n'est pas exact : le diagnostic d'IC à FE préservée repose sur un faisceau d'arguments, pas seulement sur l'examen clinique."},{"t":"Seule la présence d'une turgescence jugulaire permettrait de poursuivre les investigations","ok":false,"why":"L'absence de turgescence jugulaire ne suffit pas à écarter le diagnostic."},{"t":"L'absence de crépitants élimine toute possibilité de rétention hydrosodée","ok":false,"why":"Les œdèmes des chevilles témoignent déjà d'une possible rétention hydrosodée malgré une auscultation pulmonaire normale."},{"t":"Il faut attendre l'apparition de signes cliniques plus marqués avant tout bilan complémentaire","ok":false,"why":"Au contraire, un bilan complémentaire (peptides natriurétiques, ETT) est justifié dès la suspicion clinique."}],"explanation":"Le chapitre rappelle que le diagnostic clinique de l'IC est difficile car les signes physiques manquent de sensibilité ; un bilan complémentaire reste indiqué."},"reveal":"Un dosage du NT-proBNP et une échocardiographie sont prescrits.","src":"p. 458"},{"id":"234-case-03-s03","phase":1,"narrative":"Le NT-proBNP revient à 210 pg/mL (au-dessus du seuil de 125 pg/mL) et l'échocardiographie transthoracique montre une fraction d'éjection à 58 %, avec une hypertrophie ventriculaire gauche modérée et une dilatation de l'oreillette gauche.","question":{"type":"QROC","question":"Comment qualifie-t-on l'IC de M. D. en fonction de la FEVG mesurée à 58 % ?","answer":"IC à fraction d'éjection préservée","accept":["IC à FE préservée","FE préservée"],"keywords":["FE préservée","58"],"explanation":"Une FEVG > 50 % correspond à l'IC à fraction d'éjection préservée."},"reveal":"Le dossier est complété pour confirmer formellement le diagnostic d'IC à FE préservée.","src":"p. 461, 473-474"},{"id":"234-case-03-s04","phase":1,"narrative":"Le cardiologue reprend l'ensemble des critères diagnostiques réunis chez M. D.","question":{"type":"QRM","stem":"Quels éléments permettent de retenir le diagnostic d'IC à fraction d'éjection préservée chez M. D. ?","options":[{"t":"Présence de symptômes et de signes évocateurs d'IC","ok":true,"why":"C'est le premier élément nécessaire au diagnostic."},{"t":"FEVG normale (58 %) sans valvulopathie significative ni trouble du rythme majeur","ok":true,"why":"La fonction systolique doit être normale et les autres causes de symptômes écartées."},{"t":"Élévation du NT-proBNP au-dessus du seuil d'exclusion","ok":true,"why":"L'élévation des peptides natriurétiques fait partie des critères diagnostiques."},{"t":"Présence d'une hypertrophie ventriculaire gauche et d'une dilatation de l'oreillette gauche","ok":true,"why":"Ce sont des arguments de pressions de remplissage élevées ou de trouble du remplissage, cités parmi les critères diagnostiques."},{"t":"Le diagnostic nécessite obligatoirement une FEVG inférieure à 40 % pour être retenu","ok":false,"why":"C'est au contraire le seuil de l'IC à FE diminuée ; ici la FEVG est de 58 %, préservée."}],"explanation":"Le diagnostic d'IC à FE préservée réunit symptômes/signes, FEVG normale sans autre cause, BNP élevé et argument de trouble du remplissage (HVG ou dilatation de l'OG)."},"reveal":"Le diagnostic d'IC à fraction d'éjection préservée est formellement retenu.","src":"p. 473-474"},{"id":"234-case-03-s05","phase":2,"narrative":"M. D. a également un léger tabagisme ancien sevré et se plaint parfois d'une toux sèche matinale, faisant évoquer par son médecin traitant une possible bronchopneumopathie chronique associée.","question":{"type":"OPEN","prompt":"Expliquez pourquoi, chez M. D., il ne faut pas se contenter d'attribuer la dyspnée à une possible bronchopneumopathie chronique sans explorer l'hypothèse cardiaque, et quel piège classique du chapitre ce raisonnement illustre.","rubric":[{"point":"Rappeler que la dyspnée d'effort est peu spécifique et peut coexister avec plusieurs causes","weight":1},{"point":"Souligner que les peptides natriurétiques élevés et l'ETT anormale orientent vers une cause cardiaque, indépendamment du tabagisme","weight":2},{"point":"Citer le piège de l'asthme cardiaque/dyspnée d'origine cardiaque prise à tort pour une cause pulmonaire","weight":2}],"model":"La dyspnée d'effort est un symptôme peu spécifique, qui peut avoir plusieurs causes chez un même patient. Chez M. D., le NT-proBNP élevé et l'échocardiographie anormale (HVG, dilatation de l'oreillette gauche) sont des arguments solides en faveur d'une cause cardiaque, qui ne doivent pas être négligés au seul prétexte d'un tabagisme ancien. Le chapitre met en garde contre ce type de piège, en rappelant qu'une dyspnée d'origine cardiaque (notamment l'asthme cardiaque) peut être prise à tort pour une pathologie respiratoire chronique.","explanation":"Ne pas laisser un facteur de risque respiratoire masquer une cause cardiaque documentée par les examens complémentaires."},"reveal":"Les explorations fonctionnelles respiratoires demandées restent normales, confortant l'origine cardiaque prédominante de la dyspnée.","src":"p. 461-462"},{"id":"234-case-03-s06","phase":2,"narrative":"Le diagnostic d'IC à FE préservée est confirmé en réunion de staff, en l'absence de valvulopathie ou de trouble du rythme significatif.","question":{"type":"QRU","stem":"Quelle proportion des cas d'insuffisance cardiaque l'IC à FE préservée représente-t-elle selon le chapitre ?","options":[{"t":"Au moins la moitié des cas","ok":true,"why":"Le chapitre indique que l'IC à FE préservée représente au moins la moitié des cas d'IC."},{"t":"Moins de 10 % des cas","ok":false,"why":"C'est très inférieur à la proportion réelle rapportée."},{"t":"Environ un quart des cas seulement","ok":false,"why":"Sous-estime la proportion rapportée dans le chapitre."},{"t":"La quasi-totalité des cas d'IC","ok":false,"why":"Surestime la proportion ; l'IC à FE diminuée reste également fréquente."},{"t":"Une proportion non précisée par le chapitre","ok":false,"why":"Le chapitre donne explicitement cette proportion."}],"explanation":"L'IC à FE préservée représente au moins la moitié des cas d'IC, surtout chez la femme âgée."},"reveal":"Le cardiologue explique à M. D. que cette forme d'IC est très fréquente chez les patients de son âge.","src":"p. 473-474"},{"id":"234-case-03-s07","phase":3,"narrative":"Le traitement de fond de l'IC à FE préservée est organisé pour M. D.","question":{"type":"QRM","stem":"Quelles mesures thérapeutiques sont adaptées au traitement de fond de M. D. ?","options":[{"t":"Introduction d'une gliflozine (dapagliflozine ou empagliflozine)","ok":true,"why":"Les gliflozines sont la classe la mieux validée (I, A) dans l'IC à FE préservée."},{"t":"Bloqueur du SRA (IEC ou ARA2) pour le contrôle tensionnel","ok":true,"why":"Le contrôle de la pression artérielle par bloqueur du SRA fait partie de l'axe « pression artérielle » du traitement."},{"t":"Diurétique de l'anse ou thiazidique en cas de signes congestifs, avec surveillance rénale","ok":true,"why":"Le diurétique est recommandé en présence de manifestations congestives, avec surveillance de la fonction rénale."},{"t":"Repos strict au lit pour limiter la dyspnée d'effort","ok":false,"why":"Le repos strict est délétère ; une activité physique adaptée régulière est au contraire recommandée."},{"t":"Vérapamil en 1re intention pour ralentir la fréquence cardiaque","ok":false,"why":"Bien qu'un inhibiteur calcique bradycardisant puisse être discuté selon le contexte, le vérapamil n'est pas cité comme traitement de 1re intention ici et son usage doit rester prudent."}],"explanation":"Le traitement de M. D. associe gliflozine, bloqueur du SRA pour la pression artérielle, diurétique si signes congestifs et maintien d'une activité physique adaptée."},"reveal":"Le traitement est initié avec bonne tolérance clinique.","src":"p. 483-484"},{"id":"234-case-03-s08","phase":3,"narrative":"Lors du bilan initial, une fibrillation atriale paroxystique est découverte sur un enregistrement Holter, et une hémoglobine glyquée légèrement élevée oriente vers un diabète débutant.","question":{"type":"QRM","stem":"Comment intégrer ces comorbidités dans la prise en charge de M. D. ?","options":[{"t":"La fibrillation atriale doit être prise en charge car elle fait partie des comorbidités cardiaques à traiter dans l'IC à FE préservée","ok":true,"why":"L'axe « comorbidités » du traitement inclut explicitement la fibrillation atriale."},{"t":"Le diabète débutant doit également être pris en charge, en cohérence avec l'axe comorbidités","ok":true,"why":"Les comorbidités non cardiaques comme le diabète doivent être traitées, selon le même axe du traitement."},{"t":"Un score de risque embolique doit être calculé devant cette FA","ok":true,"why":"Le chapitre recommande le calcul du score CHA2DS2-VA pour évaluer le risque embolique en cas de FA."},{"t":"Ces comorbidités n'ont aucune influence sur le pronostic de l'IC de M. D.","ok":false,"why":"Au contraire, les comorbidités cardiaques et non cardiaques aggravent le pronostic et compliquent la tolérance des traitements."},{"t":"Il faut différer la prise en charge de ces comorbidités jusqu'à la stabilisation complète de l'IC","ok":false,"why":"Ces comorbidités doivent être prises en charge en parallèle, et non différées."}],"explanation":"Le traitement de l'IC à FE préservée intègre systématiquement la prise en charge des comorbidités cardiaques (dont la FA, avec évaluation du risque embolique) et non cardiaques (comme le diabète)."},"reveal":"Un traitement anticoagulant est discuté selon le score de risque, et une prise en charge diététique du diabète débutant est mise en place.","src":"p. 481, 484"},{"id":"234-case-03-s09","phase":4,"narrative":"Trois mois plus tard, M. D. revient en consultation de suivi, se disant globalement stable, sans prise de poids notable.","question":{"type":"QROC","question":"Quel est l'objectif de régime sodé en grammes de sel par jour recommandé chez un patient insuffisant cardiaque comme M. D. ?","answer":"5 à 6 g/j","accept":["5-6 g","5 à 6 grammes par jour"],"keywords":["5","6","g/j"],"explanation":"Le régime pauvre en sel vise à ne pas dépasser 5 à 6 g de sel par jour."},"reveal":"M. D. confirme suivre ce régime, avec l'aide d'une diététicienne pour varier les assaisonnements.","src":"p. 476"},{"id":"234-case-03-s10","phase":4,"narrative":"Avant de clore la consultation, le cardiologue reprend avec M. D. les signes qui doivent l'alerter à domicile.","question":{"type":"QRM","stem":"Quels signes doivent inciter M. D. à consulter rapidement, selon l'éducation thérapeutique délivrée dans l'IC ?","options":[{"t":"Une prise de poids de 2 à 3 kg en quelques jours","ok":true,"why":"C'est le signe d'alerte cité pour dépister précocement une rétention hydrosodée."},{"t":"L'apparition d'une orthopnée","ok":true,"why":"L'apparition d'une orthopnée est un signe d'alerte de décompensation cité par le chapitre."},{"t":"L'apparition d'œdèmes des membres inférieurs ou d'un météorisme abdominal","ok":true,"why":"Ce sont des signes d'alerte explicitement mentionnés."},{"t":"Une légère perte de poids progressive sans œdème, sans gravité particulière","ok":false,"why":"Au contraire, une perte de poids progressive sans œdème traduit une dénutrition, signe de gravité et de mauvais pronostic."},{"t":"Une reprise d'une activité physique régulière et modérée","ok":false,"why":"C'est au contraire une mesure recommandée, pas un signe d'alerte."}],"explanation":"Les signes d'alerte à connaître par le patient sont la prise de poids rapide, l'aggravation de la dyspnée, l'apparition d'une orthopnée, d'œdèmes ou d'un météorisme abdominal ; une perte de poids progressive sans œdème doit aussi alerter, mais dans le sens d'une dénutrition."},"reveal":"M. D. repart avec un carnet de suivi de son poids et un rendez-vous de contrôle à 6 mois, avec une orientation possible vers un programme de télésurveillance.","src":"p. 476, 484"}]}],"ecg":{"data":[{"id":"234-ecg-01","title":"Séquelle d'infarctus antéroseptal (ondes Q de nécrose)","rank":"A","objective":"234-obj-16","ecg":{"rhythm":"sinus","rate":78,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":30,"qWaves":["V1","V2","V3"],"lowVoltage":false,"rsRatioV1":0.15,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["V1","V2","V3"],"peaked":false,"flat":false,"amp":0.2},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Ondes Q de nécrose en antéroseptal, séquelles d'un infarctus ancien, orientant vers une étiologie ischémique de l'insuffisance cardiaque."},"findings":["Rythme sinusal régulier","Ondes Q larges et profondes en V1-V3 (territoire antéroseptal)","Ondes T négatives séquellaires dans le même territoire","QRS de durée normale, pas de bloc de branche"],"diagnosis":"Séquelle d'infarctus du myocarde antéroseptal","teaching":"md L'ECG est peu contributif au diagnostic positif d'insuffisance cardiaque, mais il peut orienter vers une étiologie : des ondes Q de nécrose témoignent d'un infarctus du myocarde ancien, à rechercher systématiquement devant une insuffisance cardiaque à FEVG diminuée. Des signes d'hypertrophie atriale ou ventriculaire peuvent aussi être notés selon l'étiologie.\n\n**Ce qu'il faut faire devant ces ondes Q** : évoquer une cardiopathie ischémique comme cause de l'insuffisance cardiaque et orienter le bilan étiologique vers une coronarographie ou une imagerie de viabilité myocardique.","quiz":{"stem":"Chez un patient suivi pour une insuffisance cardiaque à FEVG diminuée, cet ECG montrant des ondes Q en V1-V3 oriente en premier lieu vers quelle étiologie ?","options":["Cardiopathie ischémique (séquelle d'infarctus)","Cardiomyopathie hypertrophique","Cardiopathie hypertensive","Myocardite virale récente"],"correct":0},"src":"p. 463-464"},{"id":"234-ecg-02","title":"Bloc de branche gauche avec QRS élargi (indication de resynchronisation)","rank":"A","objective":"234-obj-20","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.1,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.16,"bbb":"lbbb","lvh":false,"rvh":false,"delta":false,"axis":-30,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.05,"pathologicR":[]},"st":{"elev":{},"dep":{"V5":1,"V6":1},"shape":"downsloping"},"t":{"inverted":["I","aVL","V5","V6"],"peaked":false,"flat":false,"amp":0.25},"qt":0.46,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Bloc de branche gauche complet avec QRS ≥ 150 ms chez un insuffisant cardiaque à FEVG diminuée : critère électrique le plus favorable à une resynchronisation biventriculaire."},"findings":["Rythme sinusal régulier","QRS élargi ≥ 150 ms, morphologie de bloc de branche gauche complet","Ondes T négatives en I, aVL, V5-V6 (discordance secondaire au trouble de conduction)","Pas d'onde Q pathologique"],"diagnosis":"Bloc de branche gauche complet à QRS très élargi","teaching":"md L'allongement de la durée des QRS au-delà de 120 ms, en particulier en cas de bloc de branche gauche, est un élément ECG important à rechercher chez tout insuffisant cardiaque à FEVG diminuée, en raison de ses implications thérapeutiques.\n\n**Ce qu'il faut retenir** : la resynchronisation ventriculaire par stimulateur biventriculaire est envisagée chez un patient en classe NYHA II à IV, avec une FEVG ≤ 35 % et un QRS ≥ 130 ms. Le traitement est d'autant plus efficace qu'il s'agit d'un bloc de branche gauche, avec un QRS ≥ 150 ms et une cardiopathie non ischémique. Un QRS élargi (> 120 ms, bloc de branche gauche) est également un facteur pronostique péjoratif.","quiz":{"stem":"Chez un insuffisant cardiaque en classe NYHA III avec FEVG à 30 %, quel critère ECG rend une resynchronisation biventriculaire particulièrement efficace ?","options":["Bloc de branche gauche avec QRS ≥ 150 ms","Bloc de branche droit avec QRS à 110 ms","Un PR court avec préexcitation","Une fibrillation atriale rapide isolée"],"correct":0},"src":"p. 463, 481-482"}],"method":""},"echo":{"data":[{"id":"234-echo-01","title":"Cardiomyopathie dilatée avec insuffisance cardiaque à FEVG diminuée","rank":"A","objective":"234-obj-13","schematic":"a4c","findings":["Ventricule gauche dilaté, volumes télédiastolique et télésystolique augmentés","Cinétique globale hypokinétique","Fraction d'éjection ventriculaire gauche effondrée","Oreillette gauche souvent dilatée","Pas d'hypertrophie pariétale majeure"],"measures":[{"label":"FEVG (méthode de Simpson)","severe":"< 40 %","rank":"A"},{"label":"Volume télédiastolique du VG","severe":"augmenté","rank":"B"},{"label":"Volume télésystolique du VG","severe":"augmenté","rank":"B"}],"description":"md L'échocardiographie transthoracique couplée au doppler est l'examen clé indispensable devant une insuffisance cardiaque ou une suspicion d'insuffisance cardiaque. Elle permet de mesurer les volumes télédiastolique (VTD) et télésystolique (VTS) du ventricule gauche par la méthode de Simpson, d'en déduire la FEVG = (VTD − VTS)/VTD (normale > 50-60 %), et ainsi de classer l'insuffisance cardiaque selon la FEVG (< 40 %, 41-49 %, > 50 %).\n\nDans la cardiomyopathie dilatée, le ventricule gauche est dilaté et globalement hypokinétique, avec une FEVG basse. L'échocardiographie recherche aussi une anomalie de la cinétique segmentaire (en faveur d'une origine ischémique), une valvulopathie organique associée, et évalue le ventricule droit, la taille des atriums, la veine cave inférieure et les pressions de remplissage.","quiz":{"stem":"Quel seuil de FEVG définit une insuffisance cardiaque à fraction d'éjection diminuée ?","options":["FEVG < 40 %","FEVG entre 41 et 49 %","FEVG > 50 %","FEVG > 60 %"],"correct":0},"src":"p. 436-437, 466-467"},{"id":"234-echo-02","title":"Insuffisance cardiaque à FEVG préservée : hypertrophie et dilatation de l'oreillette gauche","rank":"A","objective":"234-obj-08","schematic":"a4c","findings":["Fonction systolique du ventricule gauche normale (FEVG > 50 %)","Hypertrophie ventriculaire gauche (épaississement pariétal)","Dilatation de l'oreillette gauche","Arguments pour une élévation des pressions de remplissage","Absence de valvulopathie significative, de trouble du rythme/conduction ou de pathologie péricardique expliquant les symptômes"],"measures":[{"label":"Masse ventriculaire gauche indexée (homme)","severe":"> 115 g/m²","rank":"B"},{"label":"Masse ventriculaire gauche indexée (femme)","severe":"> 95 g/m²","rank":"B"},{"label":"Volume de l'oreillette gauche indexé","severe":"> 34 mL/m²","rank":"B"},{"label":"FEVG","severe":"> 50 %","rank":"A"}],"description":"md L'insuffisance cardiaque à FEVG préservée concerne au moins la moitié des insuffisants cardiaques, surtout des femmes et des sujets âgés. On l'évoque devant des symptômes/signes d'insuffisance cardiaque, une fonction systolique conservée à l'échographie cardiaque (FEVG > 50 %), sans autre cause évidente (valve significativement atteinte, arythmie/trouble conductif, atteinte péricardique), une élévation du BNP/NT-proBNP, et un ou plusieurs arguments échographiques d'élévation des pressions de remplissage : parois ventriculaires épaissies (masse VG indexée supérieure à 115 g/m² chez l'homme, 95 g/m² chez la femme) ou oreillette gauche dilatée (volume indexé supérieur à 34 mL/m²).","quiz":{"stem":"Quel argument échocardiographique soutient le diagnostic d'insuffisance cardiaque à FEVG préservée chez une patiente dyspnéique avec BNP élevé et FEVG à 60 % ?","options":["Dilatation de l'oreillette gauche (volume indexé > 34 mL/m²)","Ventricule gauche dilaté et hypokinétique","Épanchement péricardique abondant","Rétrécissement mitral serré"],"correct":0},"src":"p. 473-474"},{"id":"234-echo-03","title":"Cardiomyopathie hypertrophique avec hypertrophie septale asymétrique","rank":"B","objective":"234-obj-16","schematic":"plax","findings":["Hypertrophie pariétale anormale, le plus souvent asymétrique et prédominant sur le septum interventriculaire","Cavité ventriculaire gauche de taille normale ou petite","Fraction d'éjection conservée","Trouble du remplissage ventriculaire","Parfois obstruction sous-aortique avec gradient de pression VG-aorte"],"measures":[],"description":"md Une hypertrophie pariétale à prédominance septale (hypertrophie asymétrique du septum interventriculaire) à l'échocardiographie oriente vers une cardiomyopathie hypertrophique, à distinguer de l'hypertrophie plus homogène de la cardiopathie hypertensive.\n\nLa cardiomyopathie hypertrophique associe une cavité ventriculaire gauche de taille normale ou petite, une fraction d'éjection conservée et un trouble du remplissage cardiaque. Dans environ un quart des cas, l'hypertrophie fait saillie dans la chambre de chasse du ventricule gauche et crée une obstruction sous-aortique avec un gradient de pression en systole entre le VG et l'aorte (CMH obstructive). Il s'agit le plus souvent d'une maladie familiale monogénique de transmission autosomique dominante, pouvant se compliquer de mort subite, d'insuffisance cardiaque ou de fibrillation atriale.","quiz":{"stem":"Une hypertrophie pariétale prédominant sur le septum interventriculaire, avec cavité VG de petite taille et FEVG conservée, oriente vers quel diagnostic ?","options":["Cardiomyopathie hypertrophique","Cardiomyopathie dilatée","Insuffisance cardiaque à FEVG diminuée d'origine ischémique","Péricardite constrictive"],"correct":0},"src":"p. 440, 467"}]}});
